use super::{PythonParser, Rule};
use pest::Parser;
use pest::iterators::Pair;
use std::collections::{HashMap, HashSet};
use vybe_ast::*;
use vybe_compiler::primitives::complex;

// ════════════════════════════════════════════════════════════════════════════
// Indentation preprocessor
// ════════════════════════════════════════════════════════════════════════════
// Python uses indentation for blocks. pest cannot track indent state, so we
// insert explicit markers before parsing:
//   ⇥ (U+21E5) = INDENT
//   ⇤ (U+21E4) = DEDENT

/// Update bracket depth for one physical line, skipping string literals.
/// `in_triple` carries an open triple-quoted string across lines (holding its
/// quote char while one is open).
///
/// Brackets and `#` inside a string literal are content, not syntax. Counting
/// them makes logical-line resolution glue unrelated statements together —
/// `s = "{"` would swallow every following line up to the next `}`.
fn scan_line_brackets(line: &str, bracket_depth: &mut i32, in_triple: &mut Option<char>) {
    let b: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if let Some(q) = *in_triple {
            if c == '\\' {
                i += 2;
                continue;
            }
            if c == q && b.get(i + 1) == Some(&q) && b.get(i + 2) == Some(&q) {
                *in_triple = None;
                i += 3;
                continue;
            }
            i += 1;
            continue;
        }
        match c {
            // Rest of the line is a comment.
            '#' => return,
            '(' | '[' | '{' => *bracket_depth += 1,
            ')' | ']' | '}' => *bracket_depth -= 1,
            '\'' | '"' => {
                if b.get(i + 1) == Some(&c) && b.get(i + 2) == Some(&c) {
                    *in_triple = Some(c);
                    i += 3;
                    continue;
                }
                // Single-quoted: consume through the closing quote. An
                // unterminated one just ends at EOL; the grammar reports it.
                i += 1;
                while i < b.len() {
                    if b[i] == '\\' {
                        i += 2;
                        continue;
                    }
                    if b[i] == c {
                        break;
                    }
                    i += 1;
                }
            }
            _ => {}
        }
        i += 1;
    }
}

fn preprocess_indentation(source: &str) -> String {
    // Phase 1: Resolve physical lines into logical lines.
    // Handles explicit continuation (backslash) and implicit continuation (unclosed brackets).
    let mut logical_lines: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut bracket_depth: i32 = 0;
    let mut in_triple: Option<char> = None;

    for line in source.lines() {
        let trimmed = line.trim();

        // During continuation, skip blank/comment lines — but never inside a
        // triple-quoted string, where both are literal content.
        if in_triple.is_none()
            && !current.is_empty()
            && (trimmed.is_empty() || trimmed.starts_with('#'))
        {
            continue;
        }

        let was_in_triple = in_triple.is_some();

        if current.is_empty() {
            current.push_str(line);
        } else if was_in_triple {
            // Inside a triple-quoted string the physical newline and the
            // leading whitespace are literal content — joining with a space
            // would rewrite the value (`print(f"""a\nb""")`).
            current.push('\n');
            current.push_str(line);
        } else {
            // Continuation: join with space + trimmed content
            current.push(' ');
            current.push_str(trimmed);
        }

        scan_line_brackets(line, &mut bracket_depth, &mut in_triple);

        // Explicit continuation: backslash at end of line (string content is
        // not a continuation marker).
        if !was_in_triple && in_triple.is_none() && line.trim_end().ends_with('\\') {
            if let Some(pos) = current.rfind('\\') {
                current.truncate(pos);
            }
            continue;
        }

        // Implicit continuation: unclosed brackets or an open triple-quoted
        // string literal.
        if bracket_depth > 0 || in_triple.is_some() {
            continue;
        }

        logical_lines.push(std::mem::take(&mut current));
        bracket_depth = 0;
    }
    if !current.is_empty() {
        logical_lines.push(current);
    }

    // Phase 2: Process indentation on logical lines
    let mut result = String::with_capacity(source.len() * 2);
    let mut indent_stack: Vec<usize> = vec![0];
    let mut first = true;

    for line in &logical_lines {
        // Count leading spaces (expand tabs to 8)
        let mut indent = 0;
        let mut chars = line.chars().peekable();
        while let Some(&c) = chars.peek() {
            match c {
                ' ' => {
                    indent += 1;
                    chars.next();
                }
                '\t' => {
                    indent += 8 - (indent % 8);
                    chars.next();
                }
                _ => break,
            }
        }

        let rest: String = chars.collect();

        // Skip blank lines and comment-only lines
        let trimmed = rest.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            if !first {
                result.push('\n');
            }
            result.push_str(line);
            first = false;
            continue;
        }

        if !first {
            result.push('\n');
        }
        first = false;

        let current_indent = *indent_stack.last().unwrap();

        if indent > current_indent {
            indent_stack.push(indent);
            result.push('\u{21E5}'); // INDENT
        } else {
            while indent < *indent_stack.last().unwrap() {
                indent_stack.pop();
                result.push('\u{21E4}'); // DEDENT
            }
            // After popping, if indent is above the new top, it's a new block level
            if indent > *indent_stack.last().unwrap() {
                indent_stack.push(indent);
                result.push('\u{21E5}'); // INDENT
            }
        }

        result.push_str(line);
    }

    // Close remaining indents at EOF
    while indent_stack.len() > 1 {
        indent_stack.pop();
        result.push('\n');
        result.push('\u{21E4}');
    }

    result
}

// ════════════════════════════════════════════════════════════════════════════
// Entry point
// ════════════════════════════════════════════════════════════════════════════

/// The text the prelude and core-class GATES are matched against: the source
/// with `#` comments removed.
///
/// ⛔ A gate is `contains("<module>")` over the whole file, and every corpus
/// test opens with `# vybe-test: python/collections_extended/...`. The suite
/// name in that header alone turned the `collections` prelude on: adding the
/// single comment `# collections` to `hello_world.py` cost **0.58s → 2.05s**,
/// and warm mode does not help because the prelude is RE-COMPILED per program
/// even when its parse is cached. String literals are KEPT, so
/// `__import__("collections")` still gates.
fn gate_text(source: &str) -> String {
    let mut out = String::with_capacity(source.len());
    let bytes = source.as_bytes();
    let mut i = 0;
    // `quote` holds the delimiter of the string being scanned, and `triple`
    // whether it was opened with three of them.
    let mut quote: Option<(u8, bool)> = None;
    while i < bytes.len() {
        let c = bytes[i];
        match quote {
            None => {
                if c == b'#' {
                    while i < bytes.len() && bytes[i] != b'\n' {
                        i += 1;
                    }
                    continue;
                }
                if c == b'"' || c == b'\'' {
                    let triple = bytes[i + 1..].starts_with(&[c, c]);
                    quote = Some((c, triple));
                    out.push(c as char);
                    i += if triple { 3 } else { 1 };
                    if triple {
                        out.push(c as char);
                        out.push(c as char);
                    }
                    continue;
                }
            }
            Some((delim, triple)) => {
                if c == b'\\' {
                    out.push(c as char);
                    if i + 1 < bytes.len() {
                        out.push(bytes[i + 1] as char);
                    }
                    i += 2;
                    continue;
                }
                if c == delim && (!triple || bytes[i..].starts_with(&[c, c, c])) {
                    quote = None;
                    out.push(c as char);
                    i += if triple { 3 } else { 1 };
                    if triple {
                        out.push(c as char);
                        out.push(c as char);
                    }
                    continue;
                }
            }
        }
        out.push(c as char);
        i += 1;
    }
    out
}

pub fn parse(source: &str) -> Result<Module, String> {
    // Every registry this walk keeps, created here and dropped when `parse`
    // returns — including on the `?` paths below. Nothing survives to be read
    // by the next program compiled on this thread.
    let mut __w_owned = PyWalker::default();
    let __w = &mut __w_owned;
    // Gates match the comment-stripped text; the PARSE still gets the real
    // source, whose comments the indentation preprocessor depends on.
    let gate = gate_text(source);
    // ⛔ The `core_classes` names are registered BEFORE the source walk, not
    // when their declarations are spliced in afterwards. The walker decides how
    // to lower `a = IPv4Address(…)` — and every later `a.attr` — from
    // `py_defined_classes` AT THE MOMENT IT SEES THE LINE, so registering at
    // splice time is too late: construction compiled as a plain call, the
    // instance was never tracked, and every attribute read on it threw.
    // ⛔ THE TREE MUST EXIST BEFORE THE WALK ASKS IT. `register_tree` is a
    // plugin hook the compiler fires on its own schedule, which is AFTER
    // `parse`; a walk-time `declares_path` therefore saw only whatever another
    // language had already mounted. Registration is `Once`-guarded and
    // idempotent, so calling it here costs one atomic on every later parse and
    // makes the resolver answerable from the frontend — which is what lets
    // `hasattr` stop keeping a table of its own.
    crate::emitter::tree_register::register_namespace_tree();

    __w.py_imported_modules.clear();
    __w.py_from_imported_modules.clear();
    __w.py_float_returning_imports.clear();
    __w.py_sys_modules_bound = false;
    __w.py_dynamic_module_vars.clear();
    __w.py_dynamic_module_registry.clear();
    __w.py_dynamic_module_attrs.clear();
    __w.py_dynamic_module_all.clear();
    __w.py_string_consts.clear();
    __w.py_string_const_shadows.clear();
    __w.py_class_aliases.clear();
    __w.py_string_template_vars.clear();
    __w.py_string_template_delimiters.clear();
    __w.py_string_map_consts.clear();
    __w.py_object_float_fields.clear();
    __w.py_object_class_fields.clear();
    __w.py_bytes_vars.clear();
    __w.py_bytes_sequence_vars.clear();
    __w.py_bytearray_vars.clear();
    __w.py_memoryview_sources.clear();
    __w.py_memoryview_released_vars.clear();
    __w.py_codeop_compiler_vars.clear();
    __w.py_static_qualnames.clear();
    __w.py_gzip_file_vars.clear();
    __w.py_mimetype_customs.clear();
    __w.py_none_vars.clear();
    __w.py_mapping_proxy_vars.clear();
    __w.py_simple_namespace_vars.clear();
    __w.py_defined_classes.clear();
    __w.py_defined_functions.clear();
    __w.py_defined_function_params.clear();
    __w.py_defined_function_bodies.clear();
    __w.py_defined_function_returns.clear();
    __w.py_defined_function_param_kinds.clear();
    __w.py_signature_vars.clear();
    __w.py_annotation_vars.clear();
    __w.py_annotation_literal_vars.clear();
    __w.py_last_param_kinds.clear();
    __w.py_callable_classes.clear();
    __w.py_classes_with_init.clear();
    __w.py_class_parents.clear();
    __w.py_class_attrs.clear();

    // ⛔ BELOW the clears, so it is LIVE. Above them it was wiped, and a core
    // class the walker does not know is not normalised from `ClassName(arg)` to
    // `ExprKind::New` — the constructor then binds its arguments one slot over
    // and the first parameter receives the receiver.
    let needed_core = crate::core_classes::needed_classes(&gate);
    for name in &needed_core {
        __w.py_defined_classes.insert((*name).to_string());
        let parents: Vec<String> = crate::core_classes::core_class_parents(name)
            .into_iter()
            .map(|parent| parent.to_string())
            .collect();
        if !parents.is_empty() {
            note_class_parents(__w, name, &parents);
        }
    }
    // Every core class declares `__init__`, and `class_has_init` gates the
    // construction path — without it a `New` takes the no-argument shape.
    for name in &needed_core {
        __w.py_classes_with_init.insert((*name).to_string());
    }
    if source_uses_bytes(&gate) {
        for name in crate::core_classes::BYTES_CLASSES {
            __w.py_defined_classes.insert((*name).to_string());
        }
    }
    if gate.contains("object()") {
        for name in crate::core_classes::OBJECT_CLASSES {
            __w.py_defined_classes.insert((*name).to_string());
            __w.py_classes_with_init.insert((*name).to_string());
        }
    }
    if source_uses_ellipsis(&gate) {
        __w.py_defined_classes.insert("ellipsis".to_string());
    }
    for (name, attrs) in crate::core_classes::CLASS_ATTRS {
        if needed_core.contains(name) || (*name == "ellipsis" && source_uses_ellipsis(&gate)) {
            __w.py_class_attrs.insert(
                (*name).to_string(),
                attrs.iter().map(|a| (*a).to_string()).collect(),
            );
        }
    }
    __w.py_class_data_attrs.clear();
    __w.py_class_float_data_attrs.clear();
    __w.py_class_slots.clear();
    __w.py_class_properties.clear();
    for (name, attrs) in crate::core_classes::CLASS_DATA_ATTRS {
        if needed_core.contains(name) {
            note_class_data_attrs(
                __w,
                name,
                attrs.iter().map(|a| (*a).to_string()).collect(),
            );
        }
    }

    // ⛔ BELOW `py_class_properties.clear()`. A spliced class is never walked,
    // so nothing calls `note_class_property_kind` for it — and a property the
    // walker does not know is read as a plain attribute, so `PurePath("a/b")
    // .drive` resolved to an absent field instead of invoking the accessor.
    // Seeding it ABOVE the clear (where the class-name seeding has to live) is
    // wiped twenty lines later.
    for (name, props) in crate::core_classes::CLASS_PROPERTIES {
        if needed_core.contains(name) {
            for prop in *props {
                note_class_property_kind(__w, name, prop, "getter");
            }
        }
    }
    for (name, props) in crate::core_classes::CLASS_WRITABLE_PROPERTIES {
        if needed_core.contains(name) {
            for prop in *props {
                note_class_property_kind(__w, name, prop, "setter");
            }
        }
    }
    __w.py_init_subclass_writes.clear();
    __w.py_dataclass_fields.clear();
    __w.py_dataclass_options.clear();
    __w.py_instance_classes.clear();
    __w.py_instance_init_exprs.clear();
    __w.py_instance_attrs.clear();
    __w.py_assign_target_depth = 0;
    __w.py_namedtuple_defs.clear();
    __w.py_namedtuple_instances.clear();
    __w.py_sql_vars.clear();
    __w.py_sock_vars.clear();
    __w.py_re_vars.clear();
    __w.py_re_var_flags.clear();
    __w.py_re_var_patterns.clear();
    __w.py_re_match_vars.clear();
    __w.py_counter_vars.clear();
    __w.py_defaultdict_vars.clear();
    __w.py_deque_maxlen_vars.clear();
    __w.py_chainmap_vars.clear();
    __w.py_iterator_vars.clear();
    __w.py_generator_funcs.clear();
    __w.py_async_generator_funcs.clear();
    __w.py_async_funcs.clear();
    __w.py_coroutine_var_funcs.clear();
    __w.py_generator_vars.clear();
    __w.py_generator_func_float_yields.clear();
    __w.py_generator_var_funcs.clear();
    __w.py_userlist_vars.clear();
    __w.py_userdict_vars.clear();
    __w.py_dict_vars.clear();
    __w.py_dict_keys_view_vars.clear();
    __w.py_dict_items_view_vars.clear();
    __w.py_dict_keys_view_sources.clear();
    __w.py_dict_values_view_sources.clear();
    __w.py_dict_items_view_sources.clear();
    __w.py_set_vars.clear();
    __w.py_frozenset_vars.clear();
    __w.py_reprlib_vars.clear();
    __w.py_csv_field_size_limit = 131072;
    __w.py_csv_dialects.clear();
    __w.py_csv_writers.clear();
    __w.py_csv_readers.clear();
    __w.py_csv_dict_readers.clear();
    __w.py_csv_writer_targets.clear();
    __w.py_csv_dict_writers.clear();
    __w.py_xml_element_values.clear();
    __w.py_xml_element_array_values.clear();
    __w.py_xml_tree_roots.clear();
    __w.py_xml_parent_links.clear();
    __w.py_xml_pending_parent_link = None;
    __w.py_reprlib_infos.clear();
    __w.py_datetime_vars.clear();
    __w.py_calendar_vars.clear();
    __w.py_code_object_vars.clear();
    __w.py_marshal_code_vars.clear();
    __w.py_module_symbol_vars.clear();
    __w.py_doctest_object_vars.clear();
    __w.py_dis_bytecode_vars.clear();
    __w.py_uuid_values.clear();
    __w.py_path_values.clear();
    let preprocessed = preprocess_indentation(source);
    set_line_index(&preprocessed);
    let pairs = PythonParser::parse(Rule::program, &preprocessed)
        .map_err(|e| format!("Parse error: {}", e))?;

    let mut body = Vec::new();
    let mut imports = Vec::new();

    for top in pairs {
        let inner = match top.as_rule() {
            Rule::program => top.into_inner(),
            Rule::EOI => continue,
            _ => {
                walk_stmt_into(__w, top, &mut body, &mut imports)?;
                continue;
            }
        };
        for pair in inner {
            match pair.as_rule() {
                Rule::EOI | Rule::NEWLINE => continue,
                _ => walk_stmt_into(__w, pair, &mut body, &mut imports)?,
            }
        }
    }

    apply_float_var_repr(__w, &mut body, &mut HashMap::new());

    // The stdlib CLASSES, as ordinary declared AST — `core_classes`. Spliced
    // BEFORE the passes below, so the class machinery sees them exactly as it
    // sees a user class: a class inserted afterwards has its members but no
    // expression using them was ever typed.
    // Snapshot the user's own class names first: the closure only needs to
    // READ them, and borrowing `__w` mutably inside it would conflict with the
    // walker borrow that is live across the splice.
    // ⛔ FUNCTION METADATA WAS DECORATOR-ONLY. `assign_function_metadata`
    // has exactly two callers and both are in the decorator path, so a plain
    // `def f(x: int) -> bool` carried NO `__name__`, `__doc__` or
    // `__annotations__` at all — `f.__name__` did not read the wrong thing, it
    // read nothing, and the whole `function_signatures_extended` suite asks for
    // precisely those three.
    //
    // Gated on the source naming one of them, the same shape the `TYPEOBJ`
    // prelude above is gated on: three extra assignments per function is real
    // bloat for a program that never introspects, and a substring miss costs
    // only what is missing today.
    if gate.contains("__annotations__")
        || gate.contains("__name__")
        || gate.contains("__doc__")
        || gate.contains("__qualname__")
    {
        // ⛔ IMMEDIATELY AFTER EACH DEF, not appended at the end. A
        // `FunctionDecl` hoists; the metadata ASSIGNMENTS are ordinary
        // statements, so collecting them into one trailing block means
        // `print(f.__annotations__)` on line 3 runs before the assignment that
        // creates it.
        let mut rebuilt: Vec<Statement> = Vec::with_capacity(body.len());
        for stmt in body {
            let meta = match &stmt.kind {
                StmtKind::FunctionDecl {
                    name,
                    params,
                    return_type,
                    body: fn_body,
                    ..
                } if !name.starts_with("__py_") && !name.starts_with("__vybe") => {
                    let mut out = Vec::new();
                    assign_function_metadata(&mut out, name, params, return_type.as_ref(), fn_body);
                    out
                }
                _ => Vec::new(),
            };
            rebuilt.push(stmt);
            rebuilt.extend(meta);
        }
        body = rebuilt;
    }

    let user_classes = __w.py_defined_classes.clone();
    // ⛔ EXCLUDE THE SEEDED NAMES. `is_user_declared` exists so a user's own
    // `class IPv4Address` wins over the core one — but `py_defined_classes` now
    // HOLDS the core names (that seeding is what makes `ClassName(arg)`
    // normalise to `New`), so the guard saw its own seed, skipped every
    // declaration, and `New` reached a global that was never emitted:
    // "undefined is not callable". The user's classes are the ones the SOURCE
    // declared, which is exactly the seeded set removed.
    let mut core_classes = crate::core_classes::declarations_for(&gate, |name| {
        user_classes.contains(name) && !needed_core.iter().any(|n| *n == name)
    });
    add_core_class_data_fields(&mut core_classes);
    if !core_classes.is_empty() {
        // ⛔ REGISTER THEM. The declarations are spliced AFTER the source walk,
        // so nothing has called `note_defined_class` for them — and without
        // that the walker cannot track that `a = ipaddress.IPv4Address(…)`
        // holds an instance, so `a.version` took the untyped attribute path and
        // raised. A spliced class has to be as known to the walker as a
        // source-declared one.
        body.splice(0..0, core_classes);
    }

    let mut helper_decls = Vec::new();

    // The module dunders, as real module BINDINGS.
    //
    // `__name__` used to be a `[namespace_constants]` row, which resolves the
    // NAME but never creates a member — so it was absent from the module's
    // globals, and `globals()` had to seed it back by hand in the shared
    // builtin table. CPython has no such split: `__name__` is an attribute of
    // the module, `globals()['__name__']` reads it, and `'__name__' in
    // globals()` is True because it is genuinely there. Binding it makes all
    // three agree from one fact instead of two.
    helper_decls.extend(crate::core_classes::module_dunder_declarations());

    // The bytes helper surface is DECLARED, not parsed: it was 55 lines of
    // prelude source on the widest gate in the language (any `b'` or `b"`,
    // measured firing on 1368 corpus tests).
    if source_uses_bytes(&gate) {
        let mut decls = crate::core_classes::bytes_declarations();
        decls.append(&mut body);
        body = decls;
    }

    if gate.contains("object()") {
        let mut decls = crate::core_classes::object_declarations();
        decls.append(&mut body);
        body = decls;
    }

    // Define the `Ellipsis` singleton (bound to `...`) as a real object so it is
    // distinct from `None`, is its own singleton (`... is ...`), and reprs as
    // `Ellipsis` with `type(...).__name__ == "ellipsis"`.
    if source_uses_ellipsis(&gate) {
        helper_decls.extend(crate::core_classes::ellipsis_declarations());
    }

    // Seed the sentinel used by the `python.slice_new` adapter to distinguish
    // `slice(stop)` from `slice(start, stop)`.
    if source_uses_slice_ctor(&gate) {
        helper_decls.extend(crate::core_classes::slice_declarations());
    }

    if gate.contains("ExceptionGroup") {
        helper_decls.extend(crate::core_classes::exception_group_declarations());
    }

    // `fnmatch` — shell-style filename matching (pure Python, self-contained
    // iterative `*`/`?` matcher; no `re` dependency).

    // `configparser` — AST class adapter over `common:config.parse`; no source
    // prelude.

    // `os.path` — pure-string POSIX helpers (join/split/normpath/…) are emitter
    // adapters (common:python.ospath_*), emitted at the call site. No prelude.

    // `random` — distributions + range/weight helpers are adapter leaves over
    // the shared seedable PRNG primitive. No source prelude.

    // `string` module constants are intercepted at the member-read site.
    // Template/Formatter are AST core classes; capwords is folded in the
    // module-call normalizer.
    if !helper_decls.is_empty() {
        helper_decls.append(&mut body);
        body = helper_decls;
    }
    body.insert(
        0,
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::ident("__doc__")],
            value: Expression::new(ExprKind::Lit(Literal::Null)),
            by_ref: false,
        }),
    );
    normalize_pickle_reduce_returns(&mut body);
    let mut post_fold_shadows = HashSet::new();
    collect_python_function_param_names(&body, &mut post_fold_shadows);
    __w.py_string_const_shadows.push(post_fold_shadows);
    for stmt in &mut body {
        stmt.walk_exprs_mut(&mut normalize_python_operand_bool_expr);
        stmt.walk_exprs_mut(&mut normalize_python_slice_ctor_expr);
        stmt.walk_exprs_mut(&mut normalize_python_types_new_class_expr);
        stmt.walk_exprs_mut(&mut |__x| normalize_python_shlex_ctor_expr(__w, __x));
        stmt.walk_exprs_mut(&mut |__x| normalize_python_textwrapper_ctor_expr(__w, __x));
        stmt.walk_exprs_mut(&mut |__x| normalize_python_module_facade_expr(__w, __x));
        stmt.walk_exprs_mut(&mut |__x| normalize_python_bytes_memoryview_expr(__w, __x));
        stmt.walk_exprs_mut(&mut |__x| normalize_python_deepcopy_known_fields(__w, __x));
        stmt.walk_exprs_mut(&mut normalize_asyncio_expr);
    }
    normalize_python_slice_object_indexes(&mut body);
    let source_lines: Vec<&str> = source.lines().collect();
    recover_silent_aug_assigns(&mut body, &source_lines);
    __w.py_string_const_shadows.pop();
    Ok(Module {
        canon: Default::default(),
        name: "main".into(),
        language: Lang::Python,
        body,
        // The contract is declared in the profile's `[async]` section;
        // the compiler stamps it. A walker writes an override only for a
        // module whose contract differs from its language's.
        imports,
        directives: Directives {
            // ⛔ THE RECEIVER IS PARAMETER 0 — ECMA-262 §10.2.1
            // `[[Call]](thisArgument, argumentsList)`, which is also the only
            // shape expressible as a wasm functype. Python spells it in its own
            // syntax already (`def get(self)`), so this states the calling
            // convention the language was using anyway.
            receiver_binding: Some(vybe_ast::ReceiverBinding::UniversalParameter),
            // ⛔ Python's instance fields ARE own properties: `__py_attr_read`
            // is `ecma:object.hasIn` over the property bag and
            // `emit_attr_write` writes into it. Unstated, the default (false)
            // hands a parentless class the SEAM 3 licence, its fields move to
            // indexed GC-struct storage, and no reflective surface — `hasIn`,
            // `Object.keys`, `in` — can see them: construction succeeded and
            // every `p.a` raised AttributeError. Measured on dataclasses,
            // `py_dataclasses` 13 -> 4. `flexclassplan.md` states the rule: a
            // language whose fields are own properties stays out of indexed
            // storage until the host key walk merges `TypeEntry.fields`.
            instance_fields_are_own_properties: Some(true),
            // ⛔ And a CLASS attribute is an ordinary attribute of the class
            // object — `C.x`, `vars(C)` and `C.__dict__` all see it. Unstated,
            // the default (false) means a static field is never written as an
            // own property, so `class C: x = 5` then `C.x` found nothing.
            static_fields_are_own_properties: Some(true),
            // Reading a method produces a fresh callable with the receiver
            // already bound — the third dispatch model, distinct from
            // prototype (js/dart) and call-site (php). Replaces the profile
            // bool `methods_bind_on_access`.
            method_receiver: Some(MethodReceiver::BindOnAccess),
            set_semantics: Some(SetSemantics {
                mutation_result: SetMutationResult::Void,
                delete_result: SetMutationResult::Void,
                missing_delete: SetMissingDelete::ThrowKeyError,
                algebra_arity: SetAlgebraArity::Variadic,
                predicate_bool_object: true,
                // Unchanged: Python keeps its current membership behaviour;
                // migrating it to hash-based identity is its owner's call.
                membership: SetMembership::SameValueZero,
            }),
            // `del x` and `x = None` drop a reference and run `__del__`. The
            // POLICY is stated here once; the shared compiler lowers both
            // statements against `ProtocolSlot::Destructor`, which
            // `normalize_class.rs` already fills from the canonical table. The
            // walker used to synthesise a `typeof x.__del__ == "function"`
            // probe into the tree at every drop site instead — a second
            // mechanism for a slot that was already bound.
            name_drop: Some(NameDrop::Finalise),
            // CPython §3.3.1: truth is asked of the OBJECT — `__bool__`, then
            // `__len__` — so `[]`, `{}`, `set()` and a class returning 0 from
            // `__len__` are all falsy for the SAME reason. Declared once here;
            // the shared compiler runs the ladder against `ProtocolSlot::Bool`
            // and `ProtocolSlot::Len`.
            //
            // This was `truthiness_via_dunder_or_length` in the profile, which
            // the program could not see and which three shared sites read
            // separately — so they drifted, and `assert []` passed.
            truthiness: Some(Truthiness::Protocol),
            ..Default::default()
        },
    })
}

/// Heuristic: does the source reference bytes at all? Only gates whether the
/// repr helper is injected — a false positive just adds an unused function.
fn source_uses_bytes(source: &str) -> bool {
    source.contains("b'")
        || source.contains("b\"")
        || source.contains("B'")
        || source.contains("B\"")
        || source.contains("bytes")
        || source.contains("BytesIO")
        || source.contains("bytearray")
        || source.contains("memoryview")
        || source.contains("import codecs")
        || source.contains("from codecs")
        || source.contains("import io")
        || source.contains(", io")
        || source.contains("from io")
        || source.contains(".hex(")
        || source.contains(".encode(")
        || source.contains(".decode(")
}

/// Python source for `__vybe_bytes_repr(int_array) -> "b'…'"`. Escape fragments
/// are built from `chr(92)` (backslash) rather than backslash string literals,
/// which the Python string-escape lowering mishandles.
/// Does the source reference `...` or `Ellipsis`? Gates the singleton prelude
/// (a false positive just adds an unused class + binding).
fn source_uses_ellipsis(source: &str) -> bool {
    source.contains("...") || source.contains("Ellipsis")
}

/// Does the source call the `slice()` constructor (as opposed to `.slice(` method
/// calls or `islice`)? Requires `slice(` whose preceding char is not part of an
/// identifier and not a `.` member access. A false positive only adds an unused
/// class definition.
fn source_uses_slice_ctor(source: &str) -> bool {
    let bytes = source.as_bytes();
    let mut i = 0;
    while let Some(pos) = source[i..].find("slice(") {
        let at = i + pos;
        let prev_ok = at == 0
            || !matches!(bytes[at - 1], b'.' | b'_') && !bytes[at - 1].is_ascii_alphanumeric();
        if prev_ok {
            return true;
        }
        i = at + 5;
    }
    false
}

fn normalize_python_slice_ctor_expr(expr: &mut Expression) {
    let ExprKind::Call { callee, args, .. } = &mut expr.kind else {
        return;
    };
    if !matches!(&callee.kind, ExprKind::Ident(name) if name == "slice") {
        return;
    }
    if args.is_empty() || args.len() > 3 || args.iter().any(|arg| arg.name.is_some() || arg.spread) {
        return;
    }
    let first = args[0].value.clone();
    let second = args
        .get(1)
        .map(|arg| arg.value.clone())
        .unwrap_or_else(|| Expression::ident("__slice_unset"));
    let third = args
        .get(2)
        .map(|arg| arg.value.clone())
        .unwrap_or_else(Expression::null);
    expr.kind = ExprKind::Call {
        callee: Box::new(Expression::ident("__py_slice_new")),
        args: vec![
            Argument::positional(first),
            Argument::positional(second),
            Argument::positional(third),
        ],
        optional: false,
    };
}

fn normalize_python_slice_object_indexes(body: &mut [Statement]) {
    let mut slice_vars = HashSet::new();
    collect_python_slice_vars(body, &mut slice_vars);
    if slice_vars.is_empty() {
        return;
    }
    for stmt in body {
        stmt.walk_exprs_mut(&mut |expr| rewrite_python_slice_getitem(expr, &slice_vars));
    }
}

fn collect_python_slice_vars(body: &[Statement], out: &mut HashSet<String>) {
    for stmt in body {
        match &stmt.kind {
            StmtKind::Assign { targets, value, .. } if targets.len() == 1 => {
                if let ExprKind::Ident(name) = &targets[0].kind
                    && expr_is_normalized_slice_ctor(value)
                {
                    out.insert(name.clone());
                }
            }
            StmtKind::Block(body)
            | StmtKind::FunctionDecl { body, .. }
            | StmtKind::NamespaceDecl { body, .. }
            | StmtKind::For { body, .. }
            | StmtKind::ForIn { body, .. }
            | StmtKind::While { body, .. }
            | StmtKind::DoWhile { body, .. }
            | StmtKind::With { body, .. }
            | StmtKind::Using { body, .. }
            | StmtKind::Lock { body, .. } => collect_python_slice_vars(body, out),
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                collect_python_slice_vars(then_body, out);
                for (_, body) in elifs {
                    collect_python_slice_vars(body, out);
                }
                if let Some(body) = else_body {
                    collect_python_slice_vars(body, out);
                }
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                collect_python_slice_vars(body, out);
                for catch in catches {
                    collect_python_slice_vars(&catch.body, out);
                }
                if let Some(body) = else_body {
                    collect_python_slice_vars(body, out);
                }
                if let Some(body) = finally {
                    collect_python_slice_vars(body, out);
                }
            }
            StmtKind::Switch { cases, default, .. } => {
                for case in cases {
                    collect_python_slice_vars(&case.body, out);
                }
                if let Some(body) = default {
                    collect_python_slice_vars(body, out);
                }
            }
            StmtKind::ClassDecl { members, .. }
            | StmtKind::StructDecl { members, .. }
            | StmtKind::ModuleDecl { members, .. } => {
                for member in members {
                    match member {
                        ClassMember::Method(method) | ClassMember::NestedType(method) => {
                            collect_python_slice_vars(std::slice::from_ref(method), out);
                        }
                        ClassMember::Constructor { body, .. } => collect_python_slice_vars(body, out),
                        ClassMember::Property { getter, setter, .. } => {
                            if let Some(body) = getter {
                                collect_python_slice_vars(body, out);
                            }
                            if let Some(setter) = setter {
                                collect_python_slice_vars(&setter.body, out);
                            }
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }
}

fn expr_is_normalized_slice_ctor(expr: &Expression) -> bool {
    matches!(
        &expr.kind,
        ExprKind::Call { callee, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_slice_new")
    )
}

fn from_end_slice_var(expr: &Expression, slice_vars: &HashSet<String>) -> Option<String> {
    let ExprKind::Call { callee, args, .. } = &expr.kind else {
        return None;
    };
    if !matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_from_end__") || args.len() != 2
    {
        return None;
    }
    let ExprKind::Ident(name) = &args[1].value.kind else {
        return None;
    };
    slice_vars.contains(name).then(|| name.clone())
}

fn rewrite_python_slice_getitem(expr: &mut Expression, slice_vars: &HashSet<String>) {
    let ExprKind::Call { callee, args, .. } = &mut expr.kind else {
        return;
    };
    if !matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_getitem") || args.len() != 2 {
        return;
    }
    let Some(slice_var) = from_end_slice_var(&args[1].value, slice_vars) else {
        return;
    };
    *callee = Box::new(Expression::ident("__py_getslice_obj"));
    args[1].value = Expression::ident(&slice_var);
}

fn silent_aug_assign_op(text: &str) -> Option<&'static str> {
    [
        "**=", "//=", "<<=", ">>=", "+=", "-=", "*=", "/=", "%=", "@=", "|=", "&=", "^=",
    ]
    .into_iter()
    .find(|op| text.contains(op))
}

fn line_aug_assign_op_for_ident(line: &str, name: &str) -> Option<&'static str> {
    for op in ["+=", "*=", "/="] {
        if let Some(pos) = line.find(op)
            && line[..pos].trim() == name
        {
            return Some(op);
        }
    }
    None
}

fn already_lowered_aug_value(value: &Expression, helper: &str) -> bool {
    matches!(
        &value.kind,
        ExprKind::Call { callee, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == helper)
    )
}

fn recover_silent_aug_assigns(body: &mut [Statement], source_lines: &[&str]) {
    for stmt in body {
        recover_silent_aug_assign_stmt(stmt, source_lines);
    }
}

fn recover_silent_aug_assign_stmt(stmt: &mut Statement, source_lines: &[&str]) {
    match &mut stmt.kind {
        StmtKind::Assign { targets, value, .. } if targets.len() == 1 => {
            let ExprKind::Ident(name) = &targets[0].kind else {
                return;
            };
            let Some(line_no) = stmt.span.start_line.checked_sub(1) else {
                return;
            };
            let Some(line) = source_lines.get(line_no as usize) else {
                return;
            };
            let Some(op) = line_aug_assign_op_for_ident(line, name) else {
                return;
            };
            let helper = match op {
                "+=" => "__pyadd__",
                "*=" => "__pymul__",
                "/=" => "__pytruediv__",
                _ => return,
            };
            if already_lowered_aug_value(value, helper) {
                return;
            }
            let rhs = value.clone();
            *value = call_ident(helper, vec![Expression::ident(name), rhs]);
        }
        StmtKind::Block(body)
        | StmtKind::FunctionDecl { body, .. }
        | StmtKind::NamespaceDecl { body, .. }
        | StmtKind::For { body, .. }
        | StmtKind::ForIn { body, .. }
        | StmtKind::While { body, .. }
        | StmtKind::DoWhile { body, .. }
        | StmtKind::With { body, .. }
        | StmtKind::Using { body, .. }
        | StmtKind::Lock { body, .. } => recover_silent_aug_assigns(body, source_lines),
        StmtKind::If {
            then_body,
            elifs,
            else_body,
            ..
        } => {
            recover_silent_aug_assigns(then_body, source_lines);
            for (_, body) in elifs {
                recover_silent_aug_assigns(body, source_lines);
            }
            if let Some(body) = else_body {
                recover_silent_aug_assigns(body, source_lines);
            }
        }
        StmtKind::Try {
            body,
            catches,
            else_body,
            finally,
        } => {
            recover_silent_aug_assigns(body, source_lines);
            for catch in catches {
                recover_silent_aug_assigns(&mut catch.body, source_lines);
            }
            if let Some(body) = else_body {
                recover_silent_aug_assigns(body, source_lines);
            }
            if let Some(body) = finally {
                recover_silent_aug_assigns(body, source_lines);
            }
        }
        StmtKind::Switch { cases, default, .. } => {
            for case in cases {
                recover_silent_aug_assigns(&mut case.body, source_lines);
            }
            if let Some(body) = default {
                recover_silent_aug_assigns(body, source_lines);
            }
        }
        StmtKind::ClassDecl { members, .. }
        | StmtKind::StructDecl { members, .. }
        | StmtKind::ModuleDecl { members, .. } => {
            for member in members {
                match member {
                    ClassMember::Method(method) | ClassMember::NestedType(method) => {
                        recover_silent_aug_assign_stmt(method, source_lines);
                    }
                    ClassMember::Constructor { body, .. } => {
                        recover_silent_aug_assigns(body, source_lines);
                    }
                    ClassMember::Property { getter, setter, .. } => {
                        if let Some(body) = getter {
                            recover_silent_aug_assigns(body, source_lines);
                        }
                        if let Some(setter) = setter {
                            recover_silent_aug_assigns(&mut setter.body, source_lines);
                        }
                    }
                    _ => {}
                }
            }
        }
        _ => {}
    }
}

/// Pure-Python `warnings` module.

/// `io.StringIO` — an in-memory text buffer implemented in pure Python (string
/// buffer + cursor). No host I/O; `print(file=buf)` writes here via `.write`.
/// `socket` — the stateful half of the module: the `socket` class, plus the
/// module object that carries the constants and the module-level functions.
///
/// A prelude rather than adapters because a socket IS a stateful object: it
/// holds the WASI resource, the input/output streams, the timeout and the
/// option table across calls. The individual WASI calls it sequences are all
/// plain `host:` profile entries (`_wasi_*`), so no bytecode is hand-written
/// here — this only composes them into CPython's blocking API.
///
/// The module object has to carry the module FUNCTIONS too: a global named
/// `socket` shadows the dotted `socket.gethostname` profile builtin, so each
/// one delegates to the bare alias of the same adapter.

/// `ipaddress` — pure address arithmetic, so no host surface is involved at
/// all; the module is a prelude only because `IPv4Address`/`IPv4Network` are
/// stateful classes.
///
/// Authoring constraints this file must respect (each one silently drops the
/// whole prelude): no comment inside an indented block, no blank line inside a
/// class body, no string literal containing `:` inside a subscript, and no
/// parameter or attribute named `type`.

/// `fnmatch` — shell-style pattern matching.
///
/// The MATCHER is no longer here: `__glob_match` is bound to
/// `common:str_glob_match`, the shared emitter php's `fnmatch` also uses. What
/// was here was a hand-written iterative `*`/`?` matcher that could not do
/// `[seq]` classes at all — so `fnmatch("fileA.py", "file[ABC].py")` was False
/// where real python3 says True. Every test missed it because
/// `fold_fnmatch_call` CONSTANT-FOLDS literal arguments in Rust, so the prelude
/// only ran behind a variable, which no test exercised.
///
/// `os.path.normcase` is identity on POSIX, so `fnmatch` is case-SENSITIVE here
/// and identical to `fnmatchcase` — measured, `fnmatch.fnmatch('ABC','abc')` is
/// False on this platform. The old body lower-cased both sides.
///
/// `translate` stays Python: it emits python's OWN regex dialect
/// (`(?s:…)\Z`), which is a regex-layer question, not a glob one.

/// `configparser` — Python's ADAPTER over the shared `config` primitive.
///
/// The INI grammar itself is `crates/vybe_compiler/src/primitives/config.rs`,
/// beside `csv`, because the format has several consumers and belongs to none
/// of them: php's `parse_ini_file`/`parse_ini_string` bind the same primitive.
/// What stays here is only what is Python's — the class surface, the
/// `optionxform` lowercasing policy passed as the second argument, and the
/// accessors' return types.
///
/// This used to be a 40-line scanner in this string, which is why php had no
/// `parse_ini_*` at all: the code existed but no other language could reach it.

/// Pure-Python `string` module surface: `Template` (`$name`/`${name}`
/// substitution with `$$` escape and a class-attribute `delimiter`),
/// `Formatter` (delegates to `str.format`), and `capwords`. Constants
/// (ascii_letters, digits, …) are intercepted in [desugar_member_reads].
/// Pure-Python `pprint` surface: `pformat`/`pprint`/`pp`, the stateful
/// `PrettyPrinter` class, plus `saferepr`/`isreadable`/`isrecursive`.
///
/// A prelude (not adapters) because `PrettyPrinter` is a genuinely stateful
/// CLASS carrying indent/width/depth/compact/sort_dicts across calls, and the
/// module functions are thin wrappers over the same recursive layout routine —
/// splitting them would duplicate the algorithm. See
/// `feedback_adapters_over_preludes`: "a class needs a class".
///
/// Recursion detection tracks container identity down the current path only, so
/// a value repeated in sibling positions is not a cycle.

fn walk_stmt_into(
    __w: &mut PyWalker,
    pair: Pair<Rule>,
    body: &mut Vec<Statement>,
    imports: &mut Vec<Import>,
) -> Result<(), String> {
    match pair.as_rule() {
        Rule::import_stmt => {
            for import in walk_imports(__w, pair)? {
                let ImportKind::Simple { path, alias } = &import.kind else {
                    continue;
                };
                let root = path.split('.').next().unwrap_or(path).to_string();
                let bound = alias.clone().unwrap_or_else(|| root.clone());
                if let Some(stmts) = dynamic_module_import_stmts(__w, path, &bound) {
                    body.extend(stmts);
                    continue;
                }
                if matches!(root.as_str(), "shlex" | "textwrap") {
                    note_imported_module(__w, &root);
                    if bound != root {
                        note_module_alias(__w, &bound, &root);
                    }
                    if bound != root {
                        body.push(Statement::new(StmtKind::Assign {
                            targets: vec![Expression::new(ExprKind::Ident(bound.clone()))],
                            value: Expression::new(ExprKind::Ident(root.clone())),
                            by_ref: false,
                        }));
                    }
                    continue;
                }
                if !py_known_module(&root) {
                    body.push(py_import_error_stmt(&format!("No module named '{root}'")));
                    return Ok(());
                }
                body.extend(py_module_rename_stmts(&root));
                if root == "sys" && !__w.py_sys_modules_bound {
                    __w.py_sys_modules_bound = true;
                    body.push(Statement::new(StmtKind::Assign {
                        targets: vec![Expression::ident("__py_sys_path")],
                        value: Expression::new(ExprKind::Array(vec![ArrayElement {
                            key: None,
                            value: Expression::string(""),
                            spread: false,
                            by_ref: false,
                        }])),
                        by_ref: false,
                    }));
                    body.push(Statement::new(StmtKind::Assign {
                        targets: vec![Expression::ident("__py_sys_argv")],
                        value: Expression::new(ExprKind::Array(vec![ArrayElement {
                            key: None,
                            value: Expression::string(""),
                            spread: false,
                            by_ref: false,
                        }])),
                        by_ref: false,
                    }));
                    let props: Vec<ObjectProperty> = {
                        __w.py_imported_modules
                            .iter()
                            .map(|name| ObjectProperty::KeyValue {
                                key: Expression::new(ExprKind::Lit(Literal::Str(
                                    name.clone().into(),
                                ))),
                                value: Expression::new(ExprKind::Ident(name.clone())),
                            })
                            .collect()
                    };
                    body.push(Statement::new(StmtKind::Assign {
                        targets: vec![Expression::new(ExprKind::Ident("__py_sys_modules".into()))],
                        value: Expression::new(ExprKind::Object(props)),
                        by_ref: false,
                    }));
                } else if __w.py_sys_modules_bound {
                    body.push(Statement::new(StmtKind::Assign {
                        targets: vec![Expression::new(ExprKind::Index {
                            object: Box::new(Expression::new(ExprKind::Ident(
                                "__py_sys_modules".into(),
                            ))),
                            index: Box::new(Expression::new(ExprKind::Lit(Literal::Str(
                                bound.clone().into(),
                            )))),
                            null_safe: false,
                        })],
                        value: Expression::new(ExprKind::Ident(bound)),
                        by_ref: false,
                    }));
                }
                imports.push(import);
            }
        }
        Rule::import_from_stmt => {
            let import = walk_import_from(__w, pair)?;
            // `from operator import add, mul` — the operator module IS the
            // operators; bind each name to the equivalent lambda instead of
            // an ESM binding (there is no host module to bind against).
            // `from __future__ import …` — compiler directives for features
            // this implementation already has; bind nothing, error nothing.
            if let ImportKind::Named { path, names, level } = &import.kind {
                if path == "__future__" {
                    return Ok(());
                }
                // `contextlib` names are defined globally by the injected prelude
                // (CONTEXTLIB_PRELUDE), so `from contextlib import X` is a no-op —
                // rebinding through the empty module surface would shadow them.
                if path == "contextlib" {
                    return Ok(());
                }
                // `io` (StringIO/BytesIO) is provided by IO_PRELUDE as globals.
                if path == "io" {
                    return Ok(());
                }
                if path == "types"
                    || path == "threading"
                    || path == "queue"
                    || path == "concurrent.futures"
                    || path == "multiprocessing"
                    || path == "subprocess"
                {
                    return Ok(());
                }
                let root = path.split('.').next().unwrap_or(path).to_string();
                if *level == 0 && !path.is_empty() && !py_known_module(&root) {
                    body.push(py_import_error_stmt(&format!("No module named '{root}'")));
                    return Ok(());
                }
                // A module whose export surface the walker knows rejects
                // unknown names with ImportError (CPython behavior). The
                // surface = the static table + the rename aliases.
                if let Some(surface) = py_module_surface(path) {
                    let renames = py_module_renames(path).unwrap_or(&[]);
                    for n in names {
                        if !surface.contains(&n.name.as_str())
                            && !renames.iter().any(|(py, canon)| {
                                *py == n.name.as_str() || *canon == n.name.as_str()
                            })
                        {
                            body.push(py_import_error_stmt(&format!(
                                "cannot import name '{}' from '{}'",
                                n.name, path
                            )));
                            return Ok(());
                        }
                    }
                }
                if path == "collections" {
                    // Bind Python-only collection constructors to the small
                    // normalization helpers above; deque remains an array, and
                    // dict-like collections remain ordinary dicts/maps.
                    for n in names {
                        let helper = match n.name.as_str() {
                            "Counter" => Some("__py_counter_new"),
                            "defaultdict" => Some("__py_defaultdict"),
                            "deque" => Some("__py_deque"),
                            "ChainMap" => Some("__py_chainmap_new"),
                            _ => None,
                        };
                        if let Some(helper) = helper {
                            let local = n.alias.as_ref().unwrap_or(&n.name).clone();
                            body.push(Statement::new(StmtKind::Assign {
                                targets: vec![Expression::new(ExprKind::Ident(local))],
                                value: Expression::ident(helper),
                                by_ref: false,
                            }));
                        }
                    }
                    imports.push(import);
                    return Ok(());
                }
                if path == "string" {
                    note_imported_module(__w, "string");
                    for n in names {
                        let helper = match n.name.as_str() {
                            "Template" => Some("__string_Template"),
                            "Formatter" => Some("__string_Formatter"),
                            _ => None,
                        };
                        if let Some(helper) = helper {
                            let local = n.alias.as_ref().unwrap_or(&n.name).clone();
                            note_class_alias(__w, &local, helper);
                            body.push(Statement::new(StmtKind::Assign {
                                targets: vec![Expression::ident(&local)],
                                value: Expression::ident(helper),
                                by_ref: false,
                            }));
                        }
                    }
                    imports.push(import);
                    return Ok(());
                }
                if path == "operator" {
                    for n in names {
                        let local = n.alias.as_ref().unwrap_or(&n.name).clone();
                        __w.py_operator_imports.insert(local.clone(), n.name.clone());
                        if let Some(lambda) = operator_fn_lambda(&n.name) {
                            body.push(Statement::new(StmtKind::Assign {
                                targets: vec![Expression::new(ExprKind::Ident(local))],
                                value: lambda,
                                by_ref: false,
                            }));
                        }
                    }
                    return Ok(());
                }
                if path == "functools" {
                    imports.push(import);
                    return Ok(());
                }
            }
            if let ImportKind::Wildcard { path, .. } = &import.kind {
                if let Some(stmts) = dynamic_module_star_import_stmts(__w, path) {
                    body.extend(stmts);
                    return Ok(());
                }
            }
            imports.push(import);
        }
        _ => body.push(walk_statement(__w, pair)?),
    }
    Ok(())
}

/// `operator.<name>` as a lambda over the equivalent operator — the module's
/// documented semantics (`add(a, b)` is `a + b`, …). `None` for names this
/// table doesn't cover (they stay unbound, same as before).
fn operator_fn_lambda(name: &str) -> Option<Expression> {
    let binop = |op: BinOp| -> Expression {
        Expression::new(ExprKind::Lambda {
            params: vec![lambda_param("__a"), lambda_param("__b")],
            body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Binary {
                op,
                left: Box::new(Expression::new(ExprKind::Ident("__a".into()))),
                right: Box::new(Expression::new(ExprKind::Ident("__b".into()))),
            }))),
            is_async: false,
            captures: vec![],
        })
    };
    // `add`/`mul` route through the same dynamic helpers `+`/`*` lower to
    // (list concat / str repeat / dunder dispatch), not raw numeric ops.
    let helper2 = |helper: &str| -> Expression {
        Expression::new(ExprKind::Lambda {
            params: vec![lambda_param("__a"), lambda_param("__b")],
            body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Call {
                callee: Box::new(Expression::new(ExprKind::Ident(helper.into()))),
                args: vec![
                    Argument::positional(Expression::new(ExprKind::Ident("__a".into()))),
                    Argument::positional(Expression::new(ExprKind::Ident("__b".into()))),
                ],
                optional: false,
            }))),
            is_async: false,
            captures: vec![],
        })
    };
    Some(match name {
        "add" | "concat" => helper2("__pyadd__"),
        "mul" => helper2("__pymul__"),
        "matmul" => helper2("__pymatmul__"),
        "sub" => binop(BinOp::Sub),
        "truediv" => binop(BinOp::Div),
        "floordiv" => binop(BinOp::FloorDiv),
        "mod" => binop(BinOp::Mod),
        "pow" => binop(BinOp::Pow),
        "eq" => binop(BinOp::Eq),
        "ne" => binop(BinOp::NotEq),
        "lt" => binop(BinOp::Lt),
        "le" => binop(BinOp::LtEq),
        "gt" => binop(BinOp::Gt),
        "ge" => binop(BinOp::GtEq),
        "neg" => Expression::new(ExprKind::Lambda {
            params: vec![lambda_param("__a")],
            body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Unary {
                op: UnaryOp::Neg,
                expr: Box::new(Expression::new(ExprKind::Ident("__a".into()))),
            }))),
            is_async: false,
            captures: vec![],
        }),
        _ => return None,
    })
}

fn py_member(object: Expression, field: &str) -> Expression {
    Expression::new(ExprKind::Member {
        object: Box::new(object),
        field: field.into(),
        null_safe: false,
    })
}

fn py_index(object: Expression, index: Expression) -> Expression {
    Expression::new(ExprKind::Index {
        object: Box::new(object),
        index: Box::new(index),
        null_safe: false,
    })
}

fn py_call(callee: Expression, args: Vec<Expression>) -> Expression {
    Expression::new(ExprKind::Call {
        callee: Box::new(callee),
        args: args.into_iter().map(Argument::positional).collect(),
        optional: false,
    })
}

fn py_new(class_name: &str, args: Vec<Expression>) -> Expression {
    Expression::new(ExprKind::New {
        class: Box::new(Expression::ident(class_name)),
        args: args.into_iter().map(Argument::positional).collect(),
    })
}

fn py_raise_expr(exc_name: &str, message: Option<&str>) -> Expression {
    let mut args = Vec::new();
    if let Some(message) = message {
        args.push(Expression::string(message));
    }
    call_ident(&format!("__py_raise_{exc_name}"), args)
}

fn py_raise_expr_stmt(expr: &Expression) -> Option<StmtKind> {
    let ExprKind::Call { callee, args, .. } = &expr.kind else {
        return None;
    };
    let ExprKind::Ident(name) = &callee.kind else {
        return None;
    };
    let exc_name = name.strip_prefix("__py_raise_")?;
    if exc_name == "GetoptError" {
        let opt = args
            .first()
            .map(|a| a.value.clone())
            .unwrap_or_else(|| Expression::string(""));
        let tmp = Expression::ident("__py_pending_getopt_error");
        let field = |name: &str| {
            Expression::new(ExprKind::Member {
                object: Box::new(tmp.clone()),
                field: name.into(),
                null_safe: false,
            })
        };
        return Some(StmtKind::Block(vec![
            Statement::new(StmtKind::Assign {
                targets: vec![tmp.clone()],
                value: call_ident("__py_exc_Exception", vec![opt.clone()]),
                by_ref: false,
            }),
            Statement::new(StmtKind::Assign {
                targets: vec![field("__exception_type")],
                value: Expression::string("GetoptError"),
                by_ref: false,
            }),
            Statement::new(StmtKind::Assign {
                targets: vec![field("msg")],
                value: opt.clone(),
                by_ref: false,
            }),
            Statement::new(StmtKind::Assign {
                targets: vec![field("opt")],
                value: opt,
                by_ref: false,
            }),
            Statement::new(StmtKind::Throw {
                expr: Some(tmp),
                cause: None,
            }),
        ]));
    }
    let exc = {
        call_ident(
            &format!("__py_exc_{exc_name}"),
            args.iter().map(|a| a.value.clone()).collect(),
        )
    };
    Some(StmtKind::Throw {
        expr: Some(exc),
        cause: None,
    })
}

/// Strip `(key)` out of every `%(key)...conv` spec in a static python format
/// string, returning the plain-printf equivalent plus the keys in the order
/// they appeared. `None` when the string has no mapping key at all (the
/// ordinary positional path handles it).
fn py_percent_named_keys(fmt: &str) -> Option<(String, Vec<String>)> {
    if !fmt.contains("%(") {
        return None;
    }
    let chars: Vec<char> = fmt.chars().collect();
    let mut out = String::with_capacity(fmt.len());
    let mut keys = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '%' && i + 1 < chars.len() && chars[i + 1] == '(' {
            let close = chars[i + 2..].iter().position(|&c| c == ')')?;
            let key: String = chars[i + 2..i + 2 + close].iter().collect();
            keys.push(key);
            out.push('%');
            i = i + 2 + close + 1;
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    Some((out, keys))
}

fn py_numeric_zero(e: &Expression) -> bool {
    match &e.kind {
        ExprKind::Lit(Literal::Int(n)) => *n == 0,
        ExprKind::Lit(Literal::Float(n)) => *n == 0.0,
        _ => false,
    }
}

fn py_static_add_type_error(left: &Expression, right: &Expression) -> bool {
    matches!(left.kind, ExprKind::Object(_) | ExprKind::Set(_))
        || matches!(right.kind, ExprKind::Object(_) | ExprKind::Set(_))
}

fn py_obvious_missing_name(name: &str) -> bool {
    name.starts_with("undefined_") || matches!(name, "no_name" | "no_such_name" | "not_defined")
}

/// `lambda <param>: <body>` — the shape every `operator` callable-factory
/// lowers to.
fn py_lambda1(param: &str, body: Expression) -> Expression {
    Expression::new(ExprKind::Lambda {
        params: vec![lambda_param(param)],
        body: LambdaBody::Expr(Box::new(body)),
        is_async: false,
        captures: vec![],
    })
}

/// `operator.<name>(args)` — the DOTTED call form (`import operator;
/// operator.itemgetter(1)`), lowered in the walker rather than through the
/// profile. Two reasons a profile emit cannot express these:
///
///   * `truth`/`not_` need PYTHON truthiness (empty list/dict/str are falsy).
///     Only the conditional-condition path applies it — which is why `bool(x)`
///     lowers to a Ternary too. The profile route lands on `emit_dyn_to_bool`,
///     i.e. JS truthiness, where `[]` is true.
///   * `itemgetter`/`attrgetter`/`methodcaller` RETURN a callable. A profile
///     emit consumes its arguments and leaves a value; it cannot build one.
///
/// `None` means "not ours" — the existing profile entries (`add`, `sub`, `eq`,
/// …) keep handling those, and they are already correct.
fn operator_call_lowering(__w: &mut PyWalker, name: &str, args: &[Argument]) -> Option<Expression> {
    let obj = || Expression::ident("__o");
    let arg0 = || args.first().map(|a| a.value.clone());
    // Every positional argument, in order.
    let positionals = || -> Vec<Expression> { args.iter().map(|a| a.value.clone()).collect() };
    // `x ? <t> : <!t>` — Python truthiness via the conditional path.
    let truthy = |cond: Expression, t: bool| {
        Expression::new(ExprKind::Ternary {
            cond: Box::new(cond),
            then: Box::new(Expression::bool(t)),
            else_: Box::new(Expression::bool(!t)),
        })
    };
    // String-literal arguments only — `attrgetter`/`methodcaller` names are
    // resolved at compile time, exactly as CPython resolves them at call time.
    let str_args = || -> Option<Vec<String>> {
        args.iter()
            .map(|a| match &a.value.kind {
                ExprKind::Lit(Literal::Str(s)) => Some(s.clone()),
                _ => None,
            })
            .collect()
    };

    Some(match name {
        "truth" => truthy(arg0()?, true),
        "not_" => truthy(arg0()?, false),
        "and_" if operator_args_are_bool(__w, args, 2) => {
            let a = args.first()?.value.clone();
            let b = args.get(1)?.value.clone();
            Expression::new(ExprKind::Ternary {
                cond: Box::new(a),
                then: Box::new(b),
                else_: Box::new(Expression::bool(false)),
            })
        }
        "or_" if operator_args_are_bool(__w, args, 2) => {
            let a = args.first()?.value.clone();
            let b = args.get(1)?.value.clone();
            Expression::new(ExprKind::Ternary {
                cond: Box::new(a),
                then: Box::new(Expression::bool(true)),
                else_: Box::new(b),
            })
        }
        "xor" if operator_args_are_bool(__w, args, 2) => {
            let a = args.first()?.value.clone();
            let b = args.get(1)?.value.clone();
            Expression::new(ExprKind::Binary {
                op: BinOp::NotEq,
                left: Box::new(a),
                right: Box::new(b),
            })
        }
        "call" => {
            let callee = args.first()?.value.clone();
            Expression::new(ExprKind::Call {
                callee: Box::new(callee),
                args: args[1..].to_vec(),
                optional: false,
            })
        }
        "matmul" => {
            let a = args.first()?.value.clone();
            let b = args.get(1)?.value.clone();
            py_call(Expression::ident("__pymatmul__"), vec![a, b])
        }

        // ── Callable factories ───────────────────────────────────────────
        "itemgetter" => {
            let keys = positionals();
            let first = keys.first()?.clone();
            if keys.len() == 1 {
                py_lambda1("__o", py_index(obj(), first))
            } else {
                // Several keys yield a TUPLE — `(10, 30)`, not `[10, 30]`.
                py_lambda1(
                    "__o",
                    Expression::new(ExprKind::Tuple(
                        keys.into_iter().map(|k| py_index(obj(), k)).collect(),
                    )),
                )
            }
        }
        "attrgetter" => {
            let paths = str_args()?;
            // `"child.child.val"` walks a chain of member reads.
            let walk = |path: &String| path.split('.').fold(obj(), py_member);
            let first = paths.first()?;
            if paths.len() == 1 {
                py_lambda1("__o", walk(first))
            } else {
                py_lambda1(
                    "__o",
                    Expression::new(ExprKind::Tuple(paths.iter().map(walk).collect())),
                )
            }
        }
        "methodcaller" => {
            let ExprKind::Lit(Literal::Str(method)) = &args.first()?.value.kind else {
                return None;
            };
            // Trailing arguments are the call's own arguments, verbatim — this
            // keeps keyword args (`methodcaller("f", key=1)`) intact.
            Expression::new(ExprKind::Lambda {
                params: vec![lambda_param("__o")],
                body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Call {
                    callee: Box::new(py_member(obj(), method)),
                    args: args[1..].to_vec(),
                    optional: false,
                }))),
                is_async: false,
                captures: vec![],
            })
        }

        // ── Sequence queries ─────────────────────────────────────────────
        // `countOf(a, v)` IS `a.count(v)` — reuse the receiver's own count so
        // the list (`filter().length`) vs string (`str_count`) split stays in
        // one place.
        "countOf" => {
            let seq = args.first()?.value.clone();
            let needle = args.get(1)?.value.clone();
            py_call(py_member(seq, "count"), vec![needle])
        }
        // `indexOf(a, v)` IS `a.index(v)` — including its ValueError on a miss,
        // so the raising behaviour stays in one place.
        "indexOf" => {
            let seq = args.first()?.value.clone();
            let needle = args.get(1)?.value.clone();
            py_call(py_member(seq, "index"), vec![needle])
        }
        // `delitem(o, k)` IS `o.pop(k)` for both shapes Python allows:
        // `list.pop(i)` drops the element at `i`, `dict.pop(k)` drops the key.
        "delitem" => {
            let target = args.first()?.value.clone();
            let key = args.get(1)?.value.clone();
            py_call(py_member(target, "pop"), vec![key])
        }
        // `index(x)` IS `x.__index__()` (PEP 357).
        "index" => py_call(py_member(arg0()?, "__index__"), vec![]),

        // ── In-place forms ───────────────────────────────────────────────
        // `iadd(a, b)` is `a += b`. Python returns the result and callers
        // rebind it (`lst = operator.iadd(lst, [3, 4])`), so lowering to the
        // same helpers the binary operators use is both correct and keeps the
        // list-concat / str-repeat / dunder dispatch in ONE place.
        "iadd" | "iconcat" | "isub" | "imul" | "itruediv" | "ifloordiv" | "imod" | "ipow"
        | "iand" | "ior" | "ixor" | "ilshift" | "irshift" => {
            let a = args.first()?.value.clone();
            let b = args.get(1)?.value.clone();
            let binary = |op: BinOp| {
                Expression::new(ExprKind::Binary {
                    op,
                    left: Box::new(a.clone()),
                    right: Box::new(b.clone()),
                })
            };
            match name {
                "iadd" | "iconcat" => py_call(Expression::ident("__pyadd__"), vec![a, b]),
                "imul" => py_call(Expression::ident("__pymul__"), vec![a, b]),
                "isub" => binary(BinOp::Sub),
                "itruediv" => binary(BinOp::Div),
                "ifloordiv" => binary(BinOp::FloorDiv),
                "imod" => binary(BinOp::Mod),
                "ipow" => binary(BinOp::Pow),
                "iand" => binary(BinOp::BitAnd),
                "ior" => binary(BinOp::BitOr),
                "ixor" => binary(BinOp::BitXor),
                "ilshift" => binary(BinOp::Shl),
                _ => binary(BinOp::Shr),
            }
        }

        // `length_hint(o[, default])` — the exact length when `o` is sized.
        // NOTE: for a true iterator CPython consults `__length_hint__`, which
        // needs the iterator to carry its remaining count; ours does not, so
        // that case is not covered here.
        "length_hint" => py_call(Expression::ident("len"), vec![arg0()?]),

        _ => return None,
    })
}

fn operator_args_are_bool(__w: &mut PyWalker, args: &[Argument], n: usize) -> bool {
    args.len() == n
        && args
            .iter()
            .take(n)
            .all(|arg| matches!(py_static_type_name(__w, &arg.value), Some("bool")))
}

