fn lambda_param(name: &str) -> Param {
    Param {
        name: name.into(),
        type_hint: None,
        default: None,
        pass_by: PassBy::Value,
        is_rest: false,
        is_kwargs: false,
        is_optional: false,
        is_nullable: false,
    }
}

fn lambda_rest_param(name: &str) -> Param {
    Param {
        is_rest: true,
        ..lambda_param(name)
    }
}

#[allow(dead_code)]
fn lambda_param_optional(name: &str, default: Expression) -> Param {
    Param {
        name: name.into(),
        type_hint: None,
        default: Some(default),
        pass_by: PassBy::Value,
        is_rest: false,
        is_kwargs: false,
        is_optional: true,
        is_nullable: false,
    }
}

fn py_builtin_callable_lambda(name: &str) -> Option<Expression> {
    let param = "__py_key_value";
    Some(match name {
        "bool" => py_lambda1(
            param,
            Expression::new(ExprKind::Ternary {
                cond: Box::new(Expression::new(ExprKind::Ident(param.into()))),
                then: Box::new(Expression::bool(true)),
                else_: Box::new(Expression::bool(false)),
            }),
        ),
        "len" | "abs" | "str" | "int" | "float" | "chr" | "ord" => {
            Expression::new(ExprKind::Lambda {
                params: vec![lambda_param(param)],
                body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Call {
                    callee: Box::new(Expression::new(ExprKind::Ident(name.into()))),
                    args: vec![Argument::positional(Expression::new(ExprKind::Ident(
                        param.into(),
                    )))],
                    optional: false,
                }))),
                is_async: false,
                captures: vec![],
            })
        }
        _ => return None,
    })
}

fn py_builtin_binary_callable_lambda(name: &str) -> Option<Expression> {
    let helper2 = |helper: &str| -> Expression {
        Expression::new(ExprKind::Lambda {
            params: vec![lambda_param("__a"), lambda_param("__b")],
            body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Call {
                callee: Box::new(Expression::new(ExprKind::Ident(helper.into()))),
                args: vec![
                    Argument::positional(Expression::new(ExprKind::Ident("__a".into()))),
                    Argument::positional(Expression::new(ExprKind::Ident("__b".into()))),
                ],
                optional: false,
            }))),
            is_async: false,
            captures: vec![],
        })
    };
    let choose = |op: BinOp, then_name: &str, else_name: &str| -> Expression {
        Expression::new(ExprKind::Lambda {
            params: vec![lambda_param("__a"), lambda_param("__b")],
            body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Ternary {
                cond: Box::new(Expression::new(ExprKind::Binary {
                    op,
                    left: Box::new(Expression::new(ExprKind::Ident("__a".into()))),
                    right: Box::new(Expression::new(ExprKind::Ident("__b".into()))),
                })),
                then: Box::new(Expression::new(ExprKind::Ident(then_name.into()))),
                else_: Box::new(Expression::new(ExprKind::Ident(else_name.into()))),
            }))),
            is_async: false,
            captures: vec![],
        })
    };
    Some(match name {
        "max" => choose(BinOp::GtEq, "__a", "__b"),
        "min" => choose(BinOp::LtEq, "__a", "__b"),
        "pow" => helper2("__pypow__"),
        _ => return None,
    })
}

fn py_identity_lambda(param: &str) -> Expression {
    Expression::new(ExprKind::Lambda {
        params: vec![lambda_param(param)],
        body: LambdaBody::Expr(Box::new(Expression::ident(param))),
        is_async: false,
        captures: vec![],
    })
}

fn py_identity_decorator() -> Expression {
    py_identity_lambda("__py_decorated")
}

fn py_partial_lambda(args: &[Argument]) -> Option<Expression> {
    let func = args.first()?.value.clone();
    let bound_args = Expression::new(ExprKind::Array(
        args.iter()
            .skip(1)
            .filter(|arg| arg.name.is_none())
            .map(|arg| ArrayElement {
                key: None,
                spread: false,
                by_ref: false,
                value: arg.value.clone(),
            })
            .collect(),
    ));
    let combined_args = call_ident(
        "__pyadd__",
        vec![bound_args, Expression::ident("__py_partial_args")],
    );
    let apply_call = call_ident(
        "__py_reflect_apply",
        vec![func, Expression::null(), combined_args],
    );
    Some(Expression::new(ExprKind::Lambda {
        params: vec![Param {
            name: "__py_partial_args".to_string(),
            type_hint: None,
            default: None,
            pass_by: PassBy::Value,
            is_rest: true,
            is_kwargs: false,
            is_optional: false,
            is_nullable: false,
        }],
        body: LambdaBody::Expr(Box::new(apply_call)),
        is_async: false,
        captures: vec![],
    }))
}

fn functools_cmp_to_key_arg(expr: &Expression) -> Option<Expression> {
    let ExprKind::Call { callee, args, .. } = &expr.kind else {
        return None;
    };
    if args.len() != 1 || args[0].name.is_some() {
        return None;
    }
    match &callee.kind {
        ExprKind::Ident(name) if name == "cmp_to_key" => Some(args[0].value.clone()),
        ExprKind::Member { object, field, .. }
            if field == "cmp_to_key"
                && matches!(&object.kind, ExprKind::Ident(module) if module == "functools") =>
        {
            Some(args[0].value.clone())
        }
        _ => None,
    }
}

fn functools_call_lowering(callee: &Expression, args: &[Argument]) -> Option<ExprKind> {
    let ExprKind::Ident(name) = &callee.kind else {
        return None;
    };
    match name.as_str() {
        "partial" | "partialmethod" => py_partial_lambda(args).map(|e| e.kind),
        "cmp_to_key" => Some(py_identity_lambda("__py_cmp_key").kind),
        "cache" | "singledispatch" if args.len() == 1 && args[0].name.is_none() => {
            Some(args[0].value.clone().kind)
        }
        "lru_cache" if args.len() == 1 && args[0].name.is_none() => Some(args[0].value.clone().kind),
        "lru_cache" => Some(py_identity_decorator().kind),
        _ => None,
    }
}

fn normalize_python_binary_callable_arg(arg: &mut Argument) {
    if let ExprKind::Ident(name) = &arg.value.kind
        && let Some(lambda) = py_builtin_binary_callable_lambda(name)
    {
        arg.value = lambda;
    }
}

fn py_string_method_callable_lambda(field: &str) -> Option<Expression> {
    let helper = match field {
        "isdigit" => "__py_str_isdigit",
        "isalpha" => "__py_str_isalpha",
        "isalnum" => "__py_str_isalnum",
        "isspace" => "__py_str_isspace",
        _ => return None,
    };
    let param = "__py_str_value";
    Some(py_lambda1(
        param,
        call_ident(helper, vec![Expression::new(ExprKind::Ident(param.into()))]),
    ))
}

fn py_bound_method_callable_lambda(object: Expression, field: &str) -> Expression {
    if field == "append" {
        return py_lambda1(
            "__py_bound_arg",
            Expression::new(ExprKind::Call {
                callee: Box::new(py_member(object, field)),
                args: vec![Argument::positional(Expression::ident("__py_bound_arg"))],
                optional: false,
            }),
        );
    }
    Expression::new(ExprKind::Lambda {
        params: vec![lambda_rest_param("__py_bound_args")],
        body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Call {
            callee: Box::new(py_member(object, field)),
            args: vec![Argument {
                value: Expression::ident("__py_bound_args"),
                name: None,
                by_ref: false,
                spread: true,
            }],
            optional: false,
        }))),
        is_async: false,
        captures: vec![],
    })
}

fn py_callable_expr(__w: &mut PyWalker, value: Expression) -> Expression {
    if py_known_data_member_read(__w, &value) {
        return value;
    }
    match &value.kind {
        ExprKind::Ident(name) => py_builtin_callable_lambda(name).unwrap_or(value),
        ExprKind::Call { callee, args, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_attr_read")
                && args.len() == 2 =>
        {
            if let ExprKind::Lit(Literal::Str(field)) = &args[1].value.kind {
                if is_known_python_data_member_name(field) {
                    return value;
                }
                py_bound_method_callable_lambda(args[0].value.clone(), field)
            } else {
                value
            }
        }
        ExprKind::Member { object, field, .. } if matches!(&object.kind, ExprKind::Ident(n) if n == "str") => {
            py_string_method_callable_lambda(field).unwrap_or(value)
        }
        ExprKind::Member { field, .. } if field == "queue" => value,
        ExprKind::Member { object, field, .. } => {
            py_bound_method_callable_lambda((**object).clone(), field)
        }
        ExprKind::Index { object, index, .. } if matches!(&object.kind, ExprKind::Ident(n) if n == "str") => {
            if let ExprKind::Lit(Literal::Str(field)) = &index.kind {
                py_string_method_callable_lambda(field).unwrap_or(value)
            } else {
                value
            }
        }
        ExprKind::Index { index, .. } if matches!(&index.kind, ExprKind::Lit(Literal::Str(_))) => {
            Expression::new(ExprKind::Lambda {
                params: vec![lambda_rest_param("__py_bound_args")],
                body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Call {
                    callee: Box::new(value),
                    args: vec![Argument {
                        value: Expression::ident("__py_bound_args"),
                        name: None,
                        by_ref: false,
                        spread: true,
                    }],
                    optional: false,
                }))),
                is_async: false,
                captures: vec![],
            })
        }
        _ => value,
    }
}

fn is_known_python_data_member_name(field: &str) -> bool {
    matches!(
        field,
        "queue" | "name" | "mode" | "closed" | "traceback" | "filename" | "lineno" | "size"
            | "size_diff" | "count_diff"
    )
}

fn py_known_data_member_read(__w: &mut PyWalker, value: &Expression) -> bool {
    let (object, field) = match &value.kind {
        ExprKind::Member { object, field, .. } => (object.as_ref(), field.as_str()),
        _ => match py_attr_read_parts(value) {
            Some((object, field)) => (object, field),
            None => return false,
        },
    };
    match &object.kind {
        ExprKind::Ident(var) => {
            if let Some(class_name) = instance_class(__w, var) {
                class_has_data_attr(__w, &class_name, field)
                    || class_has_property(__w, &class_name, field)
            } else if is_defined_class(__w, var) {
                class_has_data_attr(__w, var, field) || class_has_property(__w, var, field)
            } else {
                false
            }
        }
        ExprKind::New { class, .. } => match &class.kind {
            ExprKind::Ident(class_name) => {
                class_has_data_attr(__w, class_name, field)
                    || class_has_property(__w, class_name, field)
            }
            _ => false,
        },
        _ => false,
    }
}

fn py_bound_data_member_read(value: &Expression) -> Option<Expression> {
    let ExprKind::Lambda { params, body, .. } = &value.kind else {
        return None;
    };
    if params.len() != 1 || !params[0].is_rest || params[0].name != "__py_bound_args" {
        return None;
    }
    let LambdaBody::Expr(body) = body else {
        return None;
    };
    let ExprKind::Call { callee, args, .. } = &body.kind else {
        return None;
    };
    let ExprKind::Member { object, field, null_safe } = &callee.kind else {
        return None;
    };
    if *null_safe || !is_known_python_data_member_name(field) {
        return None;
    }
    if args.len() != 1
        || !args[0].spread
        || !matches!(&args[0].value.kind, ExprKind::Ident(name) if name == "__py_bound_args")
    {
        return None;
    }
    Some(Expression::new(ExprKind::Member {
        object: object.clone(),
        field: field.clone(),
        null_safe: false,
    }))
}

fn lower_class_getitem_reads_in_assignment_target(
    __w: &mut PyWalker,
    target: Expression,
) -> Expression {
    match target.kind {
        ExprKind::Index {
            object,
            index,
            null_safe,
        } => Expression::new(ExprKind::Index {
            object: Box::new(lower_class_getitem_assignment_receiver(__w, *object)),
            index,
            null_safe,
        }),
        _ => target,
    }
}

fn lower_class_getitem_assignment_receiver(
    __w: &mut PyWalker,
    object: Expression,
) -> Expression {
    match object.kind {
        ExprKind::Index {
            object,
            index,
            null_safe,
        } => {
            let receiver = lower_class_getitem_assignment_receiver(__w, *object);
            let has_getitem = if let ExprKind::Ident(var) = &receiver.kind {
                instance_class(__w, var)
                    .as_deref()
                    .is_some_and(|class_name| class_has_attr(__w, class_name, "__getitem__"))
            } else {
                false
            };
            if has_getitem {
                py_call(py_member(receiver, "__getitem__"), vec![*index])
            } else {
                Expression::new(ExprKind::Index {
                    object: Box::new(receiver),
                    index,
                    null_safe,
                })
            }
        }
        _ => object,
    }
}

fn normalize_heapq_key_callable(mut args: Vec<Argument>) -> Vec<Argument> {
    for arg in &mut args {
        if arg.name.as_deref() == Some("key")
            && let ExprKind::Ident(name) = &arg.value.kind
            && let Some(lambda) = py_builtin_callable_lambda(name)
        {
            arg.value = lambda;
        }
    }
    args
}

// ════════════════════════════════════════════════════════════════════════════
// Statements
// ════════════════════════════════════════════════════════════════════════════

fn walk_statement(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<Statement, String> {
    let span = to_span(&pair);
    let kind = match pair.as_rule() {
        Rule::pass_stmt => StmtKind::Empty,
        Rule::break_stmt | Rule::break_inline => StmtKind::Break(BreakTarget::Implicit),
        Rule::continue_stmt | Rule::continue_inline => StmtKind::Continue(ContinueTarget::Implicit),

        Rule::function_def => walk_func_def(__w, pair, false, Vec::new())?,
        Rule::class_def => {
            let __d = walk_class_def(__w, pair, Vec::new())?;
            desugar_descriptor_set_name(__w, __d)
        }
        Rule::decorated_def => walk_decorated(__w, pair)?,
        Rule::async_stmt => walk_async_stmt(__w, pair)?,

        Rule::if_stmt => walk_if(__w, pair)?,
        Rule::while_stmt => walk_while(__w, pair)?,
        Rule::for_stmt => walk_for(__w, pair, false)?,
        Rule::try_stmt => walk_try(__w, pair)?,
        Rule::with_stmt => walk_with(__w, pair, false)?,
        Rule::match_stmt => walk_match(__w, pair)?,

        Rule::return_stmt | Rule::return_inline => walk_return(__w, pair)?,
        Rule::raise_stmt | Rule::raise_inline => walk_raise(__w, pair)?,
        Rule::del_stmt | Rule::del_inline => walk_del(__w, pair)?,
        Rule::assert_stmt | Rule::assert_inline => walk_assert(__w, pair)?,
        Rule::global_stmt | Rule::global_inline => walk_scope_decl(pair, ScopeDeclKind::Global)?,
        Rule::nonlocal_stmt | Rule::nonlocal_inline => {
            walk_scope_decl(pair, ScopeDeclKind::Nonlocal)?
        }

        Rule::import_stmt => {
            // Nested imports (inside try/if bodies) still mount the module
            // for compile-time resolution; the statement itself is a no-op —
            // unless the module is outside the known universe, which raises
            // ImportError right here (CPython §import semantics), catchable
            // by the enclosing try.
            let import = walk_import(__w, pair)?;
            if let ImportKind::Simple { path, .. } = &import.kind {
                let root = path.split('.').next().unwrap_or(path);
                if dynamic_module_registry_var(__w, path).is_some() {
                    return Ok(Statement::new(StmtKind::Empty));
                }
                if !py_known_module(root) {
                    return Ok(py_import_error_stmt(&format!("No module named '{root}'")));
                }
            }
            return Ok(Statement::new(StmtKind::Empty));
        }
        Rule::import_from_stmt => {
            let import = walk_import_from(__w, pair)?;
            if let ImportKind::Named { path, names, level } = &import.kind {
                let root = path.split('.').next().unwrap_or(path);
                if *level == 0 && !path.is_empty() && path != "__future__" {
                    if dynamic_module_registry_var(__w, path).is_some() {
                        return Ok(Statement::new(StmtKind::Empty));
                    }
                    if !py_known_module(root) {
                        return Ok(py_import_error_stmt(&format!("No module named '{root}'")));
                    }
                    if let Some(surface) = py_module_surface(path) {
                        let renames = py_module_renames(path).unwrap_or(&[]);
                        for n in names {
                            if !surface.contains(&n.name.as_str())
                                && !renames.iter().any(|(py, canon)| {
                                    *py == n.name.as_str() || *canon == n.name.as_str()
                                })
                            {
                                return Ok(py_import_error_stmt(&format!(
                                    "cannot import name '{}' from '{}'",
                                    n.name, path
                                )));
                            }
                        }
                    }
                }
            }
            return Ok(Statement::new(StmtKind::Empty));
        }

        Rule::expr_or_assign_stmt | Rule::expr_or_assign_inline => walk_expr_or_assign(__w, pair)?,

        Rule::pass_inline => StmtKind::Empty,

        Rule::NEWLINE | Rule::INDENT | Rule::DEDENT => StmtKind::Empty,

        other => return Err(format!("Unexpected statement rule: {:?}", other)),
    };
    Ok(Statement::with_span(kind, span))
}

// ── Generator → eager collection helpers ────────────────────────────────────

/// Recursively check if a statement list contains any Yield expressions.
fn body_has_yield(stmts: &[Statement]) -> bool {
    stmts.iter().any(|s| stmt_has_yield(s))
}

fn stmt_has_yield(stmt: &Statement) -> bool {
    match &stmt.kind {
        StmtKind::Expr(e) => expr_has_yield(e),
        StmtKind::Return(Some(e)) => expr_has_yield(e),
        StmtKind::Assign { value, .. } => expr_has_yield(value),
        StmtKind::If {
            cond,
            then_body,
            else_body,
            ..
        } => {
            expr_has_yield(cond)
                || body_has_yield(then_body)
                || else_body.as_ref().map_or(false, |eb| body_has_yield(eb))
        }
        StmtKind::While { cond, body, .. } => expr_has_yield(cond) || body_has_yield(body),
        StmtKind::ForIn { body, .. } => body_has_yield(body),
        StmtKind::Try {
            body,
            catches,
            finally,
            ..
        } => {
            body_has_yield(body)
                || catches.iter().any(|cb| body_has_yield(&cb.body))
                || finally.as_ref().map_or(false, |fb| body_has_yield(fb))
        }
        StmtKind::With { body, .. } => body_has_yield(body),
        _ => false,
    }
}

fn expr_has_yield(expr: &Expression) -> bool {
    match &expr.kind {
        ExprKind::Yield(_) | ExprKind::YieldFrom(_) => true,
        ExprKind::Call { args, .. } => args.iter().any(|a| expr_has_yield(&a.value)),
        ExprKind::Binary { left, right, .. } => expr_has_yield(left) || expr_has_yield(right),
        ExprKind::Unary { expr: e, .. } => expr_has_yield(e),
        ExprKind::Index { object, index, .. } => expr_has_yield(object) || expr_has_yield(index),
        _ => false,
    }
}

fn normalize_pickle_reduce_returns(stmts: &mut [Statement]) {
    for stmt in stmts {
        match &mut stmt.kind {
            StmtKind::ClassDecl { members, .. } => {
                for member in members {
                    match member {
                        ClassMember::Method(method) => {
                            if let StmtKind::FunctionDecl { name, body, .. } = &mut method.kind {
                                if name == "__reduce__" {
                                    normalize_pickle_reduce_return_body(body);
                                } else {
                                    normalize_pickle_reduce_returns(body);
                                }
                            }
                        }
                        ClassMember::Constructor { body, .. } => {
                            normalize_pickle_reduce_returns(body);
                        }
                        ClassMember::NestedType(nested) => {
                            normalize_pickle_reduce_returns(std::slice::from_mut(nested.as_mut()));
                        }
                        ClassMember::Property { getter, setter, .. } => {
                            if let Some(body) = getter {
                                normalize_pickle_reduce_returns(body);
                            }
                            if let Some(setter) = setter {
                                normalize_pickle_reduce_returns(&mut setter.body);
                            }
                        }
                        _ => {}
                    }
                }
            }
            StmtKind::FunctionDecl { body, .. } => normalize_pickle_reduce_returns(body),
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                normalize_pickle_reduce_returns(then_body);
                for (_, body) in elifs {
                    normalize_pickle_reduce_returns(body);
                }
                if let Some(body) = else_body {
                    normalize_pickle_reduce_returns(body);
                }
            }
            StmtKind::While {
                body, else_body, ..
            }
            | StmtKind::ForIn {
                body, else_body, ..
            } => {
                normalize_pickle_reduce_returns(body);
                if let Some(body) = else_body {
                    normalize_pickle_reduce_returns(body);
                }
            }
            StmtKind::For { body, .. }
            | StmtKind::Block(body)
            | StmtKind::NamespaceDecl { body, .. } => normalize_pickle_reduce_returns(body),
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                normalize_pickle_reduce_returns(body);
                for catch in catches {
                    normalize_pickle_reduce_returns(&mut catch.body);
                }
                if let Some(body) = else_body {
                    normalize_pickle_reduce_returns(body);
                }
                if let Some(body) = finally {
                    normalize_pickle_reduce_returns(body);
                }
            }
            StmtKind::With { body, .. } => normalize_pickle_reduce_returns(body),
            _ => {}
        }
    }
}

fn normalize_pickle_reduce_return_body(stmts: &mut [Statement]) {
    for stmt in stmts {
        match &mut stmt.kind {
            StmtKind::Return(Some(expr)) => normalize_pickle_reduce_return_expr(expr),
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                normalize_pickle_reduce_return_body(then_body);
                for (_, body) in elifs {
                    normalize_pickle_reduce_return_body(body);
                }
                if let Some(body) = else_body {
                    normalize_pickle_reduce_return_body(body);
                }
            }
            StmtKind::While {
                body, else_body, ..
            }
            | StmtKind::ForIn {
                body, else_body, ..
            } => {
                normalize_pickle_reduce_return_body(body);
                if let Some(body) = else_body {
                    normalize_pickle_reduce_return_body(body);
                }
            }
            StmtKind::For { body, .. } | StmtKind::Block(body) => {
                normalize_pickle_reduce_return_body(body);
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                normalize_pickle_reduce_return_body(body);
                for catch in catches {
                    normalize_pickle_reduce_return_body(&mut catch.body);
                }
                if let Some(body) = else_body {
                    normalize_pickle_reduce_return_body(body);
                }
                if let Some(body) = finally {
                    normalize_pickle_reduce_return_body(body);
                }
            }
            StmtKind::With { body, .. } => normalize_pickle_reduce_return_body(body),
            StmtKind::FunctionDecl { .. } | StmtKind::ClassDecl { .. } => {}
            _ => {}
        }
    }
}

fn normalize_pickle_reduce_return_expr(expr: &mut Expression) {
    let ExprKind::Tuple(items) = &expr.kind else {
        return;
    };
    if items.len() != 2 {
        return;
    }
    let ctor = items[0].clone();
    let mut args = vec![Argument::positional(ctor)];
    match &items[1].kind {
        ExprKind::Tuple(inner) => {
            args.extend(inner.iter().cloned().map(Argument::positional));
        }
        ExprKind::Array(elements)
            if elements
                .iter()
                .all(|element| element.key.is_none() && !element.spread) =>
        {
            args.extend(
                elements
                    .iter()
                    .map(|element| Argument::positional(element.value.clone())),
            );
        }
        _ => args.push(Argument::positional(items[1].clone())),
    };
    expr.kind = ExprKind::Call {
        callee: Box::new(Expression::ident("__py_pickle_reduce")),
        args,
        optional: false,
    };
}

fn add_core_class_data_fields(stmts: &mut [Statement]) {
    for stmt in stmts {
        let StmtKind::ClassDecl { name, members, .. } = &mut stmt.kind else {
            continue;
        };
        let Some((_, attrs)) = crate::core_classes::CLASS_DATA_ATTRS
            .iter()
            .find(|(class_name, _)| *class_name == name)
        else {
            continue;
        };
        for attr in *attrs {
            let exists = members
                .iter()
                .any(|member| matches!(member, ClassMember::Field { name, .. } if name == attr));
            if exists {
                continue;
            }
            members.push(ClassMember::Field {
                name: (*attr).to_string(),
                type_hint: None,
                init: None,
                modifiers: Modifiers::default(),
                with_events: false,
                array_bounds: None,
                storage: None,
            });
        }
    }
}

fn normalize_python_operand_bool_expr(expr: &mut Expression) {
    let ExprKind::Binary { op, left, right } = &mut expr.kind else {
        return;
    };
    if let Some(folded) = fold_python_literal_bitwise(*op, left, right) {
        expr.kind = folded.kind;
        return;
    }
    if !matches!(op, BinOp::And | BinOp::Or) {
        return;
    }

    let left_value = (**left).clone();
    let right_value = (**right).clone();
    expr.kind = match op {
        BinOp::And => ExprKind::Ternary {
            cond: Box::new(left_value.clone()),
            then: Box::new(right_value),
            else_: Box::new(left_value),
        },
        BinOp::Or => ExprKind::Ternary {
            cond: Box::new(left_value.clone()),
            then: Box::new(left_value),
            else_: Box::new(right_value),
        },
        _ => unreachable!(),
    };
}

fn fold_python_literal_bitwise(op: BinOp, left: &Expression, right: &Expression) -> Option<Expression> {
    match (&left.kind, &right.kind) {
        (ExprKind::Lit(Literal::Bool(a)), ExprKind::Lit(Literal::Bool(b))) => {
            let value = match op {
                BinOp::BitAnd => *a & *b,
                BinOp::BitOr => *a | *b,
                BinOp::BitXor => *a ^ *b,
                _ => return None,
            };
            Some(Expression::bool(value))
        }
        (ExprKind::Lit(Literal::Int(a)), ExprKind::Lit(Literal::Int(b))) => {
            let value = match op {
                BinOp::BitAnd => a & b,
                BinOp::BitOr => a | b,
                BinOp::BitXor => a ^ b,
                BinOp::Shl => a.checked_shl((*b).try_into().ok()?)?,
                BinOp::Shr => a.checked_shr((*b).try_into().ok()?)?,
                _ => return None,
            };
            Some(Expression::int(value))
        }
        _ => None,
    }
}

fn collect_python_function_local_names(body: &[Statement]) -> Vec<String> {
    let mut assigned = HashSet::new();
    let mut opened = HashSet::new();
    for stmt in body {
        collect_python_function_local_names_stmt(stmt, &mut assigned, &mut opened);
    }
    let mut names: Vec<String> = assigned
        .into_iter()
        .filter(|name| !opened.contains(name))
        .collect();
    names.sort();
    names
}

fn collect_python_function_param_names(body: &[Statement], out: &mut HashSet<String>) {
    for stmt in body {
        match &stmt.kind {
            StmtKind::FunctionDecl { params, body, .. } => {
                out.extend(params.iter().map(|param| param.name.clone()));
                collect_python_function_param_names(body, out);
            }
            StmtKind::ClassDecl { members, .. } => {
                for member in members {
                    if let ClassMember::Method(method) = member
                        && let StmtKind::FunctionDecl { params, body, .. } = &method.kind
                    {
                        out.extend(params.iter().map(|param| param.name.clone()));
                        collect_python_function_param_names(body, out);
                    }
                }
            }
            StmtKind::Block(body)
            | StmtKind::With { body, .. }
            | StmtKind::NamespaceDecl { body, .. } => collect_python_function_param_names(body, out),
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                collect_python_function_param_names(then_body, out);
                for (_, body) in elifs {
                    collect_python_function_param_names(body, out);
                }
                if let Some(body) = else_body {
                    collect_python_function_param_names(body, out);
                }
            }
            StmtKind::For { body, .. } => {
                collect_python_function_param_names(body, out);
            }
            StmtKind::While { body, else_body, .. } => {
                collect_python_function_param_names(body, out);
                if let Some(body) = else_body {
                    collect_python_function_param_names(body, out);
                }
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                collect_python_function_param_names(body, out);
                for catch in catches {
                    collect_python_function_param_names(&catch.body, out);
                }
                if let Some(body) = else_body {
                    collect_python_function_param_names(body, out);
                }
                if let Some(body) = finally {
                    collect_python_function_param_names(body, out);
                }
            }
            _ => {}
        }
    }
}

fn collect_python_function_local_names_stmt(
    stmt: &Statement,
    assigned: &mut HashSet<String>,
    opened: &mut HashSet<String>,
) {
    match &stmt.kind {
        StmtKind::ScopeDecl {
            kind: ScopeDeclKind::Global | ScopeDeclKind::Nonlocal,
            names,
        } => {
            opened.extend(names.iter().cloned());
        }
        StmtKind::VarDecl { declarations, .. } => {
            for decl in declarations {
                collect_python_function_local_names_pattern(&decl.pattern, assigned);
            }
        }
        StmtKind::Assign { targets, .. } => {
            for target in targets {
                collect_python_function_local_names_target(target, assigned);
            }
        }
        StmtKind::CompoundAssign { target, .. } => {
            collect_python_function_local_names_target(target, assigned);
        }
        StmtKind::ForIn {
            var,
            key,
            body,
            else_body,
            ..
        } => {
            assigned.insert(var.clone());
            if let Some(key) = key {
                assigned.insert(key.clone());
            }
            collect_python_function_local_names_body(body, assigned, opened);
            if let Some(body) = else_body {
                collect_python_function_local_names_body(body, assigned, opened);
            }
        }
        StmtKind::With { items, body, .. } => {
            for item in items {
                if let Some(var) = &item.var {
                    assigned.insert(var.clone());
                }
            }
            collect_python_function_local_names_body(body, assigned, opened);
        }
        StmtKind::If {
            then_body,
            elifs,
            else_body,
            ..
        } => {
            collect_python_function_local_names_body(then_body, assigned, opened);
            for (_, body) in elifs {
                collect_python_function_local_names_body(body, assigned, opened);
            }
            if let Some(body) = else_body {
                collect_python_function_local_names_body(body, assigned, opened);
            }
        }
        StmtKind::While {
            body, else_body, ..
        } => {
            collect_python_function_local_names_body(body, assigned, opened);
            if let Some(body) = else_body {
                collect_python_function_local_names_body(body, assigned, opened);
            }
        }
        StmtKind::For { body, .. }
        | StmtKind::Block(body)
        | StmtKind::NamespaceDecl { body, .. } => {
            collect_python_function_local_names_body(body, assigned, opened);
        }
        StmtKind::Try {
            body,
            catches,
            else_body,
            finally,
        } => {
            collect_python_function_local_names_body(body, assigned, opened);
            for catch in catches {
                if let Some(var) = &catch.var_name {
                    assigned.insert(var.clone());
                }
                collect_python_function_local_names_body(&catch.body, assigned, opened);
            }
            if let Some(body) = else_body {
                collect_python_function_local_names_body(body, assigned, opened);
            }
            if let Some(body) = finally {
                collect_python_function_local_names_body(body, assigned, opened);
            }
        }
        StmtKind::ClassDecl { name, .. } | StmtKind::FunctionDecl { name, .. } => {
            assigned.insert(name.clone());
        }
        _ => {}
    }
}

fn collect_python_function_local_names_body(
    body: &[Statement],
    assigned: &mut HashSet<String>,
    opened: &mut HashSet<String>,
) {
    for stmt in body {
        collect_python_function_local_names_stmt(stmt, assigned, opened);
    }
}

fn collect_python_function_local_names_pattern(
    pattern: &BindingPattern,
    assigned: &mut HashSet<String>,
) {
    match pattern {
        BindingPattern::Ident(name) => {
            assigned.insert(name.clone());
        }
        BindingPattern::Object(props) => {
            for prop in props {
                if let Some(value) = &prop.value {
                    collect_python_function_local_names_pattern(value, assigned);
                } else if !prop.is_rest {
                    assigned.insert(prop.key.clone());
                }
            }
        }
        BindingPattern::Array(items) => {
            for item in items {
                match item {
                    ArrayPatternElem::Pattern(pattern, _) => {
                        collect_python_function_local_names_pattern(pattern, assigned);
                    }
                    ArrayPatternElem::Rest(name) => {
                        assigned.insert(name.clone());
                    }
                    ArrayPatternElem::Hole => {}
                }
            }
        }
    }
}

fn collect_python_function_local_names_target(expr: &Expression, assigned: &mut HashSet<String>) {
    match &expr.kind {
        ExprKind::Ident(name) => {
            assigned.insert(name.clone());
        }
        ExprKind::Tuple(items) => {
            for item in items {
                collect_python_function_local_names_target(item, assigned);
            }
        }
        ExprKind::Array(items) => {
            for item in items {
                collect_python_function_local_names_target(&item.value, assigned);
            }
        }
        _ => {}
    }
}

fn prepend_python_function_local_decls(body: &mut Vec<Statement>, params: &[Param]) {
    let params: HashSet<&str> = params.iter().map(|p| p.name.as_str()).collect();
    let locals = collect_python_function_local_names(body);
    let declarations: Vec<vybe_ast::VarDeclarator> = locals
        .into_iter()
        .filter(|name| !params.contains(name.as_str()) && !name.starts_with("__"))
        .map(|name| vybe_ast::VarDeclarator {
            pattern: BindingPattern::Ident(name),
            type_hint: None,
            init: None,
            array_bounds: None,
            with_events: false,
        })
        .collect();
    if declarations.is_empty() {
        return;
    }
    body.insert(
        0,
        Statement::new(StmtKind::VarDecl {
            declarations,
            kind: VarDeclKind::Let,
        }),
    );
}

fn python_rest_tuple_stmt(name: &str) -> Statement {
    Statement::new(StmtKind::Assign {
        targets: vec![Expression::ident(name)],
        value: call_ident("tuple", vec![Expression::ident(name)]),
        by_ref: false,
    })
}

fn prepend_python_rest_tuple_bindings(body: &mut Vec<Statement>, params: &[Param]) {
    let mut insert_at = 0;
    while body
        .get(insert_at)
        .is_some_and(|stmt| matches!(stmt.kind, StmtKind::VarDecl { .. }))
    {
        insert_at += 1;
    }
    for param in params.iter().filter(|param| param.is_rest).rev() {
        body.insert(insert_at, python_rest_tuple_stmt(&param.name));
    }
}

fn normalize_python_nonterminal_rest_params(params: &mut [Param], kinds: &[String]) {
    for (idx, param) in params.iter_mut().enumerate() {
        if !param.is_rest {
            continue;
        }
        let has_later_python_param = kinds
            .iter()
            .skip(idx + 1)
            .any(|kind| kind != "VAR_KEYWORD");
        if has_later_python_param {
            param.is_rest = false;
        }
    }
}

fn python_lambda_param_kinds(params: &[Param]) -> Vec<String> {
    let mut keyword_only = false;
    params
        .iter()
        .map(|param| {
            if param.is_rest {
                keyword_only = true;
                "VAR_POSITIONAL".to_string()
            } else if param.is_kwargs {
                "VAR_KEYWORD".to_string()
            } else if keyword_only {
                "KEYWORD_ONLY".to_string()
            } else {
                "POSITIONAL_OR_KEYWORD".to_string()
            }
        })
        .collect()
}

fn note_lambda_signature(__w: &mut PyWalker, name: &str, value: &Expression) {
    let ExprKind::Lambda { params, body, .. } = &value.kind else {
        return;
    };
    let body = match body {
        LambdaBody::Expr(expr) => vec![Statement::new(StmtKind::Return(Some((**expr).clone())))],
        LambdaBody::Block(stmts) => stmts.clone(),
    };
    let kinds = python_lambda_param_kinds(params);
    note_defined_function(__w, name, params, None, &body, &kinds);
}

// ── Function def ────────────────────────────────────────────────────────────

fn walk_func_def(
    __w: &mut PyWalker,
    pair: Pair<Rule>,
    is_async: bool,
    decorators: Vec<Expression>,
) -> Result<StmtKind, String> {
    let mut name = String::new();
    let mut params = Vec::new();
    let mut param_kinds = Vec::new();
    let mut body = Vec::new();
    let mut return_type = None;

    for p in pair.into_inner() {
        match p.as_rule() {
            Rule::identifier => name = p.as_str().to_string(),
            Rule::param_list => {
                params = walk_params(__w, p)?;
                param_kinds = __w.py_last_param_kinds.clone();
            }
            Rule::block => {
                let shadows = params.iter().map(|param| param.name.clone()).collect();
                __w.py_string_const_shadows.push(shadows);
                let walked = walk_block(__w, p);
                __w.py_string_const_shadows.pop();
                body = walked?;
            }
            Rule::expression
            | Rule::named_expr
            | Rule::ternary_expr
            | Rule::or_expr
            | Rule::and_expr
            | Rule::not_expr
            | Rule::comparison
            | Rule::bitor_expr
            | Rule::bitxor_expr
            | Rule::bitand_expr
            | Rule::shift_expr
            | Rule::additive
            | Rule::multiplicative
            | Rule::unary
            | Rule::power
            | Rule::await_expr
            | Rule::postfix
            | Rule::primary => {
                // return type annotation — just note it as string
                return_type = Some(p.as_str().to_string());
            }
            _ => {}
        }
    }

    // Generator function: transform yield statements into eager collection.
    // def gen(): yield 1; yield 2 → def gen(): __gen_result = []; __gen_result.append(1); ...; return __gen_result
    // Generators: two lowering paths, chosen by the function's
    // decorator list.
    //   * Default — eager-list rewrite: yields append to a list that
    //     is returned at the end, so `for v in gen()` iterates the
    //     list via the standard for-in protocol. Backwards-compatible
    //     with the existing generator test suite.
    //   * `@generator` decorator — true lazy generator via the
    //     stack-switching proposal: the function compiles with
    //     `is_generator = true`, calls return a `Continuation`, and
    //     each `yield` compiles to a `SUSPEND` opcode. Consuming
    //     requires explicit `RESUME` (or a future iterator-protocol-
    //     aware for-in) — no automatic eager materialisation.
    // Any function containing `yield` is a true lazy generator — compiled
    // through the shared stack-switching machinery (`generators.rs`), exactly
    // like JavaScript. No eager list materialization (that hung on `while True`
    // generators and was semantically eager).
    let has_yield = body_has_yield(&body);
    normalize_currentframe_in_body(__w, &name, &mut body);
    let python_params = params.clone();
    note_defined_function(
        __w,
        &name,
        &python_params,
        return_type.clone(),
        &body,
        &param_kinds,
    );
    normalize_python_nonterminal_rest_params(&mut params, &param_kinds);
    if is_async {
        note_async_func(__w, &name);
    }
    if has_yield {
        note_generator_func(__w, &name);
        if is_async {
            note_async_generator_func(__w, &name);
        }
        if body_yields_python_float(__w, &body) {
            note_generator_func_float_yield(__w, &name);
        }
    }
    if let Some(factory) = body.iter().find_map(|stmt| {
        if let StmtKind::Return(Some(e)) = &stmt.kind {
            defaultdict_call_factory(__w, e)
        } else {
            None
        }
    }) {
        note_defaultdict_func(__w, &name, factory);
    }
    prepend_python_function_local_decls(&mut body, &params);
    prepend_python_rest_tuple_bindings(&mut body, &python_params);
    attach_nested_function_metadata(&name, &mut body);

    Ok(StmtKind::FunctionDecl {
        name,
        params,
        return_type,
        body,
        modifiers: Modifiers {
            decorators,
            ..Default::default()
        },
        handles: Vec::new(),
        is_async,
        is_generator: has_yield,
        is_sub: false,
    })
}

fn walk_params(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<Vec<Param>, String> {
    let mut params = Vec::new();
    let mut kinds: Vec<String> = Vec::new();
    let mut keyword_only = false;
    for p in pair.into_inner() {
        if p.as_rule() == Rule::param_item {
            let inner = p.into_inner().next();
            if let Some(item) = inner {
                match item.as_rule() {
                    Rule::normal_param => {
                        // Grammar: `identifier (":" expr)? ("=" expr)?`. pest
                        // drops the `:`/`=` tokens, so with a single expression
                        // we can't tell a type annotation (`x: int`) from a
                        // default (`x = 2`) by rule alone — disambiguate from
                        // the source text (does the part after the name start
                        // with `=`?). With two expressions it's `type = default`.
                        let param_text = item.as_str().trim_start().to_string();
                        let mut name = String::new();
                        let mut default = None;
                        let mut type_hint = None;
                        let mut exprs = Vec::new();
                        for c in item.into_inner() {
                            if c.as_rule() == Rule::identifier && name.is_empty() {
                                name = c.as_str().to_string();
                            } else {
                                exprs.push(c);
                            }
                        }
                        let after_name = param_text
                            .strip_prefix(name.as_str())
                            .unwrap_or("")
                            .trim_start();
                        match exprs.len() {
                            2 => {
                                type_hint = Some(exprs[0].as_str().to_string());
                                default = Some(walk_expression(__w, exprs.remove(1))?);
                            }
                            1 => {
                                if after_name.starts_with('=') {
                                    default = Some(walk_expression(__w, exprs.remove(0))?);
                                } else {
                                    type_hint = Some(exprs[0].as_str().to_string());
                                }
                            }
                            _ => {}
                        }
                        params.push(Param {
                            name,
                            // A parameter annotation — Descriptive, see the
                            // annotated-assignment site.
                            type_hint: type_hint.map(vybe_ast::TypeHint::descriptive),
                            is_optional: default.is_some(),
                            default,
                            pass_by: PassBy::Value,
                            is_rest: false,
                            is_kwargs: false,
                            is_nullable: false,
                        });
                        kinds.push(if keyword_only {
                            "KEYWORD_ONLY".to_string()
                        } else {
                            "POSITIONAL_OR_KEYWORD".to_string()
                        });
                    }
                    Rule::star_param => {
                        let mut name = String::new();
                        for c in item.into_inner() {
                            if c.as_rule() == Rule::identifier {
                                name = c.as_str().to_string();
                            }
                        }
                        params.push(Param {
                            name,
                            type_hint: None,
                            default: None,
                            pass_by: PassBy::Value,
                            is_rest: true,
                            is_kwargs: false,
                            is_optional: false,
                            is_nullable: false,
                        });
                        kinds.push("VAR_POSITIONAL".to_string());
                        keyword_only = true;
                    }
                    Rule::double_star_param => {
                        let mut name = String::new();
                        for c in item.into_inner() {
                            if c.as_rule() == Rule::identifier {
                                name = c.as_str().to_string();
                            }
                        }
                        params.push(Param {
                            name,
                            type_hint: None,
                            // An omitted `**kwargs` binds an empty dict — synthesise
                            // the default here (frontend), so the shared default
                            // machinery fills it and the compiler change stays in
                            // the named-arg reorder only.
                            default: Some(py_dict_expr(Vec::new())),
                            pass_by: PassBy::Value,
                            is_rest: false,
                            is_kwargs: true,
                            is_optional: false,
                            is_nullable: false,
                        });
                        kinds.push("VAR_KEYWORD".to_string());
                    }
                    Rule::bare_star => {
                        keyword_only = true;
                    }
                    Rule::slash_param => {
                        for kind in &mut kinds {
                            if kind == "POSITIONAL_OR_KEYWORD" {
                                *kind = "POSITIONAL_ONLY".to_string();
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
    }
    __w.py_last_param_kinds = kinds;
    Ok(params)
}

// ── Class def ───────────────────────────────────────────────────────────────

fn str_lit(text: &str) -> Expression {
    Expression::new(ExprKind::Lit(Literal::Str(text.into())))
}

/// `a + b` using Python's dynamic add, matching what the walker emits for a
/// source-level `+` (plain `BinOp::Add` coerces operands to f64).
fn py_add(a: Expression, b: Expression) -> Expression {
    call_ident("__pyadd__", vec![a, b])
}

fn py_counter_binary(
    __w: &mut PyWalker,
    op: BinOp,
    left: &Expression,
    right: &Expression,
) -> Option<Expression> {
    if !is_counter_expr(__w, left) || !is_counter_expr(__w, right) {
        return None;
    }
    let op_name = match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::BitAnd => "&",
        BinOp::BitOr => "|",
        _ => return None,
    };
    Some(call_ident(
        "__py_counter_op",
        vec![left.clone(), right.clone(), Expression::string(op_name)],
    ))
}

#[allow(dead_code)]
fn other_attr(field: &str) -> Expression {
    Expression::new(ExprKind::Member {
        object: Box::new(Expression::new(ExprKind::Ident("other".into()))),
        field: field.to_string(),
        null_safe: false,
    })
}

fn dataclass_self_field(field: &str) -> Expression {
    call_ident(
        "__py_obj_get__",
        vec![Expression::ident("self"), Expression::string(field)],
    )
}

fn dataclass_other_field(field: &str) -> Expression {
    call_ident(
        "__py_obj_get__",
        vec![Expression::ident("other"), Expression::string(field)],
    )
}

fn binop(op: BinOp, left: Expression, right: Expression) -> Expression {
    Expression::new(ExprKind::Binary {
        op,
        left: Box::new(left),
        right: Box::new(right),
    })
}

/// One annotated class-level declaration a `@dataclass` turns into a field.
///
/// `init_var` is PEP 557's `InitVar[T]`: a constructor parameter that is
/// handed to `__post_init__` and never stored on the instance, so it takes
/// part in `__init__`'s signature but in none of `__repr__`, `__eq__`,
/// `asdict` or `fields`.
#[derive(Clone)]
struct DataclassField {
    name: String,
    type_hint: Option<String>,
    default: Option<Expression>,
    default_factory: Option<Expression>,
    metadata: Option<Expression>,
    init_var: bool,
    init: bool,
    repr: bool,
    compare: bool,
    kw_only: bool,
}

#[derive(Clone, Copy, Default)]
struct DataclassOptions {
    frozen: bool,
    unsafe_hash: bool,
    order: bool,
    kw_only: bool,
    slots: bool,
}

/// `__repr__` as `@dataclass` generates it: `ClassName(field=repr, ...)`.
fn dataclass_repr(class_name: &str, fields: &[DataclassField]) -> Statement {
    let mut expr = str_lit(&format!("{class_name}("));
    for (i, field) in fields.iter().filter(|f| !f.init_var && f.repr).enumerate() {
        let name = &field.name;
        let sep = if i == 0 {
            format!("{name}=")
        } else {
            format!(", {name}=")
        };
        expr = py_add(expr, str_lit(&sep));
        let value = dataclass_self_field(name);
        let rendered = if field.type_hint.as_deref() == Some("float") {
            wrap_float_repr(value)
        } else {
            call_ident("repr", vec![value])
        };
        expr = py_add(expr, rendered);
    }
    expr = py_add(expr, str_lit(")"));
    fn_decl(
        "__repr__",
        vec![plain_param("self", None)],
        vec![Statement::new(StmtKind::Return(Some(expr)))],
    )
}

/// `__eq__` as `@dataclass` generates it: field-by-field, and only against
/// the same class — CPython returns `NotImplemented` for a foreign type,
/// which makes `==` fall back to identity and yield False.
///
/// The class test is CPython's own — `other.__class__ is self.__class__` —
/// rather than `type(other) == ClassName`. Comparing against the class GLOBAL
/// went through the rich-`==` path and answered False for two instances of the
/// same class, so every generated `__eq__` returned False.
fn dataclass_eq(fields: &[DataclassField]) -> Statement {
    let same_class = binop(
        BinOp::StrictEq,
        call_ident(
            "type",
            vec![Expression::new(ExprKind::Ident("other".into()))],
        ),
        call_ident(
            "type",
            vec![Expression::new(ExprKind::Ident("self".into()))],
        ),
    );
    let mut cond = same_class;
    for name in fields
        .iter()
        .filter(|f| !f.init_var && f.compare)
        .map(|f| &f.name)
    {
        cond = binop(
            BinOp::And,
            cond,
            binop(
                BinOp::Eq,
                dataclass_self_field(name),
                dataclass_other_field(name),
            ),
        );
    }
    fn_decl(
        "__eq__",
        vec![plain_param("self", None), plain_param("other", None)],
        vec![Statement::new(StmtKind::Return(Some(cond)))],
    )
}

fn dataclass_hash(class_name: &str, fields: &[DataclassField]) -> Statement {
    let mut key = Expression::string(class_name);
    for field in fields.iter().filter(|f| !f.init_var && f.compare) {
        key = py_add(key, Expression::string("|"));
        key = py_add(key, Expression::string(&field.name));
        key = py_add(key, Expression::string("="));
        key = py_add(
            key,
            call_ident("repr", vec![dataclass_self_field(&field.name)]),
        );
    }
    fn_decl(
        "__hash__",
        vec![plain_param("self", None)],
        vec![Statement::new(StmtKind::Return(Some(call_ident(
            "hash",
            vec![key],
        ))))],
    )
}

fn dataclass_lt(fields: &[DataclassField]) -> Statement {
    let mut body = Vec::new();
    for field in fields.iter().filter(|f| !f.init_var && f.compare) {
        let left = dataclass_self_field(&field.name);
        let right = dataclass_other_field(&field.name);
        body.push(Statement::new(StmtKind::If {
            cond: binop(BinOp::NotEq, left.clone(), right.clone()),
            then_body: vec![Statement::new(StmtKind::Return(Some(binop(
                BinOp::Lt,
                left,
                right,
            ))))],
            elifs: Vec::new(),
            else_body: None,
        }));
    }
    body.push(Statement::new(StmtKind::Return(Some(Expression::new(
        ExprKind::Lit(Literal::Bool(false)),
    )))));
    fn_decl(
        "__lt__",
        vec![plain_param("self", None), plain_param("other", None)],
        body,
    )
}

fn dataclass_store_value(field: &DataclassField, value: Expression) -> Expression {
    if field.type_hint.as_deref() == Some("float") {
        call_ident("float", vec![value])
    } else {
        value
    }
}

fn property_accessor_decorator(expr: &Expression) -> Option<(String, &'static str)> {
    match &expr.kind {
        ExprKind::Member { object, field, .. }
            if matches!(field.as_str(), "setter" | "getter" | "deleter") =>
        {
            let prop_name = match &object.kind {
                ExprKind::Ident(prop_name) => prop_name.clone(),
                ExprKind::Member { field, .. } => field.clone(),
                ExprKind::Call { .. } => property_target_name(object)?,
                _ => return None,
            };
            let kind = match field.as_str() {
                "setter" => "setter",
                "getter" => "getter",
                "deleter" => "deleter",
                _ => return None,
            };
            Some((prop_name, kind))
        }
        ExprKind::Call { callee, args, .. } => {
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_attr_read")
                && args.len() == 2
                && let ExprKind::Lit(Literal::Str(kind)) = &args[1].value.kind
                && matches!(kind.as_str(), "setter" | "getter" | "deleter")
            {
                let prop_name = property_target_name(&args[0].value)?;
                let kind = match kind.as_str() {
                    "setter" => "setter",
                    "getter" => "getter",
                    "deleter" => "deleter",
                    _ => return None,
                };
                return Some((prop_name, kind));
            }
            property_accessor_decorator(callee)
        }
        _ => None,
    }
}

fn property_target_name(expr: &Expression) -> Option<String> {
    match &expr.kind {
        ExprKind::Ident(name) => Some(name.clone()),
        ExprKind::Member { field, .. } => Some(field.clone()),
        ExprKind::Call { callee, args, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_attr_read")
                && args.len() == 2 =>
        {
            match &args[1].value.kind {
                ExprKind::Lit(Literal::Str(field)) => Some(field.clone()),
                _ => property_target_name(&args[0].value),
            }
        }
        ExprKind::Call { callee, .. } => property_target_name(callee),
        _ => None,
    }
}

fn property_getter_returns_float(__w: &mut PyWalker, class_name: &str, body: &[Statement]) -> bool {
    body.iter().any(|stmt| match &stmt.kind {
        StmtKind::Return(Some(expr)) => match &expr.kind {
            ExprKind::Member { object, field, .. }
                if matches!(&object.kind, ExprKind::Ident(name) if name == "self") =>
            {
                class_has_float_data_attr(__w, class_name, field)
            }
            ExprKind::Index { object, index, .. }
                if matches!(&object.kind, ExprKind::Ident(name) if name == "self") =>
            {
                matches!(&index.kind, ExprKind::Lit(Literal::Str(field)) if class_has_float_data_attr(__w, class_name, field))
            }
            ExprKind::Call { callee, args, .. }
                if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_obj_get__")
                    && args.len() == 2
                    && matches!(&args[0].value.kind, ExprKind::Ident(name) if name == "self") =>
            {
                matches!(&args[1].value.kind, ExprKind::Lit(Literal::Str(field)) if class_has_float_data_attr(__w, class_name, field))
            }
            _ => expr_is_python_float(__w, expr),
        },
        StmtKind::Block(stmts) => property_getter_returns_float(__w, class_name, stmts),
        StmtKind::If {
            then_body,
            elifs,
            else_body,
            ..
        } => {
            property_getter_returns_float(__w, class_name, then_body)
                || elifs
                    .iter()
                    .any(|(_, body)| property_getter_returns_float(__w, class_name, body))
                || else_body
                    .as_deref()
                    .is_some_and(|body| property_getter_returns_float(__w, class_name, body))
        }
        _ => false,
    })
}

/// `@dataclass` or `@dataclass(...)` (the parametrised form).
fn is_dataclass_decorator(d: &Expression) -> bool {
    match &d.kind {
        ExprKind::Ident(n) => n == "dataclass",
        ExprKind::Call { callee, .. } => {
            matches!(&callee.kind, ExprKind::Ident(n) if n == "dataclass")
        }
        ExprKind::Member { field, .. } => field == "dataclass",
        _ => false,
    }
}

fn dataclass_bool_arg(args: &[Argument], name: &str) -> bool {
    args.iter().any(|arg| {
        arg.name.as_deref() == Some(name)
            && matches!(&arg.value.kind, ExprKind::Lit(Literal::Bool(true)))
    })
}

fn dataclass_options(decorators: &[Expression]) -> DataclassOptions {
    let mut opts = DataclassOptions::default();
    for d in decorators {
        let ExprKind::Call { callee, args, .. } = &d.kind else {
            continue;
        };
        let is_dataclass = match &callee.kind {
            ExprKind::Ident(n) => n == "dataclass",
            ExprKind::Member { field, .. } => field == "dataclass",
            _ => false,
        };
        if !is_dataclass {
            continue;
        }
        opts.frozen = dataclass_bool_arg(args, "frozen");
        opts.unsafe_hash = dataclass_bool_arg(args, "unsafe_hash");
        opts.order = dataclass_bool_arg(args, "order");
        opts.kw_only = dataclass_bool_arg(args, "kw_only");
        opts.slots = dataclass_bool_arg(args, "slots");
    }
    opts
}

/// The annotated class-level declarations, in source order — exactly what
/// CPython's `@dataclass` treats as fields. A bare `x = 5` with no annotation
/// is NOT a field, which is why the type hint (threaded through
/// `VarDeclarator.type_hint`) is the marker.
fn dataclass_fields(body: &[Statement]) -> Vec<DataclassField> {
    let mut fields = Vec::new();
    let mut kw_only_after = false;
    for stmt in body {
        let StmtKind::VarDecl { declarations, .. } = &stmt.kind else {
            continue;
        };
        for d in declarations {
            let Some(hint) = &d.type_hint else {
                continue;
            };
            if let BindingPattern::Ident(name) = &d.pattern {
                if hint.starts_with("ClassVar") || hint.starts_with("typing.ClassVar") {
                    continue;
                }
                if name == "_" && (**hint == *"KW_ONLY" || **hint == *"dataclasses.KW_ONLY") {
                    kw_only_after = true;
                    continue;
                }
                let (default, default_factory, metadata, init, repr, compare) =
                    dataclass_field_config(d.init.as_ref());
                fields.push(DataclassField {
                    name: name.clone(),
                    type_hint: Some(hint.to_string()),
                    default,
                    default_factory,
                    metadata,
                    // `InitVar[int]`, or the bare `InitVar` — the hint is a
                    // string, so match the head rather than parsing it.
                    init_var: **hint == *"InitVar"
                        || **hint == *"dataclasses.InitVar"
                        || hint.starts_with("InitVar[")
                        || hint.starts_with("dataclasses.InitVar["),
                    init,
                    repr,
                    compare,
                    kw_only: kw_only_after,
                });
            }
        }
    }
    fields
}

fn dataclass_has_mutable_literal_default(body: &[Statement]) -> bool {
    dataclass_fields(body).iter().any(|field| {
        field.default.as_ref().is_some_and(|default| {
            matches!(
                default.kind,
                ExprKind::Array(_) | ExprKind::Map(_) | ExprKind::Set(_) | ExprKind::Object(_)
            )
        })
    })
}

fn dataclass_field_config(
    init: Option<&Expression>,
) -> (
    Option<Expression>,
    Option<Expression>,
    Option<Expression>,
    bool,
    bool,
    bool,
) {
    let Some(init) = init else {
        return (None, None, None, true, true, true);
    };
    if !is_dataclass_field_call(init) {
        return (Some(init.clone()), None, None, true, true, true);
    }
    let ExprKind::Call { callee, args, .. } = &init.kind else {
        return (Some(init.clone()), None, None, true, true, true);
    };
    let is_field_call = match &callee.kind {
        ExprKind::Ident(n) => n == "field",
        ExprKind::Member { field, .. } => field == "field",
        _ => false,
    };
    if !is_field_call {
        return (Some(init.clone()), None, None, true, true, true);
    }
    let mut default = None;
    let mut default_factory = None;
    let mut metadata = None;
    let mut init_field = true;
    let mut repr_field = true;
    let mut compare_field = true;
    for arg in args {
        match arg.name.as_deref() {
            Some("default") => default = Some(arg.value.clone()),
            Some("default_factory") => default_factory = Some(arg.value.clone()),
            Some("metadata") => metadata = Some(arg.value.clone()),
            Some("init") if matches!(&arg.value.kind, ExprKind::Lit(Literal::Bool(false))) => {
                init_field = false
            }
            Some("repr") if matches!(&arg.value.kind, ExprKind::Lit(Literal::Bool(false))) => {
                repr_field = false
            }
            Some("compare") if matches!(&arg.value.kind, ExprKind::Lit(Literal::Bool(false))) => {
                compare_field = false
            }
            _ => {}
        }
    }
    (
        default,
        default_factory,
        metadata,
        init_field,
        repr_field,
        compare_field,
    )
}

fn is_dataclass_field_call(init: &Expression) -> bool {
    let ExprKind::Call { callee, .. } = &init.kind else {
        return false;
    };
    match &callee.kind {
        ExprKind::Ident(n) => n == "field",
        ExprKind::Member { field, .. } => field == "field",
        _ => false,
    }
}

fn self_attr(field: &str) -> Expression {
    Expression::new(ExprKind::Member {
        object: Box::new(Expression::new(ExprKind::Ident("self".into()))),
        field: field.to_string(),
        null_safe: false,
    })
}

fn plain_param(name: &str, default: Option<Expression>) -> Param {
    Param {
        name: name.to_string(),
        type_hint: None,
        default,
        pass_by: PassBy::Value,
        is_rest: false,
        is_kwargs: false,
        is_optional: false,
        is_nullable: false,
    }
}

fn dataclass_param(field: &DataclassField, default: Option<Expression>) -> Param {
    let mut param = plain_param(&field.name, default);
    // A dataclass field's annotation, so DESCRIPTIVE like every other python
    // hint — see the annotated-assignment site.
    param.type_hint = field.type_hint.clone().map(vybe_ast::TypeHint::descriptive);
    param
}

fn dataclass_default_factory_call(factory: &Expression) -> Expression {
    if let ExprKind::Ident(name) = &factory.kind {
        if matches!(name.as_str(), "list" | "dict" | "set" | "int") {
            return Expression::new(ExprKind::Call {
                callee: Box::new(Expression::ident(name)),
                args: Vec::new(),
                optional: false,
            });
        }
    }
    call_ident("__py_default_factory_value", vec![factory.clone()])
}

fn merge_dataclass_fields(
    base: &mut Vec<DataclassField>,
    incoming: impl IntoIterator<Item = DataclassField>,
) {
    for field in incoming {
        if let Some(existing) = base.iter_mut().find(|f| f.name == field.name) {
            *existing = field;
        } else {
            base.push(field);
        }
    }
}

fn inherited_dataclass_fields(__w: &mut PyWalker, class_name: &str) -> Vec<DataclassField> {
    let parents = __w
        .py_class_parents
        .get(class_name)
        .cloned()
        .unwrap_or_default();
    let mut fields = Vec::new();
    for parent in parents {
        if let Some(parent_fields) = dataclass_fields_for(__w, &parent) {
            merge_dataclass_fields(&mut fields, parent_fields);
        }
    }
    fields
}

fn dataclass_fields_descriptors_expr(__w: &mut PyWalker, class_name: &str) -> Option<Expression> {
    let fields = dataclass_fields_for(__w, class_name)?;
    Some(Expression::new(ExprKind::Array(
        fields
            .into_iter()
            .filter(|f| !f.init_var)
            .map(|field| {
                let ty = field
                    .type_hint
                    .as_deref()
                    .map(py_annotation_expr)
                    .unwrap_or_else(|| Expression::new(ExprKind::Lit(Literal::Null)));
                let mut default = field
                    .default
                    .clone()
                    .unwrap_or_else(|| Expression::string("MISSING"));
                if field.type_hint.as_deref() == Some("float")
                    && let ExprKind::Lit(Literal::Float(v)) = &default.kind
                    && v.fract() == 0.0
                {
                    default = Expression::string(&format!("{v:.1}"));
                }
                ArrayElement {
                    key: None,
                    spread: false,
                    by_ref: false,
                    value: Expression::new(ExprKind::Object(vec![
                        ObjectProperty::KeyValue {
                            key: Expression::string("name"),
                            value: Expression::string(&field.name),
                        },
                        ObjectProperty::KeyValue {
                            key: Expression::string("type"),
                            value: ty,
                        },
                        ObjectProperty::KeyValue {
                            key: Expression::string("default"),
                            value: default,
                        },
                        ObjectProperty::KeyValue {
                            key: Expression::string("metadata"),
                            value: field
                                .metadata
                                .clone()
                                .unwrap_or_else(|| Expression::new(ExprKind::Map(Vec::new()))),
                        },
                    ])),
                }
            })
            .collect(),
    )))
}

fn dataclass_replace_expr(__w: &mut PyWalker, args: &[Argument]) -> Option<Expression> {
    let source = args.first()?.value.clone();
    let class_name = match &source.kind {
        ExprKind::Ident(var) => instance_class(__w, var)?,
        ExprKind::New { class, .. } => match &class.kind {
            ExprKind::Ident(name) => name.clone(),
            _ => return None,
        },
        _ => return None,
    };
    let fields = dataclass_fields_for(__w, &class_name)?;
    let mut ctor_args = Vec::new();
    for field in fields.iter().filter(|f| !f.init_var && f.init) {
        let value = args
            .iter()
            .skip(1)
            .find(|arg| arg.name.as_deref() == Some(field.name.as_str()))
            .map(|arg| desugar_member_reads(__w, arg.value.clone()))
            .unwrap_or_else(|| {
                call_ident(
                    "__py_attr_read",
                    vec![source.clone(), Expression::string(&field.name)],
                )
            });
        ctor_args.push(Argument::positional(value));
    }
    Some(Expression::new(ExprKind::New {
        class: Box::new(Expression::ident(&class_name)),
        args: ctor_args,
    }))
}

fn dataclass_hash_key_expr(__w: &mut PyWalker, value: Expression) -> Option<Expression> {
    let class_name = match &value.kind {
        ExprKind::Ident(var) => instance_class(__w, var)?,
        ExprKind::New { class, .. } => match &class.kind {
            ExprKind::Ident(name) => name.clone(),
            _ => return None,
        },
        _ => return None,
    };
    let options = dataclass_options_for(__w, &class_name).unwrap_or_default();
    if !options.frozen && !options.unsafe_hash {
        return None;
    }
    let fields = dataclass_fields_for(__w, &class_name)?;
    let mut key = Expression::string(&class_name);
    for field in fields.iter().filter(|f| !f.init_var && f.compare) {
        key = py_add(key, Expression::string("|"));
        key = py_add(key, Expression::string(&field.name));
        key = py_add(key, Expression::string("="));
        key = py_add(
            key,
            call_ident(
                "repr",
                vec![call_ident(
                    "__py_attr_read",
                    vec![value.clone(), Expression::string(&field.name)],
                )],
            ),
        );
    }
    Some(key)
}

fn dataclass_fields_keys_expr(__w: &mut PyWalker, object: &Expression) -> Option<Expression> {
    let class_name = match &object.kind {
        ExprKind::Ident(name) if is_defined_class(__w, name) => name.clone(),
        ExprKind::Ident(var) => instance_class(__w, var)?,
        ExprKind::New { class, .. } => match &class.kind {
            ExprKind::Ident(name) => name.clone(),
            _ => return None,
        },
        _ => return None,
    };
    let fields = dataclass_fields_for(__w, &class_name)?;
    let props = fields
        .into_iter()
        .filter(|f| !f.init_var)
        .map(|field| ObjectProperty::KeyValue {
            key: Expression::string(&field.name),
            value: Expression::null(),
        })
        .collect();
    Some(Expression::new(ExprKind::Call {
        callee: Box::new(Expression::new(ExprKind::Member {
            object: Box::new(py_dict_expr(props)),
            field: "keys".into(),
            null_safe: false,
        })),
        args: Vec::new(),
        optional: false,
    }))
}

fn make_dataclass_stmt(
    __w: &mut PyWalker,
    target_name: &str,
    value: &Expression,
) -> Option<StmtKind> {
    let ExprKind::Call { callee, args, .. } = &value.kind else {
        return None;
    };
    let is_make = match &callee.kind {
        ExprKind::Ident(name) => name == "make_dataclass",
        ExprKind::Member { object, field, .. } => {
            field == "make_dataclass"
                && matches!(&object.kind, ExprKind::Ident(module) if module == "dataclasses")
        }
        _ => false,
    };
    if !is_make || args.len() < 2 {
        return None;
    }
    let ExprKind::Lit(Literal::Str(class_literal)) = &args[0].value.kind else {
        return None;
    };
    let class_name = if target_name.is_empty() {
        class_literal.to_string()
    } else {
        target_name.to_string()
    };
    let ExprKind::Array(field_entries) = &args[1].value.kind else {
        return None;
    };

    let mut body = Vec::new();
    for entry in field_entries {
        let ExprKind::Tuple(items) = &entry.value.kind else {
            continue;
        };
        let Some(ExprKind::Lit(Literal::Str(field_name))) = items.first().map(|e| &e.kind) else {
            continue;
        };
        let type_hint = items.get(1).and_then(|expr| match &expr.kind {
            ExprKind::Ident(name) => Some(name.clone()),
            _ => None,
        });
        let init = items.get(2).cloned();
        body.push(Statement::new(StmtKind::VarDecl {
            declarations: vec![vybe_ast::VarDeclarator {
                pattern: BindingPattern::Ident(field_name.to_string()),
                // Same annotation, Descriptive — see the annotated-assignment
                // site.
                type_hint: type_hint.map(vybe_ast::TypeHint::descriptive),
                init,
                array_bounds: None,
                with_events: false,
            }],
            kind: VarDeclKind::Let,
        }));
    }

    let mut parents = Vec::new();
    for arg in args {
        if arg.name.as_deref() == Some("bases") {
            if let ExprKind::Tuple(items) = &arg.value.kind {
                parents.extend(items.iter().filter_map(|expr| match &expr.kind {
                    ExprKind::Ident(name) => Some(name.clone()),
                    _ => None,
                }));
            }
        }
    }

    note_defined_class(__w, &class_name);
    note_class_parents(__w, &class_name, &parents);
    let data_attrs: std::collections::HashSet<String> = dataclass_fields(&body)
        .into_iter()
        .filter(|f| !f.init_var)
        .map(|f| f.name)
        .collect();
    note_class_attrs(__w, &class_name, data_attrs.clone());
    note_class_data_attrs(__w, &class_name, data_attrs);
    synthesize_dataclass_members(__w, &class_name, &mut body, DataclassOptions::default());
    let members = stmts_to_class_members(__w, &class_name, body);
    Some(StmtKind::ClassDecl {
        name: class_name,
        parents,
        interfaces: Vec::new(),
        members,
        modifiers: ClassModifiers {
            semantics: ValueSemantics {
                equality: ValueEquality::Structural,
                ..Default::default()
            },
            ..Default::default()
        },
        decorators: Vec::new(),
    })
}

fn has_method(body: &[Statement], want: &str) -> bool {
    body.iter()
        .any(|s| matches!(&s.kind, StmtKind::FunctionDecl { name, .. } if name == want))
}

fn fn_decl(name: &str, params: Vec<Param>, body: Vec<Statement>) -> Statement {
    Statement::new(StmtKind::FunctionDecl {
        name: name.to_string(),
        params,
        return_type: None,
        body,
        modifiers: Modifiers::default(),
        handles: Vec::new(),
        is_async: false,
        is_generator: false,
        is_sub: false,
    })
}

fn is_python_private_name(name: &str) -> bool {
    name.starts_with("__") && !name.ends_with("__")
}

fn python_mangle_private_name(class_name: &str, name: &str) -> String {
    if is_python_private_name(name) {
        format!("_{}{}", class_name.trim_start_matches('_'), name)
    } else {
        name.to_string()
    }
}

fn mangle_private_members_in_expr(class_name: &str, expr: &mut Expression) {
    match &mut expr.kind {
        ExprKind::Member { object, field, .. } => {
            mangle_private_members_in_expr(class_name, object);
            *field = python_mangle_private_name(class_name, field);
        }
        ExprKind::Call { callee, args, .. } => {
            mangle_private_members_in_expr(class_name, callee);
            for arg in args {
                mangle_private_members_in_expr(class_name, &mut arg.value);
            }
        }
        ExprKind::Binary { left, right, .. } => {
            mangle_private_members_in_expr(class_name, left);
            mangle_private_members_in_expr(class_name, right);
        }
        ExprKind::Unary { expr, .. } => mangle_private_members_in_expr(class_name, expr),
        ExprKind::Ternary { cond, then, else_ } => {
            mangle_private_members_in_expr(class_name, cond);
            mangle_private_members_in_expr(class_name, then);
            mangle_private_members_in_expr(class_name, else_);
        }
        ExprKind::Index { object, index, .. } => {
            mangle_private_members_in_expr(class_name, object);
            mangle_private_members_in_expr(class_name, index);
        }
        ExprKind::Array(items) => {
            for item in items {
                if let Some(key) = &mut item.key {
                    mangle_private_members_in_expr(class_name, key);
                }
                mangle_private_members_in_expr(class_name, &mut item.value);
            }
        }
        ExprKind::Tuple(items) => {
            for item in items {
                mangle_private_members_in_expr(class_name, item);
            }
        }
        ExprKind::Object(props) => {
            for prop in props {
                match prop {
                    ObjectProperty::KeyValue { key, value }
                    | ObjectProperty::Computed { key, value } => {
                        mangle_private_members_in_expr(class_name, key);
                        mangle_private_members_in_expr(class_name, value);
                    }
                    ObjectProperty::Spread(value) => {
                        mangle_private_members_in_expr(class_name, value)
                    }
                    _ => {}
                }
            }
        }
        ExprKind::Lambda { body, .. } => match body {
            LambdaBody::Expr(expr) => mangle_private_members_in_expr(class_name, expr),
            LambdaBody::Block(stmts) => mangle_private_members_in_stmts(class_name, stmts),
        },
        _ => {}
    }
}

fn mangle_private_members_in_stmts(class_name: &str, stmts: &mut [Statement]) {
    for stmt in stmts {
        match &mut stmt.kind {
            StmtKind::FunctionDecl { body, .. } | StmtKind::Block(body) => {
                mangle_private_members_in_stmts(class_name, body);
            }
            StmtKind::If {
                cond,
                then_body,
                elifs,
                else_body,
            } => {
                mangle_private_members_in_expr(class_name, cond);
                mangle_private_members_in_stmts(class_name, then_body);
                for (elif_cond, elif_body) in elifs {
                    mangle_private_members_in_expr(class_name, elif_cond);
                    mangle_private_members_in_stmts(class_name, elif_body);
                }
                if let Some(body) = else_body {
                    mangle_private_members_in_stmts(class_name, body);
                }
            }
            StmtKind::While { cond, body, .. } => {
                mangle_private_members_in_expr(class_name, cond);
                mangle_private_members_in_stmts(class_name, body);
            }
            StmtKind::ForIn {
                iter,
                body,
                else_body,
                ..
            } => {
                mangle_private_members_in_expr(class_name, iter);
                mangle_private_members_in_stmts(class_name, body);
                if let Some(body) = else_body {
                    mangle_private_members_in_stmts(class_name, body);
                }
            }
            StmtKind::Return(Some(expr)) | StmtKind::Expr(expr) => {
                mangle_private_members_in_expr(class_name, expr);
            }
            StmtKind::Assign { targets, value, .. } => {
                for target in targets {
                    mangle_private_members_in_expr(class_name, target);
                }
                mangle_private_members_in_expr(class_name, value);
            }
            StmtKind::VarDecl { declarations, .. } => {
                for decl in declarations {
                    if let Some(init) = &mut decl.init {
                        mangle_private_members_in_expr(class_name, init);
                    }
                }
            }
            _ => {}
        }
    }
}

fn replace_ident_in_expr(expr: &mut Expression, from: &str, to: &str) {
    match &mut expr.kind {
        ExprKind::Ident(name) if name == from => {
            *name = to.to_string();
        }
        ExprKind::Member { object, .. } => replace_ident_in_expr(object, from, to),
        ExprKind::Call { callee, args, .. } => {
            replace_ident_in_expr(callee, from, to);
            for arg in args {
                replace_ident_in_expr(&mut arg.value, from, to);
            }
        }
        ExprKind::Binary { left, right, .. } => {
            replace_ident_in_expr(left, from, to);
            replace_ident_in_expr(right, from, to);
        }
        ExprKind::Unary { expr, .. } => replace_ident_in_expr(expr, from, to),
        ExprKind::Ternary { cond, then, else_ } => {
            replace_ident_in_expr(cond, from, to);
            replace_ident_in_expr(then, from, to);
            replace_ident_in_expr(else_, from, to);
        }
        ExprKind::Index { object, index, .. } => {
            replace_ident_in_expr(object, from, to);
            replace_ident_in_expr(index, from, to);
        }
        ExprKind::New { class, args } => {
            replace_ident_in_expr(class, from, to);
            for arg in args {
                replace_ident_in_expr(&mut arg.value, from, to);
            }
        }
        ExprKind::Assign { target, value } => {
            replace_ident_in_expr(target, from, to);
            replace_ident_in_expr(value, from, to);
        }
        ExprKind::Array(items) => {
            for item in items {
                if let Some(key) = &mut item.key {
                    replace_ident_in_expr(key, from, to);
                }
                replace_ident_in_expr(&mut item.value, from, to);
            }
        }
        ExprKind::Tuple(items) => {
            for item in items {
                replace_ident_in_expr(item, from, to);
            }
        }
        ExprKind::NamedTuple { fields, .. } => {
            for (_, value) in fields {
                replace_ident_in_expr(value, from, to);
            }
        }
        ExprKind::Object(props) => {
            for prop in props {
                match prop {
                    ObjectProperty::KeyValue { key, value }
                    | ObjectProperty::Computed { key, value } => {
                        replace_ident_in_expr(key, from, to);
                        replace_ident_in_expr(value, from, to);
                    }
                    ObjectProperty::Spread(value) => replace_ident_in_expr(value, from, to),
                    _ => {}
                }
            }
        }
        ExprKind::Lambda { body, .. } => match body {
            LambdaBody::Expr(expr) => replace_ident_in_expr(expr, from, to),
            LambdaBody::Block(stmts) => replace_ident_in_stmts(stmts, from, to),
        },
        _ => {}
    }
}

fn replace_ident_in_stmts(stmts: &mut [Statement], from: &str, to: &str) {
    for stmt in stmts {
        match &mut stmt.kind {
            StmtKind::Expr(expr) => replace_ident_in_expr(expr, from, to),
            StmtKind::Return(Some(expr)) => replace_ident_in_expr(expr, from, to),
            StmtKind::Throw {
                expr: Some(expr),
                cause,
            } => {
                replace_ident_in_expr(expr, from, to);
                if let Some(cause) = cause {
                    replace_ident_in_expr(cause, from, to);
                }
            }
            StmtKind::VarDecl { declarations, .. } => {
                for declaration in declarations {
                    if let Some(init) = &mut declaration.init {
                        replace_ident_in_expr(init, from, to);
                    }
                }
            }
            StmtKind::Assign { targets, value, .. } => {
                for target in targets {
                    replace_ident_in_expr(target, from, to);
                }
                replace_ident_in_expr(value, from, to);
            }
            StmtKind::If {
                cond,
                then_body,
                elifs,
                else_body,
            } => {
                replace_ident_in_expr(cond, from, to);
                replace_ident_in_stmts(then_body, from, to);
                for (elif_cond, elif_body) in elifs {
                    replace_ident_in_expr(elif_cond, from, to);
                    replace_ident_in_stmts(elif_body, from, to);
                }
                if let Some(body) = else_body {
                    replace_ident_in_stmts(body, from, to);
                }
            }
            StmtKind::While { cond, body, .. } => {
                replace_ident_in_expr(cond, from, to);
                replace_ident_in_stmts(body, from, to);
            }
            StmtKind::For {
                init,
                cond,
                update,
                body,
            } => {
                if let Some(init) = init {
                    replace_ident_in_stmts(std::slice::from_mut(init.as_mut()), from, to);
                }
                if let Some(cond) = cond {
                    replace_ident_in_expr(cond, from, to);
                }
                if let Some(update) = update {
                    replace_ident_in_expr(update, from, to);
                }
                replace_ident_in_stmts(body, from, to);
            }
            StmtKind::ForIn {
                iter,
                body,
                else_body,
                ..
            } => {
                replace_ident_in_expr(iter, from, to);
                replace_ident_in_stmts(body, from, to);
                if let Some(body) = else_body {
                    replace_ident_in_stmts(body, from, to);
                }
            }
            StmtKind::Block(body) => replace_ident_in_stmts(body, from, to),
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                replace_ident_in_stmts(body, from, to);
                for catch in catches {
                    replace_ident_in_stmts(&mut catch.body, from, to);
                }
                if let Some(body) = else_body {
                    replace_ident_in_stmts(body, from, to);
                }
                if let Some(body) = finally {
                    replace_ident_in_stmts(body, from, to);
                }
            }
            StmtKind::FunctionDecl { .. } | StmtKind::ClassDecl { .. } => {}
            _ => {}
        }
    }
}

fn rewrite_self_data_attrs_in_expr(
    data_attrs: &std::collections::HashSet<String>,
    expr: &mut Expression,
) {
    if let ExprKind::Call { callee, args, .. } = &expr.kind
        && matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_getitem")
        && args.len() == 2
        && matches!(&args[0].value.kind, ExprKind::Ident(name) if name == "self")
        && let ExprKind::Lit(Literal::Str(field)) = &args[1].value.kind
        && data_attrs.contains(field.as_str())
    {
        *expr = call_ident(
            "__py_obj_get__",
            vec![
                Expression::ident("self"),
                Expression::string(field.as_str()),
            ],
        );
        return;
    }
    if let ExprKind::Member { object, field, .. } = &expr.kind
        && matches!(&object.kind, ExprKind::Ident(name) if name == "self")
        && data_attrs.contains(field)
    {
        *expr = call_ident(
            "__py_obj_get__",
            vec![Expression::ident("self"), Expression::string(field)],
        );
        return;
    }
    if let ExprKind::Index { object, index, .. } = &expr.kind
        && matches!(&object.kind, ExprKind::Ident(name) if name == "self")
        && let ExprKind::Lit(Literal::Str(field)) = &index.kind
        && data_attrs.contains(field.as_str())
    {
        *expr = call_ident(
            "__py_obj_get__",
            vec![
                Expression::ident("self"),
                Expression::string(field.as_str()),
            ],
        );
        return;
    }
    match &mut expr.kind {
        ExprKind::Call { callee, args, .. } => {
            rewrite_self_data_attrs_in_expr(data_attrs, callee);
            for arg in args {
                rewrite_self_data_attrs_in_expr(data_attrs, &mut arg.value);
            }
        }
        ExprKind::Member { object, .. } => rewrite_self_data_attrs_in_expr(data_attrs, object),
        ExprKind::Index { object, index, .. } => {
            rewrite_self_data_attrs_in_expr(data_attrs, object);
            rewrite_self_data_attrs_in_expr(data_attrs, index);
        }
        ExprKind::Unary { expr, .. } => rewrite_self_data_attrs_in_expr(data_attrs, expr),
        ExprKind::Binary { left, right, .. } => {
            rewrite_self_data_attrs_in_expr(data_attrs, left);
            rewrite_self_data_attrs_in_expr(data_attrs, right);
        }
        ExprKind::Ternary { cond, then, else_ } => {
            rewrite_self_data_attrs_in_expr(data_attrs, cond);
            rewrite_self_data_attrs_in_expr(data_attrs, then);
            rewrite_self_data_attrs_in_expr(data_attrs, else_);
        }
        ExprKind::Array(elements) => {
            for element in elements {
                rewrite_self_data_attrs_in_expr(data_attrs, &mut element.value);
                if let Some(key) = &mut element.key {
                    rewrite_self_data_attrs_in_expr(data_attrs, key);
                }
            }
        }
        ExprKind::Tuple(items) | ExprKind::Sequence(items) => {
            for item in items {
                rewrite_self_data_attrs_in_expr(data_attrs, item);
            }
        }
        ExprKind::Object(props) => {
            for prop in props {
                match prop {
                    ObjectProperty::KeyValue { key, value }
                    | ObjectProperty::Computed { key, value } => {
                        rewrite_self_data_attrs_in_expr(data_attrs, key);
                        rewrite_self_data_attrs_in_expr(data_attrs, value);
                    }
                    ObjectProperty::Spread(value) => {
                        rewrite_self_data_attrs_in_expr(data_attrs, value)
                    }
                    _ => {}
                }
            }
        }
        ExprKind::Comprehension {
            element,
            generators,
            ..
        } => {
            rewrite_self_data_attrs_in_expr(data_attrs, element);
            for generator in generators {
                rewrite_self_data_attrs_in_expr(data_attrs, &mut generator.iter);
                for condition in &mut generator.conditions {
                    rewrite_self_data_attrs_in_expr(data_attrs, condition);
                }
            }
        }
        ExprKind::Lambda { body, .. } => match body {
            LambdaBody::Expr(expr) => rewrite_self_data_attrs_in_expr(data_attrs, expr),
            LambdaBody::Block(stmts) => rewrite_self_data_attrs_in_stmts(data_attrs, stmts),
        },
        ExprKind::Interpolation(parts) => {
            for part in parts {
                if let InterpolPart::Expr(expr) = part {
                    rewrite_self_data_attrs_in_expr(data_attrs, expr);
                }
            }
        }
        _ => {}
    }
}

fn rewrite_self_data_attrs_in_target(
    data_attrs: &std::collections::HashSet<String>,
    expr: &mut Expression,
) {
    match &mut expr.kind {
        ExprKind::Member { object, field, .. } if matches!(&object.kind, ExprKind::Ident(name) if name == "self") =>
        {
            *expr = Expression::new(ExprKind::Index {
                object: Box::new(Expression::ident("self")),
                index: Box::new(Expression::string(field)),
                null_safe: false,
            });
        }
        ExprKind::Index { object, index, .. } => {
            if let ExprKind::Member {
                object: member_object,
                field,
                ..
            } = &object.kind
                && matches!(&member_object.kind, ExprKind::Ident(name) if name == "self")
                && data_attrs.contains(field)
            {
                *object = Box::new(call_ident(
                    "__py_obj_get__",
                    vec![Expression::ident("self"), Expression::string(field)],
                ));
            } else if let ExprKind::Index {
                object: inner_object,
                index: inner_index,
                ..
            } = &object.kind
                && matches!(&inner_object.kind, ExprKind::Ident(name) if name == "self")
                && let ExprKind::Lit(Literal::Str(field)) = &inner_index.kind
                && data_attrs.contains(field.as_str())
            {
                *object = Box::new(call_ident(
                    "__py_obj_get__",
                    vec![
                        Expression::ident("self"),
                        Expression::string(field.as_str()),
                    ],
                ));
            } else {
                rewrite_self_data_attrs_in_target(data_attrs, object);
            }
            rewrite_self_data_attrs_in_expr(data_attrs, index);
        }
        ExprKind::Tuple(items) | ExprKind::Sequence(items) => {
            for item in items {
                rewrite_self_data_attrs_in_target(data_attrs, item);
            }
        }
        _ => {}
    }
}

fn collect_self_data_attrs_in_stmts(
    stmts: &[Statement],
    out: &mut std::collections::HashSet<String>,
) {
    for stmt in stmts {
        match &stmt.kind {
            StmtKind::Assign { targets, .. } => {
                for target in targets {
                    if let ExprKind::Member { object, field, .. } = &target.kind
                        && matches!(&object.kind, ExprKind::Ident(name) if name == "self")
                    {
                        out.insert(field.clone());
                    }
                }
            }
            StmtKind::FunctionDecl { body, .. } | StmtKind::Block(body) => {
                collect_self_data_attrs_in_stmts(body, out);
            }
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                collect_self_data_attrs_in_stmts(then_body, out);
                for (_, body) in elifs {
                    collect_self_data_attrs_in_stmts(body, out);
                }
                if let Some(body) = else_body {
                    collect_self_data_attrs_in_stmts(body, out);
                }
            }
            StmtKind::While {
                body, else_body, ..
            }
            | StmtKind::ForIn {
                body, else_body, ..
            } => {
                collect_self_data_attrs_in_stmts(body, out);
                if let Some(body) = else_body {
                    collect_self_data_attrs_in_stmts(body, out);
                }
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                collect_self_data_attrs_in_stmts(body, out);
                for catch in catches {
                    collect_self_data_attrs_in_stmts(&catch.body, out);
                }
                if let Some(body) = else_body {
                    collect_self_data_attrs_in_stmts(body, out);
                }
                if let Some(body) = finally {
                    collect_self_data_attrs_in_stmts(body, out);
                }
            }
            _ => {}
        }
    }
}

fn collect_self_float_attrs_in_stmts(
    __w: &mut PyWalker,
    stmts: &[Statement],
    float_vars: &std::collections::HashSet<String>,
    out: &mut std::collections::HashSet<String>,
) {
    for stmt in stmts {
        match &stmt.kind {
            StmtKind::Assign { targets, value, .. } => {
                for target in targets {
                    if let ExprKind::Member { object, field, .. } = &target.kind
                        && matches!(&object.kind, ExprKind::Ident(name) if name == "self")
                        && expr_is_self_float_expr(__w, value, float_vars, out)
                    {
                        out.insert(field.clone());
                    }
                    if let ExprKind::Index { object, index, .. } = &target.kind
                        && matches!(&object.kind, ExprKind::Ident(name) if name == "self")
                        && let ExprKind::Lit(Literal::Str(field)) = &index.kind
                        && expr_is_self_float_expr(__w, value, float_vars, out)
                    {
                        out.insert(field.clone());
                    }
                }
            }
            StmtKind::FunctionDecl { body, params, .. } => {
                let mut nested_float_vars = float_vars.clone();
                for param in params {
                    if param.type_hint.as_deref() == Some("float")
                        || param
                            .default
                            .as_ref()
                            .is_some_and(|default| expr_is_python_float(__w, default))
                    {
                        nested_float_vars.insert(param.name.clone());
                    }
                }
                collect_self_float_attrs_in_stmts(__w, body, &nested_float_vars, out);
            }
            StmtKind::Block(body) => collect_self_float_attrs_in_stmts(__w, body, float_vars, out),
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                collect_self_float_attrs_in_stmts(__w, then_body, float_vars, out);
                for (_, body) in elifs {
                    collect_self_float_attrs_in_stmts(__w, body, float_vars, out);
                }
                if let Some(body) = else_body {
                    collect_self_float_attrs_in_stmts(__w, body, float_vars, out);
                }
            }
            StmtKind::While {
                body, else_body, ..
            }
            | StmtKind::ForIn {
                body, else_body, ..
            } => {
                collect_self_float_attrs_in_stmts(__w, body, float_vars, out);
                if let Some(body) = else_body {
                    collect_self_float_attrs_in_stmts(__w, body, float_vars, out);
                }
            }
            StmtKind::Try {
                body,
                catches,
                finally,
                else_body,
            } => {
                collect_self_float_attrs_in_stmts(__w, body, float_vars, out);
                for catch in catches {
                    collect_self_float_attrs_in_stmts(__w, &catch.body, float_vars, out);
                }
                if let Some(body) = finally {
                    collect_self_float_attrs_in_stmts(__w, body, float_vars, out);
                }
                if let Some(body) = else_body {
                    collect_self_float_attrs_in_stmts(__w, body, float_vars, out);
                }
            }
            _ => {}
        }
    }
}

fn expr_is_self_float_expr(
    __w: &mut PyWalker,
    expr: &Expression,
    float_vars: &std::collections::HashSet<String>,
    float_self_attrs: &std::collections::HashSet<String>,
) -> bool {
    match &expr.kind {
        ExprKind::Ident(name) => float_vars.contains(name),
        ExprKind::Member { object, field, .. } if matches!(&object.kind, ExprKind::Ident(name) if name == "self") => {
            float_self_attrs.contains(field)
        }
        ExprKind::Index { object, index, .. } if matches!(&object.kind, ExprKind::Ident(name) if name == "self") =>
        {
            matches!(&index.kind, ExprKind::Lit(Literal::Str(field)) if float_self_attrs.contains(field.as_str()))
        }
        ExprKind::Call { callee, args, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_obj_get__")
                && args.len() == 2
                && matches!(&args[0].value.kind, ExprKind::Ident(name) if name == "self") =>
        {
            matches!(&args[1].value.kind, ExprKind::Lit(Literal::Str(field)) if float_self_attrs.contains(field.as_str()))
        }
        ExprKind::Binary { op: BinOp::Div, .. } => true,
        ExprKind::Binary {
            op: BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Mod | BinOp::Pow | BinOp::FloorDiv,
            left,
            right,
        } => {
            expr_is_self_float_expr(__w, left, float_vars, float_self_attrs)
                || expr_is_self_float_expr(__w, right, float_vars, float_self_attrs)
        }
        ExprKind::Unary {
            op: UnaryOp::Neg | UnaryOp::Pos,
            expr,
        } => expr_is_self_float_expr(__w, expr, float_vars, float_self_attrs),
        ExprKind::Call { callee, args, .. } if matches!(&callee.kind, ExprKind::Ident(name) if is_py_arith_helper(name)) => {
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__pytruediv__") {
                return !operand_overloads_truediv(__w, args);
            }
            args.iter()
                .any(|arg| expr_is_self_float_expr(__w, &arg.value, float_vars, float_self_attrs))
        }
        _ => expr_is_python_float(__w, expr),
    }
}

fn rewrite_self_data_attrs_in_stmts(
    data_attrs: &std::collections::HashSet<String>,
    stmts: &mut [Statement],
) {
    for stmt in stmts {
        match &mut stmt.kind {
            StmtKind::Expr(expr) | StmtKind::Return(Some(expr)) => {
                rewrite_self_data_attrs_in_expr(data_attrs, expr)
            }
            StmtKind::Assign { targets, value, .. } => {
                for target in targets {
                    rewrite_self_data_attrs_in_target(data_attrs, target);
                }
                rewrite_self_data_attrs_in_expr(data_attrs, value);
            }
            StmtKind::Delete(targets) => {
                for target in &mut *targets {
                    rewrite_self_data_attrs_in_target(data_attrs, target);
                }
                if targets.len() == 1
                    && let ExprKind::Index { object, index, .. } = &targets[0].kind
                    && matches!(&object.kind, ExprKind::Ident(name) if name == "self")
                    && let ExprKind::Lit(Literal::Str(field)) = &index.kind
                {
                    stmt.kind = StmtKind::Expr(call_ident(
                        "__py_obj_delete__",
                        vec![
                            Expression::ident("self"),
                            Expression::string(field.as_str()),
                        ],
                    ));
                }
            }
            StmtKind::VarDecl { declarations, .. } => {
                for decl in declarations {
                    if let Some(init) = &mut decl.init {
                        rewrite_self_data_attrs_in_expr(data_attrs, init);
                    }
                }
            }
            StmtKind::FunctionDecl { body, .. } | StmtKind::Block(body) => {
                rewrite_self_data_attrs_in_stmts(data_attrs, body);
            }
            StmtKind::If {
                cond,
                then_body,
                elifs,
                else_body,
            } => {
                rewrite_self_data_attrs_in_expr(data_attrs, cond);
                rewrite_self_data_attrs_in_stmts(data_attrs, then_body);
                for (cond, body) in elifs {
                    rewrite_self_data_attrs_in_expr(data_attrs, cond);
                    rewrite_self_data_attrs_in_stmts(data_attrs, body);
                }
                if let Some(body) = else_body {
                    rewrite_self_data_attrs_in_stmts(data_attrs, body);
                }
            }
            StmtKind::While {
                cond,
                body,
                else_body,
            } => {
                rewrite_self_data_attrs_in_expr(data_attrs, cond);
                rewrite_self_data_attrs_in_stmts(data_attrs, body);
                if let Some(body) = else_body {
                    rewrite_self_data_attrs_in_stmts(data_attrs, body);
                }
            }
            StmtKind::ForIn {
                iter,
                body,
                else_body,
                ..
            } => {
                rewrite_self_data_attrs_in_expr(data_attrs, iter);
                rewrite_self_data_attrs_in_stmts(data_attrs, body);
                if let Some(body) = else_body {
                    rewrite_self_data_attrs_in_stmts(data_attrs, body);
                }
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                rewrite_self_data_attrs_in_stmts(data_attrs, body);
                for catch in catches {
                    rewrite_self_data_attrs_in_stmts(data_attrs, &mut catch.body);
                }
                if let Some(body) = else_body {
                    rewrite_self_data_attrs_in_stmts(data_attrs, body);
                }
                if let Some(body) = finally {
                    rewrite_self_data_attrs_in_stmts(data_attrs, body);
                }
            }
            StmtKind::Throw { expr, cause } => {
                if let Some(expr) = expr {
                    rewrite_self_data_attrs_in_expr(data_attrs, expr);
                }
                if let Some(cause) = cause {
                    rewrite_self_data_attrs_in_expr(data_attrs, cause);
                }
            }
            _ => {}
        }
    }
}

/// Append the `__init__` a `@dataclass` generates: one positional parameter
/// per annotated field, in declaration order, carrying that field's default,
/// with a body that assigns each onto `self`.
///
/// An explicitly written `__init__` wins — CPython only generates what the
/// class does not already define.
fn synthesize_dataclass_members(
    __w: &mut PyWalker,
    class_name: &str,
    body: &mut Vec<Statement>,
    options: DataclassOptions,
) {
    let own_fields = dataclass_fields(body);
    let mut fields = inherited_dataclass_fields(__w, class_name);
    merge_dataclass_fields(&mut fields, own_fields);
    note_dataclass_options(__w, class_name, options);
    note_dataclass_fields(__w, class_name, &fields);

    if !has_method(body, "__init__") {
        let mut params = vec![plain_param("self", None)];
        let mut init_body = Vec::new();
        for field in &fields {
            if field.init {
                let default = if field.default_factory.is_some() {
                    Some(Expression::new(ExprKind::Lit(Literal::Null)))
                } else {
                    field.default.clone()
                };
                params.push(dataclass_param(field, default));
            }
            // An `InitVar` is a parameter only — PEP 557 hands it to
            // `__post_init__` and never stores it on the instance.
            if field.init_var {
                continue;
            }
            let value = if field.init {
                if let Some(factory) = &field.default_factory {
                    Expression::new(ExprKind::Ternary {
                        cond: Box::new(binop(
                            BinOp::StrictEq,
                            Expression::ident(&field.name),
                            Expression::new(ExprKind::Lit(Literal::Null)),
                        )),
                        then: Box::new(dataclass_default_factory_call(factory)),
                        else_: Box::new(Expression::ident(&field.name)),
                    })
                } else {
                    Expression::new(ExprKind::Ident(field.name.clone()))
                }
            } else if let Some(factory) = &field.default_factory {
                dataclass_default_factory_call(factory)
            } else {
                field
                    .default
                    .clone()
                    .unwrap_or_else(|| Expression::new(ExprKind::Lit(Literal::Null)))
            };
            init_body.push(Statement::new(StmtKind::Assign {
                targets: vec![self_attr(&field.name)],
                value: dataclass_store_value(field, value),
                by_ref: false,
            }));
        }
        // `__post_init__(self, *init_vars)` runs last, once every real field
        // is assigned, so it can derive attributes from them.
        if has_method(body, "__post_init__") {
            let init_vars: Vec<Expression> = fields
                .iter()
                .filter(|f| f.init_var)
                .map(|f| Expression::ident(&f.name))
                .collect();
            init_body.push(Statement::new(StmtKind::Expr(Expression::new(
                ExprKind::Call {
                    callee: Box::new(Expression::new(ExprKind::Member {
                        object: Box::new(Expression::ident("self")),
                        field: "__post_init__".into(),
                        null_safe: false,
                    })),
                    args: init_vars.into_iter().map(Argument::positional).collect(),
                    optional: false,
                },
            ))));
        }
        // FRONT, not back. Field types are inferred from the constructor's
        // assignments, and a method compiled BEFORE the constructor sees no
        // type for `self.x` — `"lit" + str(self.x)` then takes the numeric
        // path and traps in `toF64`. A generated `__init__` appended last hit
        // that for every user method in the class; declaring it first is also
        // what CPython's decorator means, since order carries no semantics.
        body.insert(0, fn_decl("__init__", params, init_body));
    }
    if !has_method(body, "__repr__") {
        body.push(dataclass_repr(class_name, &fields));
    }
    if !has_method(body, "__eq__") {
        body.push(dataclass_eq(&fields));
    }
    if !has_method(body, "__hash__") {
        body.push(dataclass_hash(class_name, &fields));
    }
    if options.order && !has_method(body, "__lt__") {
        body.push(dataclass_lt(&fields));
    }
    // `__dataclass_fields__` is what CPython's `dataclasses` module reads:
    // `is_dataclass` tests for it, and `fields`/`asdict`/`astuple`/`replace`
    // walk it. Storing the names in declaration order also makes those four
    // deterministic, which reading the instance property bag would not be.
    body.push(Statement::new(StmtKind::Assign {
        targets: vec![Expression::ident("__dataclass_fields__")],
        value: Expression::new(ExprKind::Array(
            fields
                .iter()
                .filter(|f| !f.init_var)
                .map(|f| ArrayElement {
                    key: None,
                    value: Expression::string(&f.name),
                    spread: false,
                    by_ref: false,
                })
                .collect(),
        )),
        by_ref: false,
    }));
    body.push(Statement::new(StmtKind::Assign {
        targets: vec![Expression::ident("__match_args__")],
        value: Expression::new(ExprKind::Tuple(
            fields
                .iter()
                .filter(|f| !f.init_var && f.init && !f.kw_only && !options.kw_only)
                .map(|f| Expression::string(&f.name))
                .collect(),
        )),
        by_ref: false,
    }));
}

fn synthesize_python_class_defaults(
    __w: &mut PyWalker,
    class_name: &str,
    body: &mut Vec<Statement>,
) {
    if py_class_is_subclass(__w, class_name, "BaseException")
        || py_class_is_subclass(__w, class_name, "Exception")
    {
        if !has_method(body, "__init__") && !class_parent_has_init(__w, class_name) {
            let message = Expression::ident("message");
            body.push(fn_decl(
                "__init__",
                vec![
                    plain_param("self", None),
                    plain_param("message", Some(Expression::string(""))),
                ],
                vec![
                    Statement::new(StmtKind::Assign {
                        targets: vec![self_attr("message")],
                        value: message.clone(),
                        by_ref: false,
                    }),
                    Statement::new(StmtKind::Assign {
                        targets: vec![self_attr("args")],
                        value: Expression::new(ExprKind::Tuple(vec![message])),
                        by_ref: false,
                    }),
                    Statement::new(StmtKind::Assign {
                        targets: vec![self_attr("stack")],
                        value: Expression::string(""),
                        by_ref: false,
                    }),
                ],
            ));
        }
        if !has_method(body, "__str__") {
            body.push(fn_decl(
                "__str__",
                vec![plain_param("self", None)],
                vec![Statement::new(StmtKind::Return(Some(call_ident(
                    "__py_exception_message",
                    vec![Expression::ident("self")],
                ))))],
            ));
        }
    }
    if !has_method(body, "__repr__") {
        body.push(fn_decl(
            "__repr__",
            vec![plain_param("self", None)],
            vec![Statement::new(StmtKind::Return(Some(Expression::string(
                &format!("<{} object>", class_name),
            ))))],
        ));
    }
    if !has_method(body, "__eq__") {
        body.push(fn_decl(
            "__eq__",
            vec![plain_param("self", None), plain_param("other", None)],
            vec![Statement::new(StmtKind::Return(Some(Expression::new(
                ExprKind::Binary {
                    op: BinOp::StrictEq,
                    left: Box::new(Expression::ident("self")),
                    right: Box::new(Expression::ident("other")),
                },
            ))))],
        ));
    }
    if !has_method(body, "__hash__") {
        body.push(fn_decl(
            "__hash__",
            vec![plain_param("self", None)],
            vec![Statement::new(StmtKind::Throw {
                expr: Some(Expression::new(ExprKind::Call {
                    callee: Box::new(Expression::ident("TypeError")),
                    args: vec![Argument::positional(Expression::string(&format!(
                        "unhashable type: '{}'",
                        class_name
                    )))],
                    optional: false,
                })),
                cause: None,
            })],
        ));
    }
    if has_method(body, "__init__") {
        note_class_with_init(__w, class_name);
    }
}

fn synthesize_total_ordering_members(body: &mut Vec<Statement>) {
    let self_expr = || Expression::ident("self");
    let other_expr = || Expression::ident("other");
    let self_call = |name: &str| py_call(py_member(self_expr(), name), vec![other_expr()]);
    if !has_method(body, "__le__") && has_method(body, "__lt__") {
        body.push(fn_decl(
            "__le__",
            vec![plain_param("self", None), plain_param("other", None)],
            vec![Statement::new(StmtKind::Return(Some(Expression::new(
                ExprKind::Binary {
                    op: BinOp::Or,
                    left: Box::new(self_call("__lt__")),
                    right: Box::new(self_call("__eq__")),
                },
            ))))],
        ));
    }
    if !has_method(body, "__gt__") && has_method(body, "__lt__") {
        body.push(fn_decl(
            "__gt__",
            vec![plain_param("self", None), plain_param("other", None)],
            vec![Statement::new(StmtKind::Return(Some(py_call(
                py_member(other_expr(), "__lt__"),
                vec![self_expr()],
            ))))],
        ));
    }
    if !has_method(body, "__ge__") && has_method(body, "__lt__") {
        body.push(fn_decl(
            "__ge__",
            vec![plain_param("self", None), plain_param("other", None)],
            vec![Statement::new(StmtKind::Return(Some(Expression::new(
                ExprKind::Unary {
                    op: UnaryOp::Not,
                    expr: Box::new(self_call("__lt__")),
                },
            ))))],
        ));
    }
}

fn normalize_exception_super_init(__w: &mut PyWalker, class_name: &str, body: &mut [Statement]) {
    if !(py_class_is_subclass(__w, class_name, "BaseException")
        || py_class_is_subclass(__w, class_name, "Exception"))
    {
        return;
    }
    for stmt in body {
        let StmtKind::FunctionDecl {
            name,
            body: fn_body,
            ..
        } = &mut stmt.kind
        else {
            continue;
        };
        if name != "__init__" {
            continue;
        }
        let mut rewritten = Vec::with_capacity(fn_body.len());
        for inner in fn_body.drain(..) {
            let maybe_args = match &inner.kind {
                StmtKind::Expr(Expression {
                    kind: ExprKind::Call { callee, args, .. },
                    ..
                }) if matches!(&callee.kind, ExprKind::Super) => {
                    Some(args.iter().map(|a| a.value.clone()).collect::<Vec<_>>())
                }
                _ => None,
            };
            rewritten.push(inner);
            if let Some(args) = maybe_args {
                rewritten.push(Statement::new(StmtKind::Assign {
                    targets: vec![self_attr("args")],
                    value: Expression::new(ExprKind::Tuple(args)),
                    by_ref: false,
                }));
            }
        }
        *fn_body = rewritten;
    }
}

/// Replace `auto()` in an enum body with the value CPython's `_auto_called`
/// machinery would have produced.
///
/// `auto()` has no meaning on its own — it is resolved by the enum metaclass
/// from the members declared BEFORE it, which is exactly the information a
/// class body has here and nowhere else. `Enum` counts up from the last value
/// (starting at 1); `Flag` takes the next power of two, so its members stay
/// disjoint bits.
fn resolve_enum_auto(parents: &[String], body: &mut [Statement]) {
    let base = |suffix: &str| {
        parents
            .iter()
            .any(|p| p == suffix || p.ends_with(&format!(".{suffix}")))
    };
    let is_flag = base("Flag") || base("IntFlag");
    if !is_flag && !(base("Enum") || base("IntEnum") || base("StrEnum") || base("ReprEnum")) {
        return;
    }
    let is_auto_call = |e: &Expression| match &e.kind {
        ExprKind::Call { callee, args, .. } if args.is_empty() => match &callee.kind {
            ExprKind::Ident(n) => n == "auto",
            ExprKind::Member { object, field, .. } => {
                field == "auto" && matches!(&object.kind, ExprKind::Ident(m) if m == "enum")
            }
            _ => false,
        },
        _ => false,
    };
    let mut last: i64 = 0;
    for stmt in body.iter_mut() {
        let StmtKind::Assign { targets, value, .. } = &mut stmt.kind else {
            continue;
        };
        if targets.len() != 1 || !matches!(&targets[0].kind, ExprKind::Ident(_)) {
            continue;
        }
        if let ExprKind::Lit(Literal::Int(n)) = &value.kind {
            last = *n as i64;
            continue;
        }
        if !is_auto_call(value) {
            continue;
        }
        let next = if is_flag {
            if last == 0 { 1 } else { last << 1 }
        } else {
            last + 1
        };
        last = next;
        let span = value.span;
        *value = Expression::with_span(ExprKind::Lit(Literal::Int(next)), span);
    }
}

fn walk_class_def(
    __w: &mut PyWalker,
    pair: Pair<Rule>,
    decorators: Vec<Expression>,
) -> Result<StmtKind, String> {
    let mut name = String::new();
    let mut parents = Vec::new();
    let mut class_kwargs: Vec<(String, Expression)> = Vec::new();
    let mut body_stmts = Vec::new();

    for p in pair.into_inner() {
        match p.as_rule() {
            Rule::identifier => {
                name = p.as_str().to_string();
                // Register the class name before its body is walked so
                // constructions inside its own methods normalise too.
                note_defined_class(__w, &name);
            }
            Rule::class_arg_list => {
                for arg in p.into_inner() {
                    if arg.as_rule() == Rule::class_arg {
                        // Just extract as string base name
                        let mut text = arg.as_str().trim().to_string();
                        // `class X(string.Template)` → the injected prelude
                        // global, so the base resolves to a real class.
                        if let Some(rest) = text.strip_prefix("string.") {
                            if let Some(name) = string_module_member(rest) {
                                text = name.to_string();
                            }
                        }
                        if let Some((key, raw_value)) = text.split_once('=')
                            && !text.starts_with("**")
                        {
                            let key = key.trim();
                            if key != "metaclass" {
                                class_kwargs.push((
                                    key.to_string(),
                                    python_class_arg_literal(raw_value.trim()),
                                ));
                            }
                        } else if !text.contains('=') && !text.starts_with("**") {
                            parents.push(text);
                        }
                    }
                }
            }
            Rule::block => body_stmts = walk_block(__w, p)?,
            _ => {}
        }
    }
    note_class_parents(__w, &name, &parents);
    if py_class_is_subclass(__w, &name, "__string_Template")
        && let Some(delimiter) = string_literal_class_assignment(&body_stmts, "delimiter")
    {
        __w.py_string_template_delimiters
            .insert(name.clone(), delimiter);
    }
    if let Some(doc) = function_docstring(&body_stmts) {
        note_class_doc(__w, &name, py_clean_docstring(&doc));
    }
    resolve_enum_auto(&parents, &mut body_stmts);

    let has_call_method = body_stmts.iter().any(|stmt| {
        matches!(
            &stmt.kind,
            StmtKind::FunctionDecl { name, .. } if name == "__call__"
        )
    });
    let has_init_method = body_stmts.iter().any(|stmt| {
        matches!(
            &stmt.kind,
            StmtKind::FunctionDecl { name, .. } if name == "__init__"
        )
    });
    let mut attrs = std::collections::HashSet::new();
    let mut data_attrs = std::collections::HashSet::new();
    let mut class_data_attrs = std::collections::HashSet::new();
    let mut class_float_data_attrs = std::collections::HashSet::new();
    let mut class_member_type_names = std::collections::HashMap::new();
    let mut class_slots: Option<std::collections::HashSet<String>> = None;
    let is_dataclass = decorators.iter().any(is_dataclass_decorator);
    let dataclass_scan_fields = if is_dataclass {
        dataclass_fields(&body_stmts)
    } else {
        Vec::new()
    };
    for field in &dataclass_scan_fields {
        if field.type_hint.as_deref() == Some("float") && !field.init_var {
            class_float_data_attrs.insert(field.name.clone());
        }
    }
    for stmt in &body_stmts {
        match &stmt.kind {
            StmtKind::FunctionDecl {
                name: method_name,
                body,
                params,
                modifiers,
                ..
            } => {
                attrs.insert(method_name.clone());
                if modifiers
                    .decorators
                    .iter()
                    .any(|d| matches!(&d.kind, ExprKind::Ident(n) if n == "classmethod"))
                    || method_name == "__class_getitem__"
                {
                    class_member_type_names.insert(method_name.clone(), "method");
                } else {
                    class_member_type_names.insert(method_name.clone(), "function");
                }
                collect_self_data_attrs_in_stmts(body, &mut data_attrs);
                if method_name == "__init_subclass__"
                    && let Some(class_param) = params.first()
                {
                    let mut writes = Vec::new();
                    collect_init_subclass_class_param_writes(body, &class_param.name, &mut writes);
                    note_init_subclass_writes(__w, &name, writes);
                }
                let mut float_vars = std::collections::HashSet::new();
                for param in params {
                    if param.type_hint.as_deref() == Some("float")
                        || param
                            .default
                            .as_ref()
                            .is_some_and(|default| expr_is_python_float(__w, default))
                    {
                        float_vars.insert(param.name.clone());
                    }
                }
                collect_self_float_attrs_in_stmts(
                    __w,
                    body,
                    &float_vars,
                    &mut class_float_data_attrs,
                );
            }
            StmtKind::VarDecl { declarations, .. } => {
                for d in declarations {
                    if let BindingPattern::Ident(attr) = &d.pattern {
                        if attr == "__slots__" {
                            if let Some(init) = &d.init {
                                class_slots = class_slots_from_expr(init);
                            }
                            continue;
                        }
                        // A value-less annotation (`x: int`) is NOT a class
                        // attribute — CPython records it in `__annotations__`
                        // only, and `C.x` raises AttributeError. Recording it
                        // rewrote every instance read `a.x` into the class
                        // read `A["x"]`, which is empty, so `p = P(1); p.x`
                        // returned `None` while `P(1).x` returned `1`.
                        if d.init.is_none()
                            || (is_dataclass
                                && d.init.as_ref().is_some_and(is_dataclass_field_call))
                        {
                            continue;
                        }
                        attrs.insert(attr.clone());
                        data_attrs.insert(attr.clone());
                        class_data_attrs.insert(attr.clone());
                    }
                }
            }
            StmtKind::Assign { targets, value, .. } => {
                for target in targets {
                    if let ExprKind::Ident(attr) = &target.kind {
                        if attr == "__slots__" {
                            class_slots = class_slots_from_expr(value);
                            continue;
                        }
                        attrs.insert(attr.clone());
                        data_attrs.insert(attr.clone());
                        class_data_attrs.insert(attr.clone());
                    }
                }
            }
            StmtKind::ClassDecl {
                name: nested_name, ..
            } => {
                attrs.insert(nested_name.clone());
                class_member_type_names.insert(nested_name.clone(), "type");
            }
            _ => {}
        }
    }
    if is_dataclass {
        for field in dataclass_scan_fields {
            if !field.init_var {
                data_attrs.insert(field.name.clone());
            }
        }
    }
    note_python_property_metadata(__w, &name, &body_stmts);
    rewrite_self_data_attrs_in_stmts(&data_attrs, &mut body_stmts);
    class_data_attrs.extend(data_attrs.iter().cloned());
    note_class_attrs(__w, &name, attrs);
    note_class_member_type_names(__w, &name, class_member_type_names);
    note_class_data_attrs(__w, &name, class_data_attrs);
    note_class_float_data_attrs(__w, &name, class_float_data_attrs);
    if let Some(slots) = class_slots {
        note_class_slots(__w, &name, slots);
    }
    if has_call_method {
        note_callable_class(__w, &name);
    }
    if has_init_method {
        note_class_with_init(__w, &name);
    }

    // `@dataclass` — synthesize the members CPython's decorator generates at
    // runtime. Done here, in the walker, because decorators never reach
    // `normalize_class` (the shared signature carries modifiers, not
    // decorators) and because synthesizing real AST members keeps the shared
    // class pipeline language-neutral.
    if is_dataclass {
        if dataclass_has_mutable_literal_default(&body_stmts) {
            return Ok(StmtKind::Throw {
                expr: Some(Expression::new(ExprKind::New {
                    class: Box::new(Expression::ident("ValueError")),
                    args: vec![Argument::positional(Expression::string(
                        "mutable default not allowed",
                    ))],
                })),
                cause: None,
            });
        }
        synthesize_dataclass_members(__w, &name, &mut body_stmts, dataclass_options(&decorators));
    }
    if decorators.iter().any(|d| decorator_root_ident(d) == Some("total_ordering")) {
        synthesize_total_ordering_members(&mut body_stmts);
    }
    synthesize_python_class_defaults(__w, &name, &mut body_stmts);
    normalize_exception_super_init(__w, &name, &mut body_stmts);
    mangle_private_members_in_stmts(&name, &mut body_stmts);

    // Convert body statements into ClassMembers
    let members = stmts_to_class_members(__w, &name, body_stmts);

    let class_decl = StmtKind::ClassDecl {
        name,
        parents,
        interfaces: Vec::new(),
        members,
        modifiers: ClassModifiers {
            // A `@dataclass` keeps REFERENCE storage — `b = a` still aliases —
            // but gets VALUE equality: the generated `__eq__` compares
            // field-by-field, which `dataclass_eq` above already synthesizes.
            // Declaring it here is what lets the shared lowering stop caring
            // which language wrote that method.
            semantics: ValueSemantics {
                equality: if is_dataclass {
                    ValueEquality::Structural
                } else {
                    ValueEquality::Identity
                },
                ..Default::default()
            },
            ..Default::default()
        },
        decorators: vec![],
    };
    Ok(desugar_init_subclass_hooks(__w, class_decl, class_kwargs))
}

fn method_call_args_from_params(params: &[Param]) -> Vec<Argument> {
    params
        .iter()
        .map(|p| Argument {
            value: Expression::ident(&p.name),
            name: None,
            by_ref: false,
            spread: p.is_rest || p.is_kwargs,
        })
        .collect()
}

fn decorated_method_body(
    __w: &mut PyWalker,
    name: &str,
    params: &[Param],
    return_type: &Option<String>,
    body: &[Statement],
    decorators: Vec<Expression>,
) -> Vec<Statement> {
    let original_name = format!("__py_orig_{name}");
    let original = StmtKind::FunctionDecl {
        name: original_name.clone(),
        params: params.to_vec(),
        return_type: return_type.clone(),
        body: body.to_vec(),
        modifiers: Modifiers::default(),
        handles: Vec::new(),
        is_async: false,
        is_generator: false,
        is_sub: false,
    };
    let mut stmts = vec![Statement::new(original)];
    assign_function_metadata(
        &mut stmts,
        &original_name,
        params,
        return_type.as_ref(),
        body,
    );
    let decorated = call_decorator_stack(__w, decorators, Expression::ident(&original_name));
    stmts.push(Statement::new(StmtKind::Return(Some(Expression::new(
        ExprKind::Call {
            callee: Box::new(decorated),
            args: method_call_args_from_params(params),
            optional: false,
        },
    )))));
    stmts
}

fn block_desugared_function(stmt: &Statement) -> Option<StmtKind> {
    let StmtKind::Block(stmts) = &stmt.kind else {
        return None;
    };
    let Some(first) = stmts.first() else {
        return None;
    };
    let StmtKind::FunctionDecl {
        name: _name,
        params,
        return_type,
        body: _body,
        modifiers,
        handles,
        is_async,
        is_generator,
        is_sub,
    } = &first.kind
    else {
        return None;
    };
    let (public_name, final_value) = stmts.iter().rev().find_map(|s| {
        if let StmtKind::Assign { targets, value, .. } = &s.kind
            && targets.len() == 1
            && let ExprKind::Ident(public) = &targets[0].kind
        {
            return Some((public.clone(), value.clone()));
        }
        None
    })?;
    let wrapped_body = vec![
        Statement::new(first.kind.clone()),
        Statement::new(StmtKind::Return(Some(Expression::new(ExprKind::Call {
            callee: Box::new(final_value),
            args: method_call_args_from_params(params),
            optional: false,
        })))),
    ];
    Some(StmtKind::FunctionDecl {
        name: public_name,
        params: params.clone(),
        return_type: return_type.clone(),
        body: wrapped_body,
        modifiers: modifiers.clone(),
        handles: handles.clone(),
        is_async: *is_async,
        is_generator: *is_generator,
        is_sub: *is_sub,
    })
}

fn stmts_to_class_members(
    __w: &mut PyWalker,
    class_name: &str,
    stmts: Vec<Statement>,
) -> Vec<ClassMember> {
    let mut members: Vec<ClassMember> = Vec::new();
    // Track Property member index by name so @x.setter can find the getter.
    let mut property_indices: std::collections::HashMap<String, usize> =
        std::collections::HashMap::new();

    for stmt in stmts {
        let stmt = if let Some(recovered) = block_desugared_function(&stmt) {
            Statement::new(recovered)
        } else {
            stmt
        };
        match &stmt.kind {
            StmtKind::FunctionDecl {
                name,
                params,
                return_type,
                body,
                modifiers,
                is_async,
                ..
            } => {
                if name == "__init__" {
                    // Constructor — keep `self` param; compiler strips it
                    // via `NormalClass.explicit_self_param` (set by
                    // normalize_class).
                    members.push(ClassMember::Constructor {
                        // Python has one constructor, `__init__` — unnamed.
                        name: None,
                        params: params.clone(),
                        body: body.clone(),
                        base_args: None,
                        initializer_target: vybe_ast::ConstructorInitializerTarget::Base,
                        visibility: Visibility::Public,
                    });
                    continue;
                }

                // Check for @property decorator → build Property getter
                let has_property = modifiers
                    .decorators
                    .iter()
                    .any(|d| matches!(&d.kind, ExprKind::Ident(n) if n == "property" || n == "cached_property"));
                if has_property {
                    note_class_property_kind(__w, class_name, name, "getter");
                    note_class_property_doc(__w, class_name, name, function_docstring(body));
                    if property_getter_returns_float(__w, class_name, body) {
                        note_class_property_returns_float(__w, class_name, name);
                    }
                    let idx = members.len();
                    members.push(ClassMember::Property {
                        name: name.clone(),
                        type_hint: None,
                        getter: Some(body.clone()),
                        setter: None,
                        is_auto: false,
                        modifiers: Modifiers::default(),
                    });
                    property_indices.insert(name.clone(), idx);
                    continue;
                }

                // Check for @x.setter / @x.getter / @x.deleter. Getter/setter
                // stay in `ClassMember::Property` so the common class emitter
                // publishes `__get_<name>` / `__set_<name>` accessors. Deleter
                // has no ClassMember slot today, so do not fake it here.
                let accessor_target = modifiers
                    .decorators
                    .iter()
                    .find_map(property_accessor_decorator);
                if let Some((prop_name, "getter")) = accessor_target {
                    note_class_property_kind(__w, class_name, &prop_name, "getter");
                    note_class_property_doc(__w, class_name, &prop_name, function_docstring(body));
                    if property_getter_returns_float(__w, class_name, body) {
                        note_class_property_returns_float(__w, class_name, &prop_name);
                    }
                    if let Some(&prop_idx) = property_indices.get(&prop_name) {
                        if let ClassMember::Property { getter, .. } = &mut members[prop_idx] {
                            *getter = Some(body.clone());
                        }
                    } else {
                        let idx = members.len();
                        members.push(ClassMember::Property {
                            name: prop_name.clone(),
                            type_hint: None,
                            getter: Some(body.clone()),
                            setter: None,
                            is_auto: false,
                            modifiers: Modifiers::default(),
                        });
                        property_indices.insert(prop_name.clone(), idx);
                    }
                    continue;
                }
                if let Some((prop_name, "setter")) = accessor_target {
                    note_class_property_kind(__w, class_name, &prop_name, "setter");
                    if let Some(&prop_idx) = property_indices.get(&prop_name) {
                        if let ClassMember::Property { setter, .. } = &mut members[prop_idx] {
                            // Second param (after self) is the value param
                            let value_param = params.iter().nth(1).cloned().unwrap_or(Param {
                                name: "value".to_string(),
                                type_hint: None,
                                default: None,
                                pass_by: PassBy::Value,
                                is_rest: false,
                                is_kwargs: false,
                                is_optional: false,
                                is_nullable: false,
                            });
                            *setter = Some(vybe_ast::PropertySetter {
                                param: value_param,
                                body: body.clone(),
                            });
                        }
                    }
                    continue;
                }
                if let Some((prop_name, "deleter")) = accessor_target {
                    note_class_property_kind(__w, class_name, &prop_name, "deleter");
                    let mut deleter = stmt.clone();
                    if let StmtKind::FunctionDecl {
                        name, modifiers, ..
                    } = &mut deleter.kind
                    {
                        *name = format!("__del_{prop_name}");
                        modifiers.decorators.clear();
                    }
                    members.push(ClassMember::Method(Box::new(deleter)));
                    continue;
                }

                // Method — keep `self`/`cls` param; compiler strips via
                // `NormalClass.explicit_self_param`.
                let has_staticmethod =
                    matches!(name.as_str(), "__class_getitem__" | "__init_subclass__")
                        || modifiers
                            .decorators
                            .iter()
                            .any(|d| matches!(&d.kind, ExprKind::Ident(n) if n == "staticmethod"));
                let has_classmethod = modifiers
                    .decorators
                    .iter()
                    .any(|d| matches!(&d.kind, ExprKind::Ident(n) if n == "classmethod"));
                let general_decorators: Vec<Expression> = modifiers
                    .decorators
                    .iter()
                    .filter(|d| !is_special_decorator(d))
                    .cloned()
                    .collect();
                let mut final_body = if general_decorators.is_empty() {
                    body.clone()
                } else {
                    decorated_method_body(__w, name, params, return_type, body, general_decorators)
                };
                if name == "__init_subclass__"
                    && let Some(class_param) = params.first()
                {
                    rewrite_init_subclass_class_param_writes(&mut final_body, &class_param.name);
                }
                if has_classmethod && let Some(class_param) = params.first() {
                    replace_ident_in_stmts(&mut final_body, &class_param.name, class_name);
                }
                // For @staticmethod, prepend a dummy "self" so that
                // explicit_self_param's skip(1) removes the dummy, keeping
                // the real params intact. Without this, skip(1) would drop
                // the first real param (e.g. `a` in `def add(a, b)`).
                let final_params = if has_staticmethod {
                    let dummy = Param {
                        name: "self".to_string(),
                        type_hint: None,
                        default: None,
                        pass_by: PassBy::Value,
                        is_rest: false,
                        is_kwargs: false,
                        is_optional: false,
                        is_nullable: false,
                    };
                    let mut p = vec![dummy];
                    p.extend_from_slice(params);
                    p
                } else if has_classmethod {
                    let dummy = Param {
                        name: "self".to_string(),
                        type_hint: None,
                        default: None,
                        pass_by: PassBy::Value,
                        is_rest: false,
                        is_kwargs: false,
                        is_optional: false,
                        is_nullable: false,
                    };
                    let mut p = vec![dummy];
                    p.extend_from_slice(params.get(1..).unwrap_or(&[]));
                    p
                } else {
                    params.clone()
                };
                let is_static = has_staticmethod
                    || has_classmethod
                    || final_params.first().map_or(true, |p| p.name != "self");
                let mut mods = modifiers.clone();
                mods.decorators.retain(is_special_decorator);
                mods.is_static = is_static;
                members.push(ClassMember::Method(Box::new(Statement::new(
                    StmtKind::FunctionDecl {
                        name: name.clone(),
                        params: final_params,
                        return_type: None,
                        body: final_body,
                        modifiers: mods,
                        handles: Vec::new(),
                        is_async: *is_async,
                        is_generator: false,
                        is_sub: false,
                    },
                ))));
            }
            // Annotated class-level declaration (`x: int = 0`, or bare
            // `x: int`). The type hint is what marks it a dataclass field, so
            // it is carried onto the member rather than dropped.
            //
            // Only the form WITH a value is a member at all. A bare
            // `x: int` binds nothing in CPython — `P.x` raises
            // AttributeError — it just records `__annotations__` and lets
            // `__init__` create the attribute. Emitting it as a static class
            // attribute made that empty attribute shadow the instance write,
            // so `p = P(1); p.x` read `None` while `P(1).x` read `1`. The
            // dataclass field list is derived from the body statements
            // (`dataclass_fields`), not from these members, so dropping the
            // value-less form costs nothing there.
            StmtKind::VarDecl { declarations, .. } => {
                for d in declarations {
                    let BindingPattern::Ident(field_name) = &d.pattern else {
                        continue;
                    };
                    if d.init.is_none() || d.init.as_ref().is_some_and(is_dataclass_field_call) {
                        continue;
                    }
                    let mut mods = Modifiers::default();
                    mods.is_static = true;
                    members.push(ClassMember::Field {
                        name: field_name.clone(),
                        type_hint: d.type_hint.clone().as_deref().map(str::to_string),
                        init: d.init.clone(),
                        modifiers: mods,
                        with_events: false,
                        array_bounds: None,
                        storage: None,
                    });
                }
            }
            StmtKind::Assign { targets, value, .. } => {
                // A class-level assignment is a CLASS ATTRIBUTE: `C.x` reads it
                // and so does `c.x`. A static `Field` only writes a global of
                // that name — nothing lands on the class object, so `C.x`
                // answered None and every descriptor (`x = D()`) was invisible.
                // `Const` is the member that stamps the value onto the class.
                for target in targets {
                    if let ExprKind::Ident(field_name) = &target.kind {
                        // ⛔ A SYNTHESIZED dunder stays a static FIELD. The
                        // dataclass transform adds `__dataclass_fields__` and
                        // `__match_args__` as class-level assignments, and
                        // `Const` — which writes a global and stamps the class
                        // object — never reaches `TypeEntry.fields`, so both
                        // vanished and every dataclass field read threw
                        // (`py_dataclasses` 13 -> 4).
                        if field_name.starts_with("__") && field_name.ends_with("__") {
                            let mut mods = Modifiers::default();
                            mods.is_static = true;
                            members.push(ClassMember::Field {
                                name: field_name.clone(),
                                type_hint: None,
                                init: Some(value.clone()),
                                modifiers: mods,
                                with_events: false,
                                array_bounds: None,
                                storage: None,
                            });
                            continue;
                        }
                        // A class-level assignment is a STATIC FIELD. It lands
                        // on the class object because python declares
                        // `static_fields_are_own_properties` — the shared
                        // mechanism, rather than a second one here.
                        let mut mods = Modifiers::default();
                        mods.is_static = true;
                        members.push(ClassMember::Field {
                            name: field_name.clone(),
                            type_hint: None,
                            init: Some(value.clone()),
                            modifiers: mods,
                            with_events: false,
                            array_bounds: None,
                            storage: None,
                        });
                    }
                }
            }
            StmtKind::ClassDecl { .. } => {
                members.push(ClassMember::NestedType(Box::new(stmt)));
            }
            StmtKind::Empty => {} // pass
            _ => {
                // Nested class or other — wrap as method
                members.push(ClassMember::Method(Box::new(stmt)));
            }
        }
    }
    members
}

fn dynamic_type_base_name(expr: &Expression) -> Option<String> {
    match &expr.kind {
        ExprKind::Ident(name) if name != "type" && name != "object" => Some(name.clone()),
        ExprKind::Call { callee, args, .. } | ExprKind::New { class: callee, args }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_type_obj")
                && args.len() == 1 =>
        {
            if let ExprKind::Lit(Literal::Str(name)) = &args[0].value.kind {
                if name == "object" {
                    None
                } else {
                    Some(name.to_string())
                }
            } else {
                None
            }
        }
        _ => None,
    }
}

fn dynamic_type_bases(expr: &Expression) -> Vec<String> {
    match &expr.kind {
        ExprKind::Tuple(items) => items.iter().filter_map(dynamic_type_base_name).collect(),
        ExprKind::Array(items) => items
            .iter()
            .filter(|item| item.key.is_none() && !item.spread)
            .filter_map(|item| dynamic_type_base_name(&item.value))
            .collect(),
        _ => dynamic_type_base_name(expr).into_iter().collect(),
    }
}

fn namespace_key_name(expr: &Expression) -> Option<String> {
    match &expr.kind {
        ExprKind::Lit(Literal::Str(name)) => Some(name.to_string()),
        _ => None,
    }
}

fn dynamic_type_lambda_method(name: &str, params: &[Param], body: &LambdaBody) -> Statement {
    let fn_body = match body {
        LambdaBody::Expr(expr) => vec![Statement::new(StmtKind::Return(Some((**expr).clone())))],
        LambdaBody::Block(stmts) => stmts.clone(),
    };
    Statement::new(StmtKind::FunctionDecl {
        name: name.to_string(),
        params: params.to_vec(),
        return_type: None,
        body: fn_body,
        modifiers: Modifiers::default(),
        handles: Vec::new(),
        is_async: false,
        is_generator: false,
        is_sub: false,
    })
}

fn dynamic_type_forwarding_method(__w: &mut PyWalker, name: &str, target_fn: &str) -> Statement {
    let params = defined_function_params(__w, target_fn).unwrap_or_else(|| {
        let self_param = plain_param("self", None);
        let mut rest = plain_param("__py_args", None);
        rest.is_rest = true;
        vec![self_param, rest]
    });
    if let Some(mut body) = defined_function_body(__w, target_fn) {
        if name == "__init__" {
            for param in params.iter().skip(1).filter(|p| !p.is_rest && !p.is_kwargs) {
                body.push(Statement::new(StmtKind::Expr(call_ident(
                    "__py_attr_raw_write",
                    vec![
                        Expression::ident("self"),
                        Expression::string(&param.name),
                        Expression::ident(&param.name),
                    ],
                ))));
            }
            if !matches!(
                body.last().map(|stmt| &stmt.kind),
                Some(StmtKind::Return(_))
            ) {
                body.push(Statement::new(StmtKind::Return(Some(Expression::null()))));
            }
        }
        return Statement::new(StmtKind::FunctionDecl {
            name: name.to_string(),
            params,
            return_type: None,
            body,
            modifiers: Modifiers::default(),
            handles: Vec::new(),
            is_async: false,
            is_generator: false,
            is_sub: false,
        });
    }
    let args = params
        .iter()
        .map(|param| Argument {
            value: Expression::ident(&param.name),
            name: None,
            by_ref: false,
            spread: param.is_rest || param.is_kwargs,
        })
        .collect();
    let call = Expression::new(ExprKind::Call {
        callee: Box::new(Expression::ident(target_fn)),
        args,
        optional: false,
    });
    let body = if name == "__init__" {
        let mut body = vec![Statement::new(StmtKind::Expr(call))];
        for param in params.iter().skip(1).filter(|p| !p.is_rest && !p.is_kwargs) {
            body.push(Statement::new(StmtKind::Expr(call_ident(
                "__py_attr_raw_write",
                vec![
                    Expression::ident("self"),
                    Expression::string(&param.name),
                    Expression::ident(&param.name),
                ],
            ))));
        }
        body.push(Statement::new(StmtKind::Return(Some(Expression::null()))));
        body
    } else {
        vec![Statement::new(StmtKind::Return(Some(call)))]
    };
    Statement::new(StmtKind::FunctionDecl {
        name: name.to_string(),
        params,
        return_type: None,
        body,
        modifiers: Modifiers::default(),
        handles: Vec::new(),
        is_async: false,
        is_generator: false,
        is_sub: false,
    })
}

fn dynamic_type_namespace_stmt(__w: &mut PyWalker, key: &str, value: Expression) -> Statement {
    match value.kind {
        ExprKind::Lambda {
            params,
            body,
            is_async: _,
            captures: _,
        } => dynamic_type_lambda_method(key, &params, &body),
        ExprKind::Ident(fn_name) if is_defined_function(__w, &fn_name) => {
            dynamic_type_forwarding_method(__w, key, &fn_name)
        }
        _ => Statement::new(StmtKind::Assign {
            targets: vec![Expression::ident(key)],
            value,
            by_ref: false,
        }),
    }
}

fn dynamic_type_note_attrs(__w: &mut PyWalker, class_name: &str, body: &[Statement]) {
    let attrs = body
        .iter()
        .filter_map(|stmt| match &stmt.kind {
            StmtKind::FunctionDecl { name, .. } => Some(name.clone()),
            StmtKind::Assign { targets, .. } => targets.first().and_then(|target| {
                if let ExprKind::Ident(name) = &target.kind {
                    Some(name.clone())
                } else {
                    None
                }
            }),
            _ => None,
        })
        .collect();
    note_class_attrs(__w, class_name, attrs);
}

fn dynamic_type_class_decl(
    __w: &mut PyWalker,
    target_name: &str,
    value: &Expression,
) -> Option<StmtKind> {
    let ExprKind::Call { callee, args, .. } = &value.kind else {
        return None;
    };
    if !matches!(&callee.kind, ExprKind::Ident(name) if name == "type") || args.len() != 3 {
        return None;
    }
    let ExprKind::Lit(Literal::Str(class_name)) = &args[0].value.kind else {
        return None;
    };
    if class_name != target_name {
        return None;
    }
    let mut body = Vec::new();
    match &args[2].value.kind {
        ExprKind::Map(entries) => {
            for (key, entry_value) in entries {
                if let Some(key) = namespace_key_name(key) {
                    body.push(dynamic_type_namespace_stmt(__w, &key, entry_value.clone()));
                }
            }
        }
        ExprKind::Object(props) => {
            for prop in props {
                if let ObjectProperty::KeyValue { key, value } = prop
                    && let Some(key) = namespace_key_name(key)
                {
                    body.push(dynamic_type_namespace_stmt(__w, &key, value.clone()));
                }
            }
        }
        _ => return None,
    }
    let parents = dynamic_type_bases(&args[1].value);
    note_defined_class(__w, target_name);
    note_class_parents(__w, target_name, &parents);
    dynamic_type_note_attrs(__w, target_name, &body);
    synthesize_python_class_defaults(__w, target_name, &mut body);
    Some(StmtKind::ClassDecl {
        name: target_name.to_string(),
        parents,
        interfaces: Vec::new(),
        members: stmts_to_class_members(__w, target_name, body),
        modifiers: ClassModifiers {
            semantics: ValueSemantics {
                equality: ValueEquality::Identity,
                ..Default::default()
            },
            ..Default::default()
        },
        decorators: vec![],
    })
}

// ── Decorated ───────────────────────────────────────────────────────────────

/// A decorator with dedicated compile-time handling (class-member kind,
/// dataclass, generator, …) rather than Python's runtime `f = deco(f)` wrapping.
/// These stay on the declaration's modifiers for the specialized paths.
fn is_special_decorator(expr: &Expression) -> bool {
    if property_accessor_decorator(expr).is_some() {
        return true;
    }
    match &expr.kind {
        ExprKind::Ident(name) => matches!(
            name.as_str(),
            "property"
                | "staticmethod"
                | "classmethod"
                | "abstractmethod"
                | "dataclass"
                | "generator"
                | "final"
                | "override"
        ),
        ExprKind::Member { field, .. } => {
            matches!(field.as_str(), "setter" | "getter" | "deleter")
        }
        _ => false,
    }
}

fn function_docstring(body: &[Statement]) -> Option<String> {
    let first = body.first()?;
    if let StmtKind::Expr(expr) = &first.kind
        && let ExprKind::Lit(Literal::Str(doc)) = &expr.kind
    {
        return Some(doc.to_string());
    }
    None
}

fn py_clean_docstring(raw: &str) -> String {
    let raw = raw.trim_matches('\n');
    let lines: Vec<&str> = raw.lines().collect();
    let indent = lines
        .iter()
        .skip(1)
        .filter_map(|line| {
            let trimmed = line.trim();
            (!trimmed.is_empty()).then(|| line.len() - line.trim_start().len())
        })
        .min()
        .unwrap_or(0);
    let mut cleaned = Vec::with_capacity(lines.len());
    for (idx, line) in lines.iter().enumerate() {
        let text = if idx == 0 {
            line.trim().to_string()
        } else if line.len() >= indent {
            line[indent..].trim_end().to_string()
        } else {
            line.trim_end().to_string()
        };
        cleaned.push(text);
    }
    while cleaned.first().is_some_and(|line| line.is_empty()) {
        cleaned.remove(0);
    }
    while cleaned.last().is_some_and(|line| line.is_empty()) {
        cleaned.pop();
    }
    cleaned.join("\n")
}

fn note_python_property_metadata(__w: &mut PyWalker, class_name: &str, stmts: &[Statement]) {
    for stmt in stmts {
        let StmtKind::FunctionDecl {
            name,
            body,
            modifiers,
            ..
        } = &stmt.kind
        else {
            continue;
        };
        if modifiers
            .decorators
            .iter()
            .any(|d| matches!(&d.kind, ExprKind::Ident(n) if n == "property"))
        {
            note_class_property_kind(__w, class_name, name, "getter");
            note_class_property_doc(__w, class_name, name, function_docstring(body));
            if property_getter_returns_float(__w, class_name, body) {
                note_class_property_returns_float(__w, class_name, name);
            }
            continue;
        }
        if let Some((prop_name, kind)) = modifiers
            .decorators
            .iter()
            .find_map(property_accessor_decorator)
        {
            note_class_property_kind(__w, class_name, &prop_name, kind);
            if matches!(kind, "getter") {
                note_class_property_doc(__w, class_name, &prop_name, function_docstring(body));
                if property_getter_returns_float(__w, class_name, body) {
                    note_class_property_returns_float(__w, class_name, &prop_name);
                }
            }
        }
    }
}

fn assign_member(object: Expression, field: &str, value: Expression) -> Statement {
    Statement::new(StmtKind::Assign {
        targets: vec![Expression::new(ExprKind::Member {
            object: Box::new(object),
            field: field.to_string(),
            null_safe: false,
        })],
        value,
        by_ref: false,
    })
}

fn function_doc_expr(body: &[Statement]) -> Expression {
    function_docstring(body)
        .map(|doc| Expression::string(&doc))
        .unwrap_or_else(|| Expression::new(ExprKind::Lit(Literal::Null)))
}

fn py_annotation_expr(type_hint: &str) -> Expression {
    match type_hint.trim() {
        "int" | "str" | "bool" | "float" | "list" | "dict" | "tuple" | "set" => {
            python_type_object_expr(type_hint.trim())
        }
        other => Expression::string(other),
    }
}

fn py_typing_generic_alias_name(name: &str) -> Option<&'static str> {
    Some(match name {
        "List" => "list",
        "Dict" => "dict",
        "Tuple" => "tuple",
        "Set" => "set",
        "FrozenSet" => "frozenset",
        _ => return None,
    })
}

fn py_typing_generic_alias_expr(name: &str, arg: Expression) -> Expression {
    let origin = py_typing_generic_alias_name(name).unwrap_or(name);
    Expression::new(ExprKind::Object(vec![
        ObjectProperty::KeyValue {
            key: Expression::string("__type"),
            value: Expression::string("GenericAlias"),
        },
        ObjectProperty::KeyValue {
            key: Expression::string("__origin__"),
            value: py_annotation_expr(origin),
        },
        ObjectProperty::KeyValue {
            key: Expression::string("__args__"),
            value: Expression::new(ExprKind::Tuple(vec![arg])),
        },
    ]))
}

fn function_annotations_expr(params: &[Param], return_type: Option<&String>) -> Option<Expression> {
    let mut props = Vec::new();
    for p in params {
        if let Some(hint) = &p.type_hint {
            props.push(ObjectProperty::KeyValue {
                key: Expression::string(&p.name),
                value: py_annotation_expr(hint),
            });
        }
    }
    if let Some(hint) = return_type {
        props.push(ObjectProperty::KeyValue {
            key: Expression::string("return"),
            value: py_annotation_expr(hint),
        });
    }
    if props.is_empty() {
        None
    } else {
        // `__annotations__` is a dict.
        Some(py_dict_expr(props))
    }
}

fn function_defaults_expr(params: &[Param], kinds: &[String]) -> Expression {
    let values: Vec<Expression> = params
        .iter()
        .enumerate()
        .filter_map(|(idx, param)| {
            let kind = py_parameter_kind_for(params, kinds, idx);
            matches!(kind.as_str(), "POSITIONAL_ONLY" | "POSITIONAL_OR_KEYWORD")
                .then(|| param.default.clone())
                .flatten()
        })
        .collect();
    if values.is_empty() {
        Expression::null()
    } else {
        Expression::new(ExprKind::Tuple(values))
    }
}

fn function_kwdefaults_expr(params: &[Param], kinds: &[String]) -> Expression {
    let props: Vec<ObjectProperty> = params
        .iter()
        .enumerate()
        .filter_map(|(idx, param)| {
            let kind = py_parameter_kind_for(params, kinds, idx);
            if kind != "KEYWORD_ONLY" {
                return None;
            }
            param.default.clone().map(|value| ObjectProperty::KeyValue {
                key: Expression::string(&param.name),
                value,
            })
        })
        .collect();
    if props.is_empty() {
        Expression::null()
    } else {
        py_dict_expr(props)
    }
}

fn function_metadata_expr(__w: &mut PyWalker, name: &str, field: &str) -> Option<Expression> {
    let params = defined_function_params(__w, name)?;
    let kinds = defined_function_param_kinds(__w, name).unwrap_or_default();
    match field {
        "__annotations__" => Some(
            function_annotations_expr(&params, defined_function_return(__w, name)?.as_ref())
                .unwrap_or_else(|| py_dict_expr(Vec::new())),
        ),
        "__defaults__" => Some(function_defaults_expr(&params, &kinds)),
        "__kwdefaults__" => Some(function_kwdefaults_expr(&params, &kinds)),
        "__name__" => Some(Expression::string(name)),
        "__qualname__" => Some(Expression::string(name)),
        _ => None,
    }
}

fn lowered_function_metadata_attr_read(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    if !matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_attr_read") || args.len() != 2
    {
        return None;
    }
    let ExprKind::Lit(Literal::Str(field)) = &args[1].value.kind else {
        return None;
    };
    if field.as_str() == "__name__"
        && let Some(type_name) = py_annotation_item_type_name(__w, &args[0].value)
    {
        return Some(Expression::string(&type_name));
    }
    let ExprKind::Ident(fn_name) = &args[0].value.kind else {
        return None;
    };
    if !matches!(
        field.as_str(),
        "__annotations__" | "__defaults__" | "__kwdefaults__" | "__name__" | "__qualname__"
    ) || !is_defined_function(__w, fn_name)
    {
        return None;
    }
    function_metadata_expr(__w, fn_name, field)
}

fn assign_function_metadata(
    out: &mut Vec<Statement>,
    fn_name: &str,
    params: &[Param],
    return_type: Option<&String>,
    body: &[Statement],
) {
    out.push(assign_member(
        Expression::ident(fn_name),
        "__name__",
        Expression::string(fn_name),
    ));
    out.push(assign_member(
        Expression::ident(fn_name),
        "__qualname__",
        Expression::string(fn_name),
    ));
    out.push(assign_member(
        Expression::ident(fn_name),
        "__doc__",
        function_doc_expr(body),
    ));
    if let Some(annotations) = function_annotations_expr(params, return_type) {
        out.push(assign_member(
            Expression::ident(fn_name),
            "__annotations__",
            annotations,
        ));
    }
}

fn attach_nested_function_metadata(owner_name: &str, body: &mut Vec<Statement>) {
    let mut rebuilt = Vec::with_capacity(body.len());
    for stmt in std::mem::take(body) {
        let (stmt, wraps_targets) = match stmt.kind {
            StmtKind::FunctionDecl {
                name,
                params,
                return_type,
                body: fn_body,
                mut modifiers,
                handles,
                is_async,
                is_generator,
                is_sub,
            } => {
                let wraps_targets: Vec<Expression> = modifiers
                    .decorators
                    .iter()
                    .filter_map(functools_wraps_target)
                    .collect();
                modifiers.decorators.retain(|d| {
                    !is_functools_identity_decorator(d) && functools_wraps_target(d).is_none()
                });
                (
                    Statement::new(StmtKind::FunctionDecl {
                        name,
                        params,
                        return_type,
                        body: fn_body,
                        modifiers,
                        handles,
                        is_async,
                        is_generator,
                        is_sub,
                    }),
                    wraps_targets,
                )
            }
            kind => (Statement::new(kind), Vec::new()),
        };
        let meta = match &stmt.kind {
            StmtKind::FunctionDecl {
                name,
                params,
                return_type,
                body: fn_body,
                ..
            } if !name.starts_with("__py_") && !name.starts_with("__vybe") => {
                let mut out = Vec::new();
                assign_function_metadata(&mut out, name, params, return_type.as_ref(), fn_body);
                out.push(assign_member(
                    Expression::ident(name),
                    "__qualname__",
                    Expression::string(&format!("{owner_name}.<locals>.{name}")),
                ));
                for wrapped in wraps_targets {
                    out.push(assign_member(
                        Expression::ident(name),
                        "__name__",
                        py_member(wrapped.clone(), "__name__"),
                    ));
                    out.push(assign_member(
                        Expression::ident(name),
                        "__qualname__",
                        py_member(wrapped.clone(), "__qualname__"),
                    ));
                    out.push(assign_member(
                        Expression::ident(name),
                        "__doc__",
                        py_member(wrapped.clone(), "__doc__"),
                    ));
                    out.push(assign_member(Expression::ident(name), "__wrapped__", wrapped));
                }
                out
            }
            _ => Vec::new(),
        };
        rebuilt.push(stmt);
        rebuilt.extend(meta);
    }
    *body = rebuilt;
}

fn call_decorator_stack(
    __w: &mut PyWalker,
    decorators: Vec<Expression>,
    base: Expression,
) -> Expression {
    let mut acc = base;
    for d in decorators.into_iter().rev() {
        acc = Expression::new(call_or_new(
            __w,
            d,
            vec![Argument {
                value: acc,
                name: None,
                by_ref: false,
                spread: false,
            }],
        ));
    }
    acc
}

fn decorator_root_ident(expr: &Expression) -> Option<&str> {
    match &expr.kind {
        ExprKind::Ident(name) => Some(name.as_str()),
        ExprKind::Call { callee, .. } => decorator_root_ident(callee),
        ExprKind::Member { object, .. } => decorator_root_ident(object),
        _ => None,
    }
}

fn is_functools_identity_decorator(expr: &Expression) -> bool {
    matches!(
        decorator_root_ident(expr),
        Some("cache" | "lru_cache" | "cached_property" | "singledispatch" | "total_ordering")
    )
}

fn functools_wraps_target(expr: &Expression) -> Option<Expression> {
    let ExprKind::Call { callee, args, .. } = &expr.kind else {
        return None;
    };
    if args.is_empty() || args[0].name.is_some() {
        return None;
    }
    match &callee.kind {
        ExprKind::Ident(name) if name == "wraps" => Some(args[0].value.clone()),
        ExprKind::Member { object, field, .. }
            if field == "wraps"
                && matches!(&object.kind, ExprKind::Ident(module) if module == "functools") =>
        {
            Some(args[0].value.clone())
        }
        _ => None,
    }
}

fn function_decl_with_decorators_and_wraps(
    decl: StmtKind,
    decorators: Vec<Expression>,
    wraps_targets: Vec<Expression>,
) -> StmtKind {
    let mut inner = decl;
    let fn_name = match &mut inner {
        StmtKind::FunctionDecl {
            name, modifiers, ..
        } => {
            modifiers.decorators = decorators;
            name.clone()
        }
        _ => return inner,
    };
    if wraps_targets.is_empty() {
        return inner;
    }
    let mut stmts = vec![Statement::new(inner)];
    for wrapped in wraps_targets {
        stmts.push(assign_member(
            Expression::ident(&fn_name),
            "__name__",
            py_member(wrapped.clone(), "__name__"),
        ));
        stmts.push(assign_member(
            Expression::ident(&fn_name),
            "__qualname__",
            py_member(wrapped.clone(), "__qualname__"),
        ));
        stmts.push(assign_member(
            Expression::ident(&fn_name),
            "__doc__",
            py_member(wrapped.clone(), "__doc__"),
        ));
        stmts.push(assign_member(
            Expression::ident(&fn_name),
            "__wrapped__",
            wrapped,
        ));
    }
    StmtKind::Block(stmts)
}

fn singledispatch_register_decorator(decorators: &[Expression]) -> Option<(String, String)> {
    if decorators.len() != 1 {
        return None;
    }
    let ExprKind::Call { callee, args, .. } = &decorators[0].kind else {
        return None;
    };
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if field != "register" || args.len() != 1 {
        return None;
    }
    let ExprKind::Ident(target) = &object.kind else {
        return None;
    };
    let ExprKind::Ident(type_name) = &args[0].value.kind else {
        return None;
    };
    Some((target.clone(), type_name.clone()))
}

fn desugar_singledispatch_registration(
    decl: StmtKind,
    target: String,
    type_name: String,
) -> StmtKind {
    let mut inner = decl;
    let impl_name = match &mut inner {
        StmtKind::FunctionDecl {
            name, modifiers, ..
        } => {
            modifiers.decorators.clear();
            name.clone()
        }
        _ => return inner,
    };
    let prev_name = format!("__py_singledispatch_prev_{target}_{impl_name}");
    let arg = Expression::ident("__py_sd_arg");
    let cond = call_ident("isinstance", vec![arg.clone(), Expression::ident(&type_name)]);
    let then_call = call_ident(&impl_name, vec![arg.clone()]);
    let else_call = call_ident(&prev_name, vec![arg.clone()]);
    let wrapper = Expression::new(ExprKind::Lambda {
        params: vec![lambda_param("__py_sd_arg")],
        body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Ternary {
            cond: Box::new(cond),
            then: Box::new(then_call),
            else_: Box::new(else_call),
        }))),
        is_async: false,
        captures: vec![],
    });
    StmtKind::Block(vec![
        Statement::new(inner),
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::ident(&prev_name)],
            value: Expression::ident(&target),
            by_ref: false,
        }),
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::ident(&target)],
            value: wrapper,
            by_ref: false,
        }),
    ])
}

fn decorator_stack_contains_class(__w: &mut PyWalker, decorators: &[Expression]) -> bool {
    decorators
        .iter()
        .filter_map(decorator_root_ident)
        .any(|__x| is_defined_class(__w, __x))
}

/// Desugar Python function decorators to runtime application:
/// `@a @b def f(...)` → `f = a(b(<function f>))`. Fires only when every
/// decorator is a general (user) decorator; if any is special the declaration
/// is returned unchanged so the specialized compile paths still see it.
fn desugar_function_decorators(
    __w: &mut PyWalker,
    decl: StmtKind,
    decorators: Vec<Expression>,
) -> StmtKind {
    if let Some((target, type_name)) = singledispatch_register_decorator(&decorators) {
        return desugar_singledispatch_registration(decl, target, type_name);
    }
    let wraps_targets: Vec<Expression> = decorators
        .iter()
        .filter_map(functools_wraps_target)
        .collect();
    let decorators: Vec<Expression> = decorators
        .into_iter()
        .filter(|d| !is_functools_identity_decorator(d) && functools_wraps_target(d).is_none())
        .collect();
    if decorators.is_empty() || decorators.iter().any(is_special_decorator) {
        return function_decl_with_decorators_and_wraps(decl, decorators, wraps_targets);
    }
    let (fn_name, params, return_type, body) = if let StmtKind::FunctionDecl {
        name,
        params,
        return_type,
        body,
        ..
    } = &decl
    {
        (
            name.clone(),
            params.clone(),
            return_type.clone(),
            body.clone(),
        )
    } else {
        return decl;
    };
    // Strip the now-runtime-applied decorators off the inner declaration so the
    // metadata pass doesn't ALSO treat them as (inert) annotations.
    let use_private_original = decorator_stack_contains_class(__w, &decorators);
    let original_name = if use_private_original {
        format!("__py_orig_{fn_name}")
    } else {
        fn_name.clone()
    };
    let mut inner = decl;
    if let StmtKind::FunctionDecl {
        name, modifiers, ..
    } = &mut inner
    {
        if use_private_original {
            *name = original_name.clone();
        }
        modifiers.decorators = Vec::new();
    }
    let mut stmts = vec![Statement::new(inner)];
    assign_function_metadata(
        &mut stmts,
        &original_name,
        &params,
        return_type.as_ref(),
        &body,
    );
    if use_private_original {
        stmts.push(assign_member(
            Expression::ident(&original_name),
            "__name__",
            Expression::string(&fn_name),
        ));
    }
    // Fold innermost-first (reversed) so `@a @b def f` becomes `a(b(f))`.
    let acc = call_decorator_stack(__w, decorators, Expression::ident(&original_name));
    stmts.push(Statement::new(StmtKind::Assign {
        targets: vec![Expression::ident(&fn_name)],
        value: acc,
        by_ref: false,
    }));
    StmtKind::Block(stmts)
}

fn class_decl_name(decl: &StmtKind) -> Option<String> {
    match decl {
        StmtKind::ClassDecl { name, .. } => Some(name.clone()),
        _ => None,
    }
}

fn desugar_class_decorators(
    __w: &mut PyWalker,
    decl: StmtKind,
    decorators: Vec<Expression>,
) -> StmtKind {
    let general: Vec<Expression> = decorators
        .into_iter()
        .filter(|d| !is_dataclass_decorator(d) && !is_functools_identity_decorator(d))
        .collect();
    if general.is_empty() {
        return decl;
    }
    let Some(name) = class_decl_name(&decl) else {
        return decl;
    };
    let value = call_decorator_stack(__w, general, Expression::ident(&name));
    StmtKind::Block(vec![
        Statement::new(decl),
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::ident(&name)],
            value,
            by_ref: false,
        }),
    ])
}

fn python_class_arg_literal(raw: &str) -> Expression {
    match raw.trim() {
        "True" => Expression::bool(true),
        "False" => Expression::bool(false),
        "None" => Expression::null(),
        s if s.starts_with('"') && s.ends_with('"') && s.len() >= 2 => {
            Expression::string(&s[1..s.len() - 1])
        }
        s if s.starts_with('\'') && s.ends_with('\'') && s.len() >= 2 => {
            Expression::string(&s[1..s.len() - 1])
        }
        s => {
            if let Ok(n) = s.parse::<i64>() {
                Expression::new(ExprKind::Lit(Literal::Int(n)))
            } else if let Ok(n) = s.parse::<f64>() {
                Expression::new(ExprKind::Lit(Literal::Float(n)))
            } else {
                Expression::ident(s)
            }
        }
    }
}

fn init_subclass_stmt(parent: &str, child: &str, kwargs: &[(String, Expression)]) -> Statement {
    let mut args = vec![Argument::positional(Expression::ident(child))];
    for (name, value) in kwargs {
        args.push(Argument {
            value: value.clone(),
            name: Some(name.clone()),
            by_ref: false,
            spread: false,
        });
    }
    Statement::new(StmtKind::Expr(Expression::new(ExprKind::Call {
        callee: Box::new(Expression::new(ExprKind::Member {
            object: Box::new(Expression::ident(parent)),
            field: "__init_subclass__".to_string(),
            null_safe: false,
        })),
        args,
        optional: false,
    })))
}

fn class_metadata_stmt(class_name: &str, field: &str, value: Expression) -> Statement {
    Statement::new(StmtKind::Assign {
        targets: vec![Expression::new(ExprKind::Member {
            object: Box::new(Expression::ident(class_name)),
            field: field.to_string(),
            null_safe: false,
        })],
        value,
        by_ref: false,
    })
}

fn rewrite_init_subclass_class_param_writes(stmts: &mut [Statement], class_param: &str) {
    for stmt in stmts {
        match &mut stmt.kind {
            StmtKind::Assign { targets, value, .. } if targets.len() == 1 => {
                let ExprKind::Member { object, field, .. } = &targets[0].kind else {
                    continue;
                };
                if matches!(&object.kind, ExprKind::Ident(name) if name == class_param) {
                    stmt.kind = StmtKind::Expr(call_ident(
                        "__py_attr_raw_write",
                        vec![
                            Expression::ident(class_param),
                            Expression::string(field),
                            value.clone(),
                        ],
                    ));
                }
            }
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                rewrite_init_subclass_class_param_writes(then_body, class_param);
                for (_, body) in elifs {
                    rewrite_init_subclass_class_param_writes(body, class_param);
                }
                if let Some(body) = else_body {
                    rewrite_init_subclass_class_param_writes(body, class_param);
                }
            }
            StmtKind::While { body, .. } | StmtKind::For { body, .. } | StmtKind::Block(body) => {
                rewrite_init_subclass_class_param_writes(body, class_param);
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                rewrite_init_subclass_class_param_writes(body, class_param);
                for catch in catches {
                    rewrite_init_subclass_class_param_writes(&mut catch.body, class_param);
                }
                if let Some(body) = else_body {
                    rewrite_init_subclass_class_param_writes(body, class_param);
                }
                if let Some(body) = finally {
                    rewrite_init_subclass_class_param_writes(body, class_param);
                }
            }
            StmtKind::FunctionDecl { .. } | StmtKind::ClassDecl { .. } => {}
            _ => {}
        }
    }
}

fn collect_init_subclass_class_param_writes(
    stmts: &[Statement],
    class_param: &str,
    out: &mut Vec<PyInitSubclassWrite>,
) {
    for stmt in stmts {
        match &stmt.kind {
            StmtKind::Assign { targets, value, .. } if targets.len() == 1 => {
                let ExprKind::Member { object, field, .. } = &targets[0].kind else {
                    continue;
                };
                if matches!(&object.kind, ExprKind::Ident(name) if name == class_param) {
                    out.push(PyInitSubclassWrite {
                        field: field.clone(),
                        value: value.clone(),
                    });
                }
            }
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                collect_init_subclass_class_param_writes(then_body, class_param, out);
                for (_, body) in elifs {
                    collect_init_subclass_class_param_writes(body, class_param, out);
                }
                if let Some(body) = else_body {
                    collect_init_subclass_class_param_writes(body, class_param, out);
                }
            }
            StmtKind::While { body, .. } | StmtKind::For { body, .. } | StmtKind::Block(body) => {
                collect_init_subclass_class_param_writes(body, class_param, out);
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                collect_init_subclass_class_param_writes(body, class_param, out);
                for catch in catches {
                    collect_init_subclass_class_param_writes(&catch.body, class_param, out);
                }
                if let Some(body) = else_body {
                    collect_init_subclass_class_param_writes(body, class_param, out);
                }
                if let Some(body) = finally {
                    collect_init_subclass_class_param_writes(body, class_param, out);
                }
            }
            StmtKind::FunctionDecl { .. } | StmtKind::ClassDecl { .. } => {}
            _ => {}
        }
    }
}

fn note_init_subclass_writes(
    __w: &mut PyWalker,
    class_name: &str,
    writes: Vec<PyInitSubclassWrite>,
) {
    if writes.is_empty() {
        return;
    }
    {
        __w.py_init_subclass_writes
            .insert(class_name.to_string(), writes);
    };
}

fn init_subclass_writes(__w: &mut PyWalker, class_name: &str) -> Vec<PyInitSubclassWrite> {
    __w.py_init_subclass_writes
        .get(class_name)
        .cloned()
        .unwrap_or_default()
}

fn substitute_init_subclass_value(
    expr: Expression,
    child: &str,
    kwargs: &[(String, Expression)],
) -> Expression {
    match expr.kind {
        ExprKind::Ident(name) if name == "cls" => Expression::ident(child),
        ExprKind::Ident(name) => kwargs
            .iter()
            .find(|(key, _)| key == &name)
            .map(|(_, value)| value.clone())
            .unwrap_or_else(|| Expression::ident(&name)),
        _ => expr,
    }
}

fn desugar_init_subclass_hooks(
    __w: &mut PyWalker,
    decl: StmtKind,
    kwargs: Vec<(String, Expression)>,
) -> StmtKind {
    let (name, parents) = match &decl {
        StmtKind::ClassDecl { name, parents, .. } => (name.clone(), parents.clone()),
        _ => return decl,
    };
    // Both stages need `&mut __w`; a filter closure holding it cannot coexist
    // with the flat_map closure, so the filter runs first into a Vec.
    let __init_parents: Vec<String> = parents
        .iter()
        .filter(|parent| class_has_attr(__w, parent, "__init_subclass__"))
        .cloned()
        .collect();
    let calls: Vec<Statement> = __init_parents
        .iter()
        .flat_map(|parent| {
            let mut out = vec![init_subclass_stmt(parent, &name, &kwargs)];
            for write in init_subclass_writes(__w, parent) {
                out.push(class_metadata_stmt(
                    &name,
                    &write.field,
                    substitute_init_subclass_value(write.value, &name, &kwargs),
                ));
            }
            out
        })
        .collect();
    if calls.is_empty() {
        return decl;
    }
    let mut stmts = vec![
        Statement::new(decl),
        class_metadata_stmt(&name, "__name__", Expression::string(&name)),
    ];
    stmts.extend(calls);
    StmtKind::Block(stmts)
}

fn descriptor_set_name_stmt(class_name: &str, field: &str) -> Statement {
    Statement::new(StmtKind::Expr(Expression::new(ExprKind::Call {
        callee: Box::new(Expression::new(ExprKind::Member {
            object: Box::new(Expression::new(ExprKind::Member {
                object: Box::new(Expression::ident(class_name)),
                field: field.to_string(),
                null_safe: false,
            })),
            field: "__set_name__".to_string(),
            null_safe: false,
        })),
        args: vec![
            Argument::positional(Expression::ident(class_name)),
            Argument::positional(Expression::string(field)),
        ],
        optional: false,
    })))
}

fn class_decl_descriptor_set_name_fields(
    __w: &mut PyWalker,
    decl: &StmtKind,
) -> Vec<(String, String)> {
    let StmtKind::ClassDecl { name, members, .. } = decl else {
        return Vec::new();
    };
    members
        .iter()
        .filter_map(|member| {
            let ClassMember::Field {
                name: field,
                init: Some(init),
                modifiers,
                ..
            } = member
            else {
                return None;
            };
            if !modifiers.is_static {
                return None;
            }
            let ExprKind::New { class, .. } = &init.kind else {
                return None;
            };
            let ExprKind::Ident(descriptor_class) = &class.kind else {
                return None;
            };
            if class_has_attr(__w, descriptor_class, "__set_name__") {
                Some((name.clone(), field.clone()))
            } else {
                None
            }
        })
        .collect()
}

fn desugar_descriptor_set_name(__w: &mut PyWalker, decl: StmtKind) -> StmtKind {
    let fields = class_decl_descriptor_set_name_fields(__w, &decl);
    if fields.is_empty() {
        return decl;
    }
    let mut stmts = vec![Statement::new(decl)];
    for (class_name, field) in fields {
        stmts.push(descriptor_set_name_stmt(&class_name, &field));
    }
    StmtKind::Block(stmts)
}

fn first_function_param_name(source: &str) -> Option<String> {
    let start = source.find('(')?;
    let end = source[start + 1..].find(')')? + start + 1;
    let param = source[start + 1..end]
        .split(',')
        .next()?
        .trim()
        .trim_start_matches('*')
        .trim();
    (!param.is_empty()).then(|| param.to_string())
}

fn patch_decorator_function_block(decl: StmtKind, mock_value: Expression) -> Option<StmtKind> {
    let StmtKind::FunctionDecl {
        name,
        params,
        return_type,
        body,
        mut modifiers,
        handles,
        is_async,
        is_generator,
        is_sub,
    } = decl
    else {
        return None;
    };
    let original_name = format!("__py_orig_{name}");
    modifiers.decorators = Vec::new();
    let original = Statement::new(StmtKind::FunctionDecl {
        name: original_name.clone(),
        params,
        return_type,
        body,
        modifiers: modifiers.clone(),
        handles,
        is_async,
        is_generator,
        is_sub,
    });
    let wrapper = Statement::new(StmtKind::FunctionDecl {
        name,
        params: Vec::new(),
        return_type: None,
        body: vec![
            Statement::new(StmtKind::Assign {
                targets: vec![Expression::ident("__py_patch_mock")],
                value: mock_value,
                by_ref: false,
            }),
            Statement::new(StmtKind::Return(Some(Expression::new(ExprKind::Call {
                callee: Box::new(Expression::ident(&original_name)),
                args: vec![Argument::positional(Expression::ident("__py_patch_mock"))],
                optional: false,
            })))),
        ],
        modifiers,
        handles: Vec::new(),
        is_async: false,
        is_generator: false,
        is_sub: false,
    });
    Some(StmtKind::Block(vec![original, wrapper]))
}

fn walk_decorated(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let mut decorators = Vec::new();
    let mut inner_pairs: Vec<Pair<Rule>> = pair.into_inner().collect();

    // Collect decorators
    let i = 0;
    while i < inner_pairs.len() {
        if inner_pairs[i].as_rule() == Rule::decorator {
            let dec_pair = inner_pairs.remove(i);
            for dp in dec_pair.into_inner() {
                if dp.as_rule() != Rule::NEWLINE {
                    decorators.push(walk_expression(__w, dp)?);
                }
            }
        } else {
            break;
        }
    }

    // Remaining should be the def/class
    if let Some(item) = inner_pairs.into_iter().next() {
        match item.as_rule() {
            Rule::function_def => {
                let first_param = first_function_param_name(item.as_str());
                let mut saved_module_patches = Vec::new();
                let mut saved_param_class = None;
                if let Some(param) = first_param.as_deref() {
                    saved_param_class = Some((param.to_string(), __w.py_instance_classes.get(param).cloned()));
                    note_instance_class(__w, param, "Mock");
                    for dec in &decorators {
                        if let Some((module, func)) = unittest_patch_module_func_target(__w, dec) {
                            let key = (module, func);
                            let old = __w
                                .py_active_mock_module_func_patches
                                .insert(key.clone(), Expression::ident(param));
                            saved_module_patches.push((key, old));
                        }
                    }
                }
                let decl = walk_func_def(__w, item, false, decorators.clone())?;
                for (key, old) in saved_module_patches {
                    if let Some(value) = old {
                        __w.py_active_mock_module_func_patches.insert(key, value);
                    } else {
                        __w.py_active_mock_module_func_patches.remove(&key);
                    }
                }
                if let Some((param, old)) = saved_param_class {
                    if let Some(class_name) = old {
                        __w.py_instance_classes.insert(param, class_name);
                    } else {
                        __w.py_instance_classes.remove(&param);
                    }
                }
                if let Some(param) = first_param.as_deref()
                    && let Some(default) = decorators
                        .iter()
                        .find(|dec| unittest_patch_module_func_target(__w, dec).is_some())
                        .and_then(|dec| unittest_patch_mock_default(__w, dec))
                    && matches!(&decl, StmtKind::FunctionDecl { params, .. }
                        if params.first().is_some_and(|p| p.name == param))
                {
                    if let Some(block) = patch_decorator_function_block(decl.clone(), default) {
                        return Ok(block);
                    }
                }
                Ok(desugar_function_decorators(__w, decl, decorators))
            }
            Rule::class_def => {
                let __d = walk_class_def(__w, item, decorators.clone())?;
                let decl = desugar_descriptor_set_name(__w, __d);
                Ok(desugar_class_decorators(__w, decl, decorators))
            }
            Rule::async_stmt => {
                // async def with decorators
                for p in item.into_inner() {
                    match p.as_rule() {
                        Rule::function_def => {
                            let decl = walk_func_def(__w, p, true, decorators.clone())?;
                            return Ok(desugar_function_decorators(__w, decl, decorators));
                        }
                        Rule::for_stmt => return walk_for(__w, p, true),
                        Rule::with_stmt => return walk_with(__w, p, true),
                        _ => {}
                    }
                }
                Err("Expected def/for/with after async".into())
            }
            other => Err(format!(
                "Expected def/class after decorator, got {:?}",
                other
            )),
        }
    } else {
        Err("Empty decorated statement".into())
    }
}

// ── Async ───────────────────────────────────────────────────────────────────

fn walk_async_stmt(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    for p in pair.into_inner() {
        match p.as_rule() {
            Rule::function_def => return walk_func_def(__w, p, true, Vec::new()),
            Rule::for_stmt => return walk_for(__w, p, true),
            Rule::with_stmt => return walk_with(__w, p, true),
            Rule::async_kw => {}
            _ => {}
        }
    }
    Err("Expected def/for/with after async".into())
}

// ── If ──────────────────────────────────────────────────────────────────────

fn walk_if(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let mut inner = pair.into_inner();
    let cond = walk_expression(__w, next_meaningful(&mut inner)?)?;
    let then_body = walk_block(__w, next_rule_any(&mut inner, &[Rule::block])?)?;

    let mut elifs = Vec::new();
    let mut else_body = None;

    for p in inner {
        match p.as_rule() {
            Rule::elif_clause => {
                let mut ei = p.into_inner();
                let econd = walk_expression(__w, next_meaningful(&mut ei)?)?;
                let ebody = walk_block(__w, next_rule_any(&mut ei, &[Rule::block])?)?;
                elifs.push((econd, ebody));
            }
            Rule::else_clause => {
                let mut ei = p.into_inner();
                else_body = Some(walk_block(__w, next_rule_any(&mut ei, &[Rule::block])?)?);
            }
            _ => {}
        }
    }

    Ok(StmtKind::If {
        cond,
        then_body,
        elifs,
        else_body,
    })
}

// ── While ───────────────────────────────────────────────────────────────────

/// Per-parse counter that keeps desugared `while…else` break-flags unique so
/// nested loops don't share (and clobber) one flag.

/// Rewrite loop-level `break` statements in `stmts` to set `flag = True` before
/// breaking, so a desugared `while…else` can distinguish a break-exit from a
/// normal exit. Recurses through non-loop containers (if/try/with/block) but NOT
/// into nested loops or function/class bodies — their `break`s target
/// themselves, not this loop.
fn mark_loop_break_sets_flag(stmts: Vec<Statement>, flag: &str) -> Vec<Statement> {
    let mut out = Vec::with_capacity(stmts.len());
    for stmt in stmts {
        match stmt.kind {
            StmtKind::Break(_) => {
                out.push(Statement::new(StmtKind::Assign {
                    targets: vec![Expression::ident(flag)],
                    value: Expression::bool(true),
                    by_ref: false,
                }));
                out.push(stmt);
            }
            StmtKind::If {
                cond,
                then_body,
                elifs,
                else_body,
            } => {
                out.push(Statement::new(StmtKind::If {
                    cond,
                    then_body: mark_loop_break_sets_flag(then_body, flag),
                    elifs: elifs
                        .into_iter()
                        .map(|(c, b)| (c, mark_loop_break_sets_flag(b, flag)))
                        .collect(),
                    else_body: else_body.map(|b| mark_loop_break_sets_flag(b, flag)),
                }));
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                out.push(Statement::new(StmtKind::Try {
                    body: mark_loop_break_sets_flag(body, flag),
                    catches: catches
                        .into_iter()
                        .map(|mut c| {
                            c.body = mark_loop_break_sets_flag(c.body, flag);
                            c
                        })
                        .collect(),
                    else_body: else_body.map(|b| mark_loop_break_sets_flag(b, flag)),
                    finally: finally.map(|b| mark_loop_break_sets_flag(b, flag)),
                }));
            }
            StmtKind::With {
                items,
                body,
                is_async,
            } => {
                out.push(Statement::new(StmtKind::With {
                    items,
                    body: mark_loop_break_sets_flag(body, flag),
                    is_async,
                }));
            }
            StmtKind::Block(b) => {
                out.push(Statement::new(StmtKind::Block(mark_loop_break_sets_flag(
                    b, flag,
                ))));
            }
            _ => out.push(stmt),
        }
    }
    out
}

fn walk_while(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let mut inner = pair.into_inner();
    let cond = walk_expression(__w, next_meaningful(&mut inner)?)?;
    let body = walk_block(__w, next_rule_any(&mut inner, &[Rule::block])?)?;
    let mut else_body = None;
    for p in inner {
        if p.as_rule() == Rule::else_clause {
            let mut ei = p.into_inner();
            else_body = Some(walk_block(__w, next_rule_any(&mut ei, &[Rule::block])?)?);
        }
    }

    let Some(else_stmts) = else_body else {
        return Ok(StmtKind::While {
            cond,
            body,
            else_body: None,
        });
    };

    // Python `while C: BODY else: ELSE` runs ELSE only on a NORMAL exit
    // (condition false), never on `break`. The shared While emitter runs
    // else_body unconditionally, so normalize into common-AST primitives that
    // route through the common loop emitter (loops.rs), the same plain-`while`
    // path every language uses:
    //   __while_else_N = False
    //   while C: BODY'                 (loop-level break → __while_else_N = True; break)
    //   if not __while_else_N: ELSE
    let n = {
        let __n = __w.while_else_counter;
        __w.while_else_counter += 1;
        __n
    };
    let flag = format!("__while_else_{n}");
    let body = mark_loop_break_sets_flag(body, &flag);
    let flag_init = Statement::new(StmtKind::Assign {
        targets: vec![Expression::ident(&flag)],
        value: Expression::bool(false),
        by_ref: false,
    });
    let while_stmt = Statement::new(StmtKind::While {
        cond,
        body,
        else_body: None,
    });
    let else_guard = Statement::new(StmtKind::If {
        cond: Expression::new(ExprKind::Unary {
            op: UnaryOp::Not,
            expr: Box::new(Expression::ident(&flag)),
        }),
        then_body: else_stmts,
        elifs: Vec::new(),
        else_body: None,
    });
    Ok(StmtKind::Block(vec![flag_init, while_stmt, else_guard]))
}

// ── For ─────────────────────────────────────────────────────────────────────

fn walk_for(__w: &mut PyWalker, pair: Pair<Rule>, is_async: bool) -> Result<StmtKind, String> {
    let inner: Vec<Pair<Rule>> = pair.into_inner().collect();

    // Find target_list, expression_list, block, else_clause
    let mut var_names: Vec<String> = Vec::new();
    let mut iter_expr = None;
    let mut body = Vec::new();
    let mut else_body = None;

    for p in inner {
        match p.as_rule() {
            Rule::target_list => {
                let text = p.as_str().trim().to_string();
                var_names = text
                    .split(',')
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty())
                    .collect();
            }
            Rule::expression_list => {
                if iter_expr.is_none() {
                    iter_expr = Some(walk_expr_list(__w, p)?);
                }
            }
            Rule::block => {
                if var_names.len() == 1
                    && let Some(iter) = iter_expr.clone()
                    && py_xml_iterable_expr(__w, &iter)
                {
                    note_xml_element_var(__w, &var_names[0]);
                }
                if var_names.len() == 1
                    && let Some(iter) = iter_expr.clone()
                    && py_re_iterable_expr(__w, &iter)
                {
                    __w.py_re_match_vars.insert(var_names[0].clone());
                }
                body = walk_block(__w, p)?;
            }
            Rule::else_clause => {
                let mut ei = p.into_inner();
                else_body = Some(walk_block(__w, next_rule_any(&mut ei, &[Rule::block])?)?);
            }
            Rule::in_kw | Rule::async_kw => {}
            _ => {}
        }
    }

    // If multiple targets (tuple unpacking: `for i, v in enumerate(...)`),
    // use a temp var and prepend destructuring assignments to the body.
    let var = if var_names.len() > 1 {
        let tmp = "__forin_element".to_string();
        let mut destructure_stmts: Vec<Statement> = Vec::new();
        for (i, name) in var_names.iter().enumerate() {
            // name = __forin_element[i]
            destructure_stmts.push(Statement::new(StmtKind::Assign {
                targets: vec![Expression::new(ExprKind::Ident(name.clone()))],
                value: Expression::new(ExprKind::Index {
                    object: Box::new(Expression::new(ExprKind::Ident(tmp.clone()))),
                    index: Box::new(Expression::new(ExprKind::Lit(Literal::Int(i as i64)))),
                    null_safe: false,
                }),
                by_ref: false,
            }));
        }
        destructure_stmts.extend(body);
        body = destructure_stmts;
        tmp
    } else {
        var_names.into_iter().next().unwrap_or_default()
    };

    let iter = iter_expr.unwrap_or(Expression::new(ExprKind::Lit(Literal::Null)));
    if let ExprKind::Ident(reader_var) = &iter.kind
        && let Some(info) = __w.py_csv_readers.get(reader_var)
        && let Some(target) = csv_line_num_append_target(&body, reader_var)
    {
        let values = (1..=info.rows.len())
            .map(|line| ArrayElement {
                key: None,
                value: Expression::int(line as i64),
                spread: false,
                by_ref: false,
            })
            .collect();
        return Ok(StmtKind::Assign {
            targets: vec![Expression::ident(&target)],
            value: Expression::new(ExprKind::Array(values)),
            by_ref: false,
        });
    }
    let iter = if let ExprKind::Ident(reader_var) = &iter.kind {
        if let Some(info) = __w.py_csv_dict_readers.get(reader_var) {
            csv_dict_reader_list_expr(info)
        } else if let Some(info) = __w.py_csv_readers.get(reader_var) {
            csv_reader_list_expr(info)
        } else {
            iter
        }
    } else {
        iter
    };
    let iter = if py_custom_iterable_expr(__w, &iter) {
        call_ident("__py_custom_iter_array", vec![iter])
    } else {
        iter
    };

    Ok(StmtKind::ForIn {
        var,
        key: None,
        iter,
        body,
        of: true,
        else_body,
        is_async,
    })
}

// ── Try ─────────────────────────────────────────────────────────────────────

fn walk_try(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let mut body = Vec::new();
    let mut catches = Vec::new();
    let mut else_body = None;
    let mut finally = None;

    for p in pair.into_inner() {
        match p.as_rule() {
            Rule::block => {
                if body.is_empty() {
                    body = walk_block(__w, p)?;
                }
            }
            Rule::except_clause => {
                let mut types = Vec::new();
                let mut var_name = None;
                let mut catch_body = Vec::new();
                for cp in p.into_inner() {
                    match cp.as_rule() {
                        Rule::block => catch_body = walk_block(__w, cp)?,
                        Rule::identifier => var_name = Some(cp.as_str().to_string()),
                        Rule::as_kw => {}
                        _ => {
                            // Exception type expression. Python allows tuple
                            // catches (`except (A, B):`); the common catch
                            // node wants one type name per entry.
                            types.extend(py_except_type_names(cp.as_str()));
                        }
                    }
                }
                if catch_body.iter().any(py_stmt_is_bare_raise) {
                    let rethrow_var = var_name
                        .clone()
                        .unwrap_or_else(|| "__py_current_exception".to_string());
                    py_rewrite_bare_raises(&mut catch_body, &rethrow_var);
                    var_name = Some(rethrow_var);
                }
                let current_var = var_name
                    .clone()
                    .unwrap_or_else(|| "__py_current_exception".to_string());
                py_expand_except_exc_info_assigns(&mut catch_body, &current_var);
                py_rewrite_except_exc_info(&mut catch_body, &current_var);
                py_stamp_except_raise_contexts(&mut catch_body, &current_var);
                if var_name.is_none() {
                    var_name = Some(current_var);
                }
                catches.push(CatchClause {
                    types,
                    var_name,
                    stack_var: None,
                    body: catch_body,
                    when_clause: None,
                });
            }
            Rule::else_clause => {
                let mut ei = p.into_inner();
                else_body = Some(walk_block(__w, next_rule_any(&mut ei, &[Rule::block])?)?);
            }
            Rule::finally_clause => {
                for fp in p.into_inner() {
                    if fp.as_rule() == Rule::block {
                        finally = Some(walk_block(__w, fp)?);
                    }
                }
            }
            _ => {}
        }
    }

    let has_later_base_exception = |idx: usize, catches: &[CatchClause]| {
        catches
            .iter()
            .skip(idx + 1)
            .any(|catch| catch.types.iter().any(|ty| ty == "BaseException"))
    };
    for idx in 0..catches.len() {
        if has_later_base_exception(idx, &catches)
            && catches[idx].types.iter().any(|ty| ty == "Exception")
        {
            catches[idx].types.retain(|ty| ty != "Exception");
        }
    }

    Ok(StmtKind::Try {
        body,
        catches,
        else_body,
        finally,
    })
}

fn py_except_type_names(raw: &str) -> Vec<String> {
    let text = raw.trim();
    let inner = text
        .strip_prefix('(')
        .and_then(|s| s.strip_suffix(')'))
        .unwrap_or(text);
    let mut out = Vec::new();
    for name in inner.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if name == "ET.ParseError" || name.ends_with(".ElementTree.ParseError") {
            out.push("Exception".to_string());
            continue;
        }
        // `except graphlib.CycleError:` — a DOTTED name is module surface, and
        // the module surface is what `tree_register` mounts into the shared
        // dotted resolver. Reducing it only when the leaf is a BUILTIN left
        // every declared exception unmatchable: the clause kept the text
        // `graphlib.CycleError` while the raised object was `CycleError`.
        let normalized = match name.split_once('.') {
            Some((module, leaf)) if crate::core_classes::module_member(module, leaf).is_some() => {
                crate::core_classes::module_member(module, leaf).unwrap()
            }
            _ => name
                .rsplit('.')
                .next()
                .filter(|leaf| py_builtin_exception_bases(leaf).is_some())
                .unwrap_or(name),
        };
        out.push(normalized.to_string());
        if normalized == "GetoptError" && !out.iter().any(|existing| existing == "Exception") {
            out.push("Exception".to_string());
        }
        if py_builtin_exception_bases(normalized).is_some() {
            for candidate in py_builtin_exception_names() {
                if *candidate != normalized
                    && py_builtin_subclass(candidate, normalized) == Some(true)
                    && !out.iter().any(|existing| existing == candidate)
                {
                    out.push((*candidate).to_string());
                }
            }
        }
    }
    out
}

fn py_stmt_is_bare_raise(stmt: &Statement) -> bool {
    matches!(stmt.kind, StmtKind::Throw { expr: None, .. })
}

fn py_rewrite_bare_raises(body: &mut [Statement], var_name: &str) {
    for stmt in body {
        if let StmtKind::Throw { expr, .. } = &mut stmt.kind
            && expr.is_none()
        {
            *expr = Some(Expression::ident(var_name));
        }
    }
}

fn py_is_ident(expr: &Expression, name: &str) -> bool {
    matches!(&expr.kind, ExprKind::Ident(n) if n == name)
}

fn py_exception_chain_stmts(
    exc: Expression,
    cause: Expression,
    context: Expression,
    suppress: bool,
) -> Vec<Statement> {
    let tmp = "__py_pending_exception";
    vec![
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::ident(tmp)],
            value: exc,
            by_ref: false,
        }),
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::new(ExprKind::Member {
                object: Box::new(Expression::ident(tmp)),
                field: "__cause__".into(),
                null_safe: false,
            })],
            value: cause,
            by_ref: false,
        }),
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::new(ExprKind::Member {
                object: Box::new(Expression::ident(tmp)),
                field: "__context__".into(),
                null_safe: false,
            })],
            value: context,
            by_ref: false,
        }),
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::new(ExprKind::Member {
                object: Box::new(Expression::ident(tmp)),
                field: "__suppress_context__".into(),
                null_safe: false,
            })],
            value: Expression::bool(suppress),
            by_ref: false,
        }),
        Statement::new(StmtKind::Throw {
            expr: Some(Expression::ident(tmp)),
            cause: None,
        }),
    ]
}

fn py_stamp_except_raise_contexts(body: &mut Vec<Statement>, current_var: &str) {
    let mut rewritten = Vec::with_capacity(body.len());
    for mut stmt in body.drain(..) {
        let replacement = match &mut stmt.kind {
            StmtKind::Expr(Expression {
                kind: ExprKind::Call { callee, args, .. },
                ..
            }) => {
                if let ExprKind::Ident(name) = &callee.kind
                    && let Some(exc_name) = name.strip_prefix("__py_raise_")
                {
                    let exc = call_ident(
                        &format!("__py_exc_{exc_name}"),
                        args.iter().map(|a| a.value.clone()).collect(),
                    );
                    Some(py_exception_chain_stmts(
                        exc,
                        Expression::new(ExprKind::Lit(Literal::Null)),
                        Expression::ident(current_var),
                        false,
                    ))
                } else {
                    None
                }
            }
            StmtKind::Throw { expr, cause } => {
                if let Some(exc) = expr.take() {
                    if py_is_ident(&exc, current_var) && cause.is_none() {
                        *expr = Some(exc);
                        None
                    } else {
                        let (cause_expr, suppress) = if let Some(cause) = cause.take() {
                            (cause, true)
                        } else {
                            (Expression::new(ExprKind::Lit(Literal::Null)), false)
                        };
                        Some(py_exception_chain_stmts(
                            exc,
                            cause_expr,
                            Expression::ident(current_var),
                            suppress,
                        ))
                    }
                } else {
                    None
                }
            }
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                py_stamp_except_raise_contexts(then_body, current_var);
                for (_, body) in elifs {
                    py_stamp_except_raise_contexts(body, current_var);
                }
                if let Some(body) = else_body {
                    py_stamp_except_raise_contexts(body, current_var);
                }
                None
            }
            StmtKind::Block(stmts) => {
                py_stamp_except_raise_contexts(stmts, current_var);
                None
            }
            StmtKind::While {
                body, else_body, ..
            }
            | StmtKind::ForIn {
                body, else_body, ..
            } => {
                py_stamp_except_raise_contexts(body, current_var);
                if let Some(body) = else_body {
                    py_stamp_except_raise_contexts(body, current_var);
                }
                None
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                py_stamp_except_raise_contexts(body, current_var);
                for catch in catches {
                    py_stamp_except_raise_contexts(&mut catch.body, current_var);
                }
                if let Some(body) = else_body {
                    py_stamp_except_raise_contexts(body, current_var);
                }
                if let Some(body) = finally {
                    py_stamp_except_raise_contexts(body, current_var);
                }
                None
            }
            _ => None,
        };
        if let Some(stmts) = replacement {
            rewritten.extend(stmts);
        } else {
            rewritten.push(stmt);
        }
    }
    *body = rewritten;
}

fn py_rewrite_except_exc_info(body: &mut [Statement], current_var: &str) {
    for stmt in body {
        match &mut stmt.kind {
            StmtKind::Expr(expr) | StmtKind::Return(Some(expr)) => {
                py_rewrite_except_exc_info_expr(expr, current_var)
            }
            StmtKind::Assign { targets, value, .. } => {
                for target in targets {
                    py_rewrite_except_exc_info_expr(target, current_var);
                }
                py_rewrite_except_exc_info_expr(value, current_var);
            }
            StmtKind::VarDecl { declarations, .. } => {
                for decl in declarations {
                    if let Some(init) = &mut decl.init {
                        py_rewrite_except_exc_info_expr(init, current_var);
                    }
                }
            }
            StmtKind::If {
                cond,
                then_body,
                elifs,
                else_body,
            } => {
                py_rewrite_except_exc_info_expr(cond, current_var);
                py_rewrite_except_exc_info(then_body, current_var);
                for (cond, body) in elifs {
                    py_rewrite_except_exc_info_expr(cond, current_var);
                    py_rewrite_except_exc_info(body, current_var);
                }
                if let Some(body) = else_body {
                    py_rewrite_except_exc_info(body, current_var);
                }
            }
            StmtKind::While {
                cond,
                body,
                else_body,
            } => {
                py_rewrite_except_exc_info_expr(cond, current_var);
                py_rewrite_except_exc_info(body, current_var);
                if let Some(body) = else_body {
                    py_rewrite_except_exc_info(body, current_var);
                }
            }
            StmtKind::ForIn {
                iter,
                body,
                else_body,
                ..
            } => {
                py_rewrite_except_exc_info_expr(iter, current_var);
                py_rewrite_except_exc_info(body, current_var);
                if let Some(body) = else_body {
                    py_rewrite_except_exc_info(body, current_var);
                }
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                py_rewrite_except_exc_info(body, current_var);
                for catch in catches {
                    let nested = catch.var_name.as_deref().unwrap_or(current_var);
                    py_rewrite_except_exc_info(&mut catch.body, nested);
                }
                if let Some(body) = else_body {
                    py_rewrite_except_exc_info(body, current_var);
                }
                if let Some(body) = finally {
                    py_rewrite_except_exc_info(body, current_var);
                }
            }
            StmtKind::Throw { expr, cause } => {
                if let Some(expr) = expr {
                    py_rewrite_except_exc_info_expr(expr, current_var);
                }
                if let Some(cause) = cause {
                    py_rewrite_except_exc_info_expr(cause, current_var);
                }
            }
            _ => {}
        }
    }
}

fn py_expand_except_exc_info_assigns(body: &mut Vec<Statement>, current_var: &str) {
    let mut rewritten = Vec::with_capacity(body.len());
    for mut stmt in body.drain(..) {
        if let StmtKind::Assign { targets, value, .. } = &stmt.kind
            && targets.len() == 1
            && py_is_sys_exc_info_call(value)
            && let Some(names) = py_destructure_idents(&targets[0])
            && names.len() >= 3
        {
            rewritten.push(Statement::new(StmtKind::Assign {
                targets: vec![Expression::ident(&names[0])],
                value: Expression::new(ExprKind::Object(vec![ObjectProperty::KeyValue {
                    key: Expression::string("__name__"),
                    value: call_ident("__py_type_name", vec![Expression::ident(current_var)]),
                }])),
                by_ref: false,
            }));
            rewritten.push(Statement::new(StmtKind::Assign {
                targets: vec![Expression::ident(&names[1])],
                value: Expression::ident(current_var),
                by_ref: false,
            }));
            rewritten.push(Statement::new(StmtKind::Assign {
                targets: vec![Expression::ident(&names[2])],
                value: Expression::new(ExprKind::Object(vec![ObjectProperty::KeyValue {
                    key: Expression::string("exception"),
                    value: Expression::ident(current_var),
                }])),
                by_ref: false,
            }));
            continue;
        }
        match &mut stmt.kind {
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                py_expand_except_exc_info_assigns(then_body, current_var);
                for (_, body) in elifs {
                    py_expand_except_exc_info_assigns(body, current_var);
                }
                if let Some(body) = else_body {
                    py_expand_except_exc_info_assigns(body, current_var);
                }
            }
            StmtKind::Block(stmts) => py_expand_except_exc_info_assigns(stmts, current_var),
            StmtKind::While {
                body, else_body, ..
            }
            | StmtKind::ForIn {
                body, else_body, ..
            } => {
                py_expand_except_exc_info_assigns(body, current_var);
                if let Some(body) = else_body {
                    py_expand_except_exc_info_assigns(body, current_var);
                }
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                py_expand_except_exc_info_assigns(body, current_var);
                for catch in catches {
                    let nested = catch.var_name.as_deref().unwrap_or(current_var);
                    py_expand_except_exc_info_assigns(&mut catch.body, nested);
                }
                if let Some(body) = else_body {
                    py_expand_except_exc_info_assigns(body, current_var);
                }
                if let Some(body) = finally {
                    py_expand_except_exc_info_assigns(body, current_var);
                }
            }
            _ => {}
        }
        rewritten.push(stmt);
    }
    *body = rewritten;
}

fn py_is_sys_exc_info_call(expr: &Expression) -> bool {
    matches!(
        &expr.kind,
        ExprKind::Call { callee, args, .. }
            if args.is_empty()
                && py_is_sys_exc_info_callee(callee)
    )
}

fn py_is_sys_exc_info_callee(callee: &Expression) -> bool {
    match &callee.kind {
        ExprKind::Ident(name) => name == "sys.exc_info",
        ExprKind::Member { object, field, .. } => {
            field == "exc_info" && matches!(&object.kind, ExprKind::Ident(name) if name == "sys")
        }
        _ => false,
    }
}

fn py_destructure_idents(expr: &Expression) -> Option<Vec<String>> {
    let ExprKind::Destructure(DestructurePattern::Array(elems)) = &expr.kind else {
        return None;
    };
    let mut names = Vec::new();
    for elem in elems {
        let ArrayPatternElem::Pattern(BindingPattern::Ident(name), None) = elem else {
            return None;
        };
        names.push(name.clone());
    }
    Some(names)
}

fn py_rewrite_except_exc_info_expr(expr: &mut Expression, current_var: &str) {
    match &mut expr.kind {
        ExprKind::Index { object, index, .. }
            if py_is_sys_exc_info_call(object)
                && matches!(&index.kind, ExprKind::Lit(Literal::Int(0 | 1 | 2))) =>
        {
            let ExprKind::Lit(Literal::Int(which)) = index.kind else {
                return;
            };
            expr.kind = match which {
                0 => ExprKind::Object(vec![ObjectProperty::KeyValue {
                    key: Expression::string("__name__"),
                    value: call_ident("__py_type_name", vec![Expression::ident(current_var)]),
                }]),
                1 => ExprKind::Ident(current_var.to_string()),
                _ => ExprKind::Object(vec![ObjectProperty::KeyValue {
                    key: Expression::string("exception"),
                    value: Expression::ident(current_var),
                }]),
            };
        }
        ExprKind::Call { callee, args, .. } => {
            if args.is_empty()
                && let ExprKind::Member { object, field, .. } = &callee.kind
                && field == "exception"
                && matches!(&object.kind, ExprKind::Ident(name) if name == "sys")
            {
                expr.kind = ExprKind::Ident(current_var.to_string());
                return;
            }
            if args.is_empty() && py_is_sys_exc_info_callee(callee) {
                expr.kind = ExprKind::Array(vec![
                    ArrayElement {
                        key: None,
                        value: Expression::new(ExprKind::Object(vec![ObjectProperty::KeyValue {
                            key: Expression::string("__name__"),
                            value: call_ident(
                                "__py_type_name",
                                vec![Expression::ident(current_var)],
                            ),
                        }])),
                        spread: false,
                        by_ref: false,
                    },
                    ArrayElement {
                        key: None,
                        value: Expression::ident(current_var),
                        spread: false,
                        by_ref: false,
                    },
                    ArrayElement {
                        key: None,
                        value: Expression::new(ExprKind::Object(vec![ObjectProperty::KeyValue {
                            key: Expression::string("exception"),
                            value: Expression::ident(current_var),
                        }])),
                        spread: false,
                        by_ref: false,
                    },
                ]);
                return;
            }
            py_rewrite_except_exc_info_expr(callee, current_var);
            for arg in args {
                py_rewrite_except_exc_info_expr(&mut arg.value, current_var);
            }
        }
        ExprKind::Member { object, .. } => py_rewrite_except_exc_info_expr(object, current_var),
        ExprKind::Index { object, index, .. } => {
            py_rewrite_except_exc_info_expr(object, current_var);
            py_rewrite_except_exc_info_expr(index, current_var);
        }
        ExprKind::Binary { left, right, .. } => {
            py_rewrite_except_exc_info_expr(left, current_var);
            py_rewrite_except_exc_info_expr(right, current_var);
        }
        ExprKind::Unary { expr, .. } => py_rewrite_except_exc_info_expr(expr, current_var),
        ExprKind::Ternary { cond, then, else_ } => {
            py_rewrite_except_exc_info_expr(cond, current_var);
            py_rewrite_except_exc_info_expr(then, current_var);
            py_rewrite_except_exc_info_expr(else_, current_var);
        }
        ExprKind::Array(items) => {
            for item in items {
                if let Some(key) = &mut item.key {
                    py_rewrite_except_exc_info_expr(key, current_var);
                }
                py_rewrite_except_exc_info_expr(&mut item.value, current_var);
            }
        }
        ExprKind::Tuple(items) => {
            for item in items {
                py_rewrite_except_exc_info_expr(item, current_var);
            }
        }
        ExprKind::Object(props) => {
            for prop in props {
                match prop {
                    ObjectProperty::KeyValue { key, value }
                    | ObjectProperty::Computed { key, value } => {
                        py_rewrite_except_exc_info_expr(key, current_var);
                        py_rewrite_except_exc_info_expr(value, current_var);
                    }
                    ObjectProperty::Spread(value) => {
                        py_rewrite_except_exc_info_expr(value, current_var);
                    }
                    _ => {}
                }
            }
        }
        _ => {}
    }
}

// ── With ────────────────────────────────────────────────────────────────────

fn walk_with(__w: &mut PyWalker, pair: Pair<Rule>, is_async: bool) -> Result<StmtKind, String> {
    let mut items = Vec::new();
    let mut body = Vec::new();

    for p in pair.into_inner() {
        match p.as_rule() {
            Rule::with_item => {
                let mut expr = None;
                let mut var = None;
                for wp in p.into_inner() {
                    match wp.as_rule() {
                        Rule::as_kw => {}
                        Rule::target | Rule::target_list => {
                            var = Some(wp.as_str().trim().to_string())
                        }
                        _ => {
                            if expr.is_none() {
                                expr = Some(walk_expression(__w, wp)?);
                            }
                        }
                    }
                }
                items.push(WithItem {
                    expr: expr.unwrap_or(Expression::new(ExprKind::Lit(Literal::Null))),
                    var,
                });
            }
            Rule::block => {
                let saved_platform = __w.py_sys_platform_override.clone();
                let added_attr_patches: Vec<(String, String)> = items
                    .iter()
                    .filter_map(|item| unittest_patch_object_target(__w, &item.expr))
                    .collect();
                let added_property_patches: Vec<((String, String), Expression)> = items
                    .iter()
                    .filter_map(|item| {
                        let (target, field) = unittest_patch_object_target(__w, &item.expr)?;
                        if !is_defined_class(__w, &target) || !class_has_property(__w, &target, &field) {
                            return None;
                        }
                        let var = item.var.as_ref()?;
                        Some(((target, field), Expression::ident(var)))
                    })
                    .collect();
                if let Some(value) = items
                    .iter()
                    .find_map(|item| unittest_patch_sys_platform_value(__w, &item.expr))
                {
                    __w.py_sys_platform_override = Some(value);
                }
                for patch in &added_attr_patches {
                    __w.py_active_mock_attr_patches.insert(patch.clone());
                }
                for (patch, replacement) in &added_property_patches {
                    __w.py_active_mock_property_patches
                        .insert(patch.clone(), replacement.clone());
                }
                body = walk_block(__w, p)?;
                __w.py_sys_platform_override = saved_platform;
                for patch in added_attr_patches {
                    __w.py_active_mock_attr_patches.remove(&patch);
                }
                for (patch, _) in added_property_patches {
                    __w.py_active_mock_property_patches.remove(&patch);
                }
            }
            _ => {}
        }
    }

    // Desugar `with` to the PEP-343 try/except/finally so the standard Try
    // compilation drives the context-manager protocol — reusing errors.rs's
    // try_table AND the finally machinery that already runs on break/continue/
    // return/exception paths (a hand-rolled try_table hangs on break/nested).
    let _ = is_async;
    if items.is_empty() {
        return Ok(StmtKind::Block(body));
    }
    Ok(StmtKind::Block(build_with_desugar(__w, &items, body)))
}

fn with_stmt(kind: StmtKind) -> Statement {
    Statement::new(kind)
}
fn with_member(recv: &str, field: &str) -> Expression {
    Expression::new(ExprKind::Member {
        object: Box::new(Expression::ident(recv)),
        field: field.to_string(),
        null_safe: false,
    })
}
fn with_arg(value: Expression) -> Argument {
    Argument {
        value,
        name: None,
        by_ref: false,
        spread: false,
    }
}
fn with_call(callee: Expression, args: Vec<Argument>) -> Expression {
    Expression::new(ExprKind::Call {
        callee: Box::new(callee),
        args,
        optional: false,
    })
}
fn with_not(e: Expression) -> Expression {
    Expression::new(ExprKind::Unary {
        op: UnaryOp::Not,
        expr: Box::new(e),
    })
}

/// `with A as a, B as b: body` → nested PEP-343 blocks:
/// ```text
/// __mgr = A; a = __mgr.__enter__(); __hit = False
/// try: <inner>
/// except as __e: __hit = True; if not __mgr.__exit__(__e, __e, None): raise
/// finally: if not __hit: __mgr.__exit__(None, None, None)
/// ```
/// `with conn:` for a tracked sqlite3 connection → transaction:
/// `__sql_begin`; on normal exit `__sql_commit`; on exception `__sql_rollback`
/// then re-raise (sqlite3 does NOT suppress the exception).
fn build_sql_with_desugar(__w: &mut PyWalker, conn: &str, body: Vec<Statement>) -> Vec<Statement> {
    let n = {
        let __n = __w.with_counter;
        __w.with_counter += 1;
        __n
    };
    let hit = format!("__sql_hit_{n}");
    let exc = format!("__sql_exc_{n}");

    let sql_call = |name: &str| {
        with_stmt(StmtKind::Expr(with_call(
            Expression::ident(name),
            vec![with_arg(Expression::ident(conn))],
        )))
    };

    let catch = CatchClause {
        types: vec![],
        var_name: Some(exc.clone()),
        stack_var: None,
        body: vec![
            with_stmt(StmtKind::Assign {
                targets: vec![Expression::ident(&hit)],
                value: Expression::bool(true),
                by_ref: false,
            }),
            sql_call("__sql_rollback"),
            with_stmt(StmtKind::Throw {
                expr: Some(Expression::ident(&exc)),
                cause: None,
            }),
        ],
        when_clause: None,
    };

    let finally = vec![with_stmt(StmtKind::If {
        cond: with_not(Expression::ident(&hit)),
        then_body: vec![sql_call("__sql_commit")],
        elifs: vec![],
        else_body: None,
    })];

    vec![
        sql_call("__sql_begin"),
        with_stmt(StmtKind::Assign {
            targets: vec![Expression::ident(&hit)],
            value: Expression::bool(false),
            by_ref: false,
        }),
        with_stmt(StmtKind::Try {
            body,
            catches: vec![catch],
            else_body: None,
            finally: Some(finally),
        }),
    ]
}

/// `with open(...) as f: BODY` → `f = open(...)` + `try: BODY finally: f.close()`.
fn build_file_with_desugar(
    __w: &mut PyWalker,
    item: &WithItem,
    body: Vec<Statement>,
    closes: bool,
    close_via_method: bool,
) -> Vec<Statement> {
    let n = {
        let __n = __w.with_counter;
        __w.with_counter += 1;
        __n
    };
    let target = item
        .var
        .clone()
        .unwrap_or_else(|| format!("__with_file_{n}"));
    let mut body = body;
    normalize_file_context_body(&mut body, &target);
    let mut value = desugar_member_reads(__w, item.expr.clone());
    normalize_named_tempfile_new_args(__w, &mut value);
    vec![
        with_stmt(StmtKind::Assign {
            targets: vec![Expression::ident(&target)],
            value,
            by_ref: false,
        }),
        with_stmt(StmtKind::Try {
            body,
            catches: vec![],
            else_body: None,
            finally: Some(if closes {
                let close_expr = if close_via_method {
                    call_member_ident(&target, "close", vec![])
                } else {
                    call_ident("__py_file_close", vec![Expression::ident(&target)])
                };
                vec![with_stmt(StmtKind::Expr(close_expr))]
            } else {
                vec![]
            }),
        }),
    ]
}

fn call_member_ident(receiver: &str, field: &str, args: Vec<Expression>) -> Expression {
    Expression::new(ExprKind::Call {
        callee: Box::new(Expression::new(ExprKind::Member {
            object: Box::new(Expression::ident(receiver)),
            field: field.to_string(),
            null_safe: false,
        })),
        args: args.into_iter().map(Argument::positional).collect(),
        optional: false,
    })
}

fn normalized_named_tempfile_args(__w: &mut PyWalker, args: &[Argument]) -> Vec<Argument> {
    let defaults = [
        ("mode", Expression::string("w+b")),
        ("buffering", Expression::int(-1)),
        ("encoding", Expression::null()),
        ("newline", Expression::null()),
        ("suffix", Expression::string("")),
        ("prefix", Expression::string("")),
        ("dir", Expression::string("")),
        ("delete", Expression::bool(true)),
    ];
    defaults
        .iter()
        .enumerate()
        .map(|(index, (name, default))| {
            args.iter()
                .filter(|a| a.name.is_none())
                .nth(index)
                .or_else(|| args.iter().find(|a| a.name.as_deref() == Some(*name)))
                .map(|a| Argument::positional(desugar_member_reads(__w, a.value.clone())))
                .unwrap_or_else(|| Argument::positional(default.clone()))
        })
        .collect()
}

fn normalize_named_tempfile_new_args(__w: &mut PyWalker, expr: &mut Expression) {
    if let ExprKind::New { class, args } = &mut expr.kind
        && matches!(&class.kind, ExprKind::Ident(name) if name == "__PyNamedTempFile")
        && args.iter().any(|arg| arg.name.is_some())
    {
        *args = normalized_named_tempfile_args(__w, args);
    }
}

fn normalize_file_context_body(body: &mut [Statement], target: &str) {
    for stmt in body {
        normalize_file_context_stmt(stmt, target);
    }
}

fn normalize_file_context_stmt(stmt: &mut Statement, target: &str) {
    match &mut stmt.kind {
        StmtKind::Expr(expr) | StmtKind::Return(Some(expr)) | StmtKind::Throw { expr: Some(expr), .. } => {
            normalize_file_context_expr(expr, target);
        }
        StmtKind::Assign { targets, value, .. } => {
            for target_expr in targets {
                normalize_file_context_expr(target_expr, target);
            }
            normalize_file_context_expr(value, target);
        }
        StmtKind::VarDecl { declarations, .. } => {
            for decl in declarations {
                if let Some(init) = &mut decl.init {
                    normalize_file_context_expr(init, target);
                }
            }
        }
        StmtKind::If {
            cond,
            then_body,
            elifs,
            else_body,
        } => {
            normalize_file_context_expr(cond, target);
            normalize_file_context_body(then_body, target);
            for (elif_cond, elif_body) in elifs {
                normalize_file_context_expr(elif_cond, target);
                normalize_file_context_body(elif_body, target);
            }
            if let Some(else_body) = else_body {
                normalize_file_context_body(else_body, target);
            }
        }
        StmtKind::While { cond, body, .. } => {
            normalize_file_context_expr(cond, target);
            normalize_file_context_body(body, target);
        }
        StmtKind::For {
            init,
            cond,
            update,
            body,
        } => {
            if let Some(init) = init {
                normalize_file_context_stmt(init, target);
            }
            if let Some(cond) = cond {
                normalize_file_context_expr(cond, target);
            }
            if let Some(update) = update {
                normalize_file_context_expr(update, target);
            }
            normalize_file_context_body(body, target);
        }
        StmtKind::ForIn { iter, body, .. } => {
            normalize_file_context_expr(iter, target);
            normalize_file_context_body(body, target);
        }
        StmtKind::Try {
            body,
            catches,
            else_body,
            finally,
        } => {
            normalize_file_context_body(body, target);
            for catch in catches {
                normalize_file_context_body(&mut catch.body, target);
                if let Some(when_clause) = &mut catch.when_clause {
                    normalize_file_context_expr(when_clause, target);
                }
            }
            if let Some(else_body) = else_body {
                normalize_file_context_body(else_body, target);
            }
            if let Some(finally) = finally {
                normalize_file_context_body(finally, target);
            }
        }
        StmtKind::Block(body) | StmtKind::NamespaceDecl { body, .. } => {
            normalize_file_context_body(body, target);
        }
        StmtKind::With { items, body, .. } => {
            for item in items {
                normalize_file_context_expr(&mut item.expr, target);
            }
            normalize_file_context_body(body, target);
        }
        StmtKind::Echo(parts) => {
            for expr in parts {
                normalize_file_context_expr(expr, target);
            }
        }
        StmtKind::CompoundAssign { target: lhs, value, .. } => {
            normalize_file_context_expr(lhs, target);
            normalize_file_context_expr(value, target);
        }
        StmtKind::Return(None)
        | StmtKind::Throw { expr: None, .. }
        | StmtKind::Break(_)
        | StmtKind::Continue(_)
        | StmtKind::Empty
        | StmtKind::ClassDecl { .. }
        | StmtKind::FunctionDecl { .. }
        | StmtKind::ScopeDecl { .. } => {}
        _ => {}
    }
}

fn normalize_file_context_expr(expr: &mut Expression, target: &str) {
    if let Some(field) = file_context_bound_data_attr(expr, target) {
        *expr = Expression::new(ExprKind::Member {
            object: Box::new(Expression::ident(target)),
            field,
            null_safe: false,
        });
        return;
    }
    match &mut expr.kind {
        ExprKind::Call { callee, args, .. } => {
            normalize_file_context_expr(callee, target);
            for arg in args.iter_mut() {
                normalize_file_context_expr(&mut arg.value, target);
            }
            let helper = match &callee.kind {
                ExprKind::Member { object, field, .. }
                    if matches!(&object.kind, ExprKind::Ident(name) if name == target) =>
                {
                    match field.as_str() {
                        "read" => Some("__py_file_read"),
                        "write" => Some("__py_file_write"),
                        "readline" => Some("__py_file_readline"),
                        "writelines" => Some("__py_file_writelines"),
                        "seek" => Some("__py_file_seek"),
                        "tell" => Some("__py_file_tell"),
                        "readlines" => Some("__py_file_readlines"),
                        "close" => Some("__py_file_close"),
                        _ => None,
                    }
                }
                _ => None,
            };
            if let Some(helper) = helper {
                let mut fixed = vec![Argument::positional(Expression::ident(target))];
                fixed.extend(args.iter().cloned());
                *expr = Expression::new(ExprKind::Call {
                    callee: Box::new(Expression::ident(helper)),
                    args: fixed,
                    optional: false,
                });
            }
        }
        ExprKind::Member { object, .. } => normalize_file_context_expr(object, target),
        ExprKind::Index { object, index, .. } => {
            normalize_file_context_expr(object, target);
            normalize_file_context_expr(index, target);
        }
        ExprKind::Binary { left, right, .. } => {
            normalize_file_context_expr(left, target);
            normalize_file_context_expr(right, target);
        }
        ExprKind::Unary { expr, .. } => normalize_file_context_expr(expr, target),
        ExprKind::Ternary { cond, then, else_ } => {
            normalize_file_context_expr(cond, target);
            normalize_file_context_expr(then, target);
            normalize_file_context_expr(else_, target);
        }
        ExprKind::Array(items) => {
            for item in items {
                normalize_file_context_expr(&mut item.value, target);
                if let Some(key) = &mut item.key {
                    normalize_file_context_expr(key, target);
                }
            }
        }
        ExprKind::Tuple(items) | ExprKind::Sequence(items) => {
            for item in items {
                normalize_file_context_expr(item, target);
            }
        }
        ExprKind::Map(entries) => {
            for (key, value) in entries {
                normalize_file_context_expr(key, target);
                normalize_file_context_expr(value, target);
            }
        }
        ExprKind::Object(props) => {
            for prop in props {
                if let ObjectProperty::KeyValue { key, value } = prop {
                    normalize_file_context_expr(key, target);
                    normalize_file_context_expr(value, target);
                }
            }
        }
        ExprKind::Lambda { body, .. } => match body {
            LambdaBody::Expr(value) => normalize_file_context_expr(value, target),
            LambdaBody::Block(stmts) => normalize_file_context_body(stmts, target),
        },
        ExprKind::New { class, args } => {
            normalize_file_context_expr(class, target);
            for arg in args {
                normalize_file_context_expr(&mut arg.value, target);
            }
        }
        ExprKind::Await(inner)
        | ExprKind::Yield(Some(inner))
        | ExprKind::YieldFrom(inner)
        | ExprKind::Spread(inner)
        | ExprKind::Void(inner)
        | ExprKind::Delete(inner) => normalize_file_context_expr(inner, target),
        ExprKind::Yield(None)
        | ExprKind::Ident(_)
        | ExprKind::Lit(_)
        | ExprKind::Super
        | ExprKind::This
        | ExprKind::GlobalNamespace => {}
        _ => {}
    }
}

fn file_context_bound_data_attr(expr: &Expression, target: &str) -> Option<String> {
    let ExprKind::Lambda { params, body, .. } = &expr.kind else {
        return None;
    };
    if params.len() != 1 || !params[0].is_rest || params[0].name != "__py_bound_args" {
        return None;
    }
    let LambdaBody::Expr(body) = body else {
        return None;
    };
    let ExprKind::Call { callee, args, .. } = &body.kind else {
        return None;
    };
    let ExprKind::Member { object, field, null_safe } = &callee.kind else {
        return None;
    };
    if *null_safe || !matches!(&object.kind, ExprKind::Ident(name) if name == target) {
        return None;
    }
    if !matches!(field.as_str(), "name" | "mode" | "closed") {
        return None;
    }
    if args.len() != 1
        || !args[0].spread
        || !matches!(&args[0].value.kind, ExprKind::Ident(name) if name == "__py_bound_args")
    {
        return None;
    }
    Some(field.clone())
}

fn suppress_context_types(expr: &Expression) -> Option<Vec<String>> {
    let ExprKind::Call { callee, args, .. } = &expr.kind else {
        return None;
    };
    let is_suppress = match &callee.kind {
        ExprKind::Ident(name) => name == "suppress",
        ExprKind::Member { object, field, .. } => {
            field == "suppress"
                && matches!(&object.kind, ExprKind::Ident(module) if module == "contextlib")
        }
        _ => false,
    };
    if !is_suppress {
        return None;
    }
    let mut types = Vec::new();
    for arg in args {
        if let ExprKind::Ident(name) = &arg.value.kind {
            types.extend(py_except_type_names(name));
        }
    }
    Some(types)
}

fn build_with_desugar(
    __w: &mut PyWalker,
    items: &[WithItem],
    body: Vec<Statement>,
) -> Vec<Statement> {
    let first = &items[0];
    // sqlite3 Connection used as a context manager → transaction semantics.
    if items.len() == 1 && first.var.is_none() {
        if let ExprKind::Ident(name) = &first.expr.kind {
            if is_sql_var(__w, name) {
                return build_sql_with_desugar(__w, name, body);
            }
        }
    }
    if items.len() == 1
        && first.var.is_none()
        && let Some(types) = suppress_context_types(&first.expr)
    {
        return vec![with_stmt(StmtKind::Try {
            body,
            catches: vec![CatchClause {
                types,
                var_name: None,
                stack_var: None,
                body: Vec::new(),
                when_clause: None,
            }],
            else_body: None,
            finally: None,
        })];
    }
    if items.len() == 1
        && let Some((target, field)) = unittest_patch_object_target(__w, &first.expr)
        && is_defined_class(__w, &target)
        && class_has_property(__w, &target, &field)
    {
        let replacement = if let Some(var) = &first.var {
            Expression::ident(var)
        } else {
            Expression::ident("__with_target_property_mock")
        };
        let mut out = Vec::new();
        out.push(with_stmt(StmtKind::Assign {
            targets: vec![replacement],
            value: Expression::new(ExprKind::New {
                class: Box::new(Expression::ident("PropertyMock")),
                args: Vec::new(),
            }),
            by_ref: false,
        }));
        out.extend(body);
        return out;
    }
    // `with open(...) as f:` — a file object is a plain adapter-built value, not
    // a class, so it has no `__enter__`/`__exit__` to call. Bind it directly and
    // close in a `finally`, which IS CPython's file context-manager semantics.
    // (Adding `__enter__`/`__exit__` as value_methods instead would shadow every
    // user-defined context manager, since value methods win over user methods.)
    if items.len() == 1
        && let ExprKind::Call { callee, .. } = &first.expr.kind
        && (matches!(&callee.kind, ExprKind::Ident(n) if n == "open")
            // `tempfile.NamedTemporaryFile(...)` yields the same file object.
            || matches!(&callee.kind, ExprKind::Member { object, field, .. }
                if matches!(&object.kind, ExprKind::Ident(m) if m == "tempfile")
                    && (field == "NamedTemporaryFile"
                        || field == "TemporaryFile"
                        || field == "TemporaryDirectory"))
            // `with os.scandir(d) as it:` — an array; nothing to close.
            || matches!(&callee.kind, ExprKind::Member { object, field, .. }
                if matches!(&object.kind, ExprKind::Ident(m) if m == "os")
                    && field == "scandir"))
    {
        // `TemporaryDirectory()` yields a PATH STRING, not a file object — it
        // has no `close()`, so bind it and skip the cleanup call.
        let closes = !matches!(&first.expr.kind, ExprKind::Call { callee, .. }
            if matches!(&callee.kind, ExprKind::Member { field, .. }
                if field == "TemporaryDirectory" || field == "scandir"));
        let close_via_method = matches!(&first.expr.kind, ExprKind::Call { callee, .. }
            if matches!(&callee.kind, ExprKind::Member { object, field, .. }
                if matches!(&object.kind, ExprKind::Ident(m) if m == "tempfile")
                    && (field == "NamedTemporaryFile" || field == "TemporaryFile")));
        return build_file_with_desugar(__w, first, body, closes, close_via_method);
    }
    if items.len() == 1
        && let ExprKind::New { class, .. } = &first.expr.kind
        && matches!(&class.kind, ExprKind::Ident(n) if n == "__PyNamedTempFile")
    {
        return build_file_with_desugar(__w, first, body, true, true);
    }
    if items.len() == 1
        && let ExprKind::Call { callee, .. } = &first.expr.kind
        && (matches!(&callee.kind, ExprKind::Ident(n)
                if n == "ThreadPoolExecutor" || n == "ProcessPoolExecutor" || n == "Pool")
            || matches!(&callee.kind, ExprKind::Member { object, field, .. }
                if matches!(&object.kind, ExprKind::Ident(m) if m == "multiprocessing")
                    && field == "Pool"))
    {
        let n = {
            let __n = __w.with_counter;
            __w.with_counter += 1;
            __n
        };
        let target = first
            .var
            .clone()
            .unwrap_or_else(|| format!("__with_target_{n}"));
        let mut out = vec![with_stmt(StmtKind::Assign {
            targets: vec![Expression::ident(&target)],
            value: first.expr.clone(),
            by_ref: false,
        })];
        out.extend(body);
        return out;
    }
    let n = {
        let __n = __w.with_counter;
        __w.with_counter += 1;
        __n
    };
    let mgr = format!("__with_mgr_{n}");
    let hit = format!("__with_hit_{n}");
    let exc = format!("__with_exc_{n}");
    let target = first
        .var
        .clone()
        .unwrap_or_else(|| format!("__with_target_{n}"));

    let inner_body = if items.len() > 1 {
        build_with_desugar(__w, &items[1..], body)
    } else {
        body
    };

    let assign = |name: &str, value: Expression| {
        with_stmt(StmtKind::Assign {
            targets: vec![Expression::ident(name)],
            value,
            by_ref: false,
        })
    };

    let catch = CatchClause {
        types: vec![],
        var_name: Some(exc.clone()),
        stack_var: None,
        body: vec![
            assign(&hit, Expression::bool(true)),
            with_stmt(StmtKind::If {
                // PEP-343: `__exit__(exc_type, exc_value, traceback)`. Pass the
                // exception TYPE (not the instance) as the first arg so
                // `issubclass(exc_type, …)` works (e.g. contextlib.suppress).
                cond: with_not(with_call(
                    with_member(&mgr, "__exit__"),
                    vec![
                        with_arg(with_call(
                            Expression::ident("type"),
                            vec![with_arg(Expression::ident(&exc))],
                        )),
                        with_arg(Expression::ident(&exc)),
                        with_arg(Expression::null()),
                    ],
                )),
                // `__exit__` returned falsy → re-raise the caught exception. A
                // bare `raise` re-raises `null` here, so raise `exc` explicitly.
                then_body: vec![with_stmt(StmtKind::Throw {
                    expr: Some(Expression::ident(&exc)),
                    cause: None,
                })],
                elifs: vec![],
                else_body: None,
            }),
        ],
        when_clause: None,
    };

    let finally = vec![with_stmt(StmtKind::If {
        cond: with_not(Expression::ident(&hit)),
        then_body: vec![with_stmt(StmtKind::Expr(with_call(
            with_member(&mgr, "__exit__"),
            vec![
                with_arg(Expression::null()),
                with_arg(Expression::null()),
                with_arg(Expression::null()),
            ],
        )))],
        elifs: vec![],
        else_body: None,
    })];

    vec![
        assign(&mgr, first.expr.clone()),
        assign(&target, with_call(with_member(&mgr, "__enter__"), vec![])),
        assign(&hit, Expression::bool(false)),
        with_stmt(StmtKind::Try {
            body: inner_body,
            catches: vec![catch],
            else_body: None,
            finally: Some(finally),
        }),
    ]
}

// ── Match ───────────────────────────────────────────────────────────────────

fn walk_match(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let mut subject = None;
    let mut cases = Vec::new();

    for p in pair.into_inner() {
        match p.as_rule() {
            Rule::expression_list => {
                if subject.is_none() {
                    subject = Some(walk_expr_list(__w, p)?);
                }
            }
            Rule::case_clause => {
                let mut pattern = Pattern::Wildcard;
                let mut guard = None;
                let mut body = Vec::new();
                for cp in p.into_inner() {
                    match cp.as_rule() {
                        Rule::pattern | Rule::or_pattern => pattern = walk_pattern(__w, cp)?,
                        Rule::block => body = walk_block(__w, cp)?,
                        _ => {
                            // Guard expression (after "if")
                            if cp.as_rule() != Rule::if_kw {
                                guard = Some(walk_expression(__w, cp)?);
                            }
                        }
                    }
                }
                cases.push(MatchCase {
                    pattern,
                    guard,
                    body,
                });
            }
            Rule::NEWLINE | Rule::INDENT | Rule::DEDENT => {}
            _ => {}
        }
    }

    Ok(StmtKind::MatchStatement {
        subject: subject.unwrap_or(Expression::new(ExprKind::Lit(Literal::Null))),
        cases,
    })
}

fn walk_pattern(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<Pattern, String> {
    match pair.as_rule() {
        Rule::or_pattern => {
            let pats: Vec<Pair<Rule>> = pair.into_inner().collect();
            if pats.len() == 1 {
                walk_pattern(__w, pats.into_iter().next().unwrap())
            } else {
                let patterns = pats
                    .into_iter()
                    .map(|__x| walk_pattern(__w, __x))
                    .collect::<Result<Vec<_>, _>>()?;
                Ok(Pattern::Or(patterns))
            }
        }
        Rule::pattern => {
            let inner = pair.into_inner().next();
            match inner {
                Some(p) => walk_pattern(__w, p),
                None => Ok(Pattern::Wildcard),
            }
        }
        Rule::single_pattern => {
            let inner = pair.into_inner().next().ok_or("Empty single_pattern")?;
            walk_pattern(__w, inner)
        }
        Rule::group_pattern => {
            let inner = pair.into_inner().next().ok_or("Empty group_pattern")?;
            walk_pattern(__w, inner)
        }
        Rule::as_pattern => {
            // pattern as name
            let mut inner = pair.into_inner();
            let sub_pattern =
                walk_pattern(__w, inner.next().ok_or("Missing as_pattern sub-pattern")?)?;
            // skip as_kw
            let name = inner
                .filter(|p| p.as_rule() == Rule::identifier)
                .next()
                .map(|p| p.as_str().to_string());
            Ok(Pattern::As {
                pattern: Some(Box::new(sub_pattern)),
                name,
            })
        }
        Rule::wildcard_pattern => Ok(Pattern::Wildcard),
        Rule::capture_pattern => {
            let name = pair.as_str().to_string();
            Ok(Pattern::As {
                pattern: None,
                name: Some(name),
            })
        }
        Rule::singleton_pattern => {
            let text = pair.as_str().trim();
            let expr = match text {
                "None" => Expression::null(),
                "True" => Expression::bool(true),
                "False" => Expression::bool(false),
                _ => Expression::null(),
            };
            Ok(Pattern::Singleton(expr))
        }
        Rule::literal_pattern => {
            let text = pair.as_str().trim();
            let expr = parse_literal_to_expr(text);
            Ok(Pattern::Value(expr))
        }
        Rule::value_pattern => {
            // Dotted name like module.CONST
            let expr = Expression::new(ExprKind::Ident(pair.as_str().trim().to_string()));
            Ok(Pattern::Value(expr))
        }
        Rule::star_pattern => {
            let name = pair
                .into_inner()
                .find(|p| p.as_rule() == Rule::identifier)
                .map(|p| p.as_str().to_string());
            Ok(Pattern::Star(name))
        }
        Rule::sequence_pattern => {
            let pats = pair
                .into_inner()
                .map(|__x| walk_pattern(__w, __x))
                .collect::<Result<Vec<_>, _>>()?;
            Ok(Pattern::Sequence(pats))
        }
        Rule::tuple_pattern => {
            let pats = pair
                .into_inner()
                .map(|__x| walk_pattern(__w, __x))
                .collect::<Result<Vec<_>, _>>()?;
            Ok(Pattern::Sequence(pats))
        }
        Rule::mapping_pattern => {
            let mut pairs_vec = Vec::new();
            for mp in pair.into_inner() {
                if mp.as_rule() == Rule::mapping_pair {
                    let mut mi = mp.into_inner();
                    let key = walk_expression(__w, mi.next().ok_or("Missing mapping key")?)?;
                    let val = walk_pattern(__w, mi.next().ok_or("Missing mapping pattern")?)?;
                    pairs_vec.push((key, val));
                }
            }
            Ok(Pattern::Mapping(pairs_vec))
        }
        Rule::class_pattern => {
            let mut cls_name = String::new();
            let mut patterns = Vec::new();
            let mut kw_patterns = Vec::new();
            for cp in pair.into_inner() {
                match cp.as_rule() {
                    Rule::identifier => cls_name = cp.as_str().to_string(),
                    Rule::class_pattern_arg => {
                        let mut ai = cp.into_inner();
                        let first = ai.next().ok_or("Empty class_pattern_arg")?;
                        if first.as_rule() == Rule::identifier {
                            // Could be keyword=pattern or just a capture pattern
                            if let Some(second) = ai.next() {
                                // keyword = pattern
                                let name = first.as_str().to_string();
                                let pat = walk_pattern(__w, second)?;
                                kw_patterns.push((name, pat));
                            } else {
                                // Just a pattern (identifier is capture or wildcard)
                                patterns.push(walk_pattern(__w, first)?);
                            }
                        } else {
                            patterns.push(walk_pattern(__w, first)?);
                        }
                    }
                    _ => patterns.push(walk_pattern(__w, cp)?),
                }
            }
            Ok(Pattern::Class {
                cls: Expression::new(ExprKind::Ident(cls_name)),
                patterns,
                kw_patterns,
            })
        }
        Rule::true_kw => Ok(Pattern::Singleton(Expression::bool(true))),
        Rule::false_kw => Ok(Pattern::Singleton(Expression::bool(false))),
        Rule::none_kw => Ok(Pattern::Singleton(Expression::null())),
        other => Err(format!("Unexpected pattern rule: {:?}", other)),
    }
}

// ── Return / Raise ──────────────────────────────────────────────────────────

fn walk_return(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let expr = pair
        .into_inner()
        .find(|p| is_expression_rule(p.as_rule()))
        .map(|__x| walk_expr_list_or_single(__w, __x))
        .transpose()?;
    Ok(StmtKind::Return(expr))
}

fn walk_raise(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let mut exc = None;
    let mut cause = None;
    let mut saw_from = false;
    for p in pair.into_inner() {
        match p.as_rule() {
            Rule::from_kw => saw_from = true,
            _ if is_expression_rule(p.as_rule()) => {
                let value = walk_expression(__w, p)?;
                let value = if let ExprKind::Ident(name) = &value.kind {
                    if py_builtin_exception_bases(name).is_some() {
                        call_ident(&format!("__py_exc_{name}"), Vec::new())
                    } else {
                        value
                    }
                } else {
                    value
                };
                if saw_from {
                    cause = Some(value);
                } else {
                    exc = Some(value);
                }
            }
            _ => {}
        }
    }
    Ok(StmtKind::Throw { expr: exc, cause })
}

// ── Del / Assert / Global / Nonlocal ────────────────────────────────────────

fn walk_del(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let exprs = pair
        .into_inner()
        .filter(|p| is_expression_rule(p.as_rule()))
        .map(|__x| {
            enter_assignment_target(__w);
            let out = walk_expression(__w, __x);
            leave_assignment_target(__w);
            out
        })
        .collect::<Result<Vec<_>, _>>()?;

    // A `del` target arrives ALREADY DESUGARED: python attribute and subscript
    // reads walk to `__py_attr_read(obj, "f")` and `__py_getitem(obj, k)`, not
    // to `ExprKind::Member` / `ExprKind::Index`. Slices are the exception —
    // `del a[1:3]` keeps its `Index { index: Slice }` shape — so both forms
    // have to be recognised here.
    if let [target] = exprs.as_slice() {
        match del_target(target) {
            // `del obj.attr`. A property with a deleter runs the deleter;
            // anything else removes the attribute, which `attr_delete` does
            // through the descriptor protocol when one is present.
            Some(DelTarget::Attr { object, field }) => {
                if let ExprKind::Ident(var) = &object.kind
                    && let Some(class_name) = instance_class(__w, var)
                    && class_property_has_deleter(__w, &class_name, &field)
                {
                    return Ok(StmtKind::Expr(Expression::new(ExprKind::Call {
                        callee: Box::new(Expression::new(ExprKind::Member {
                            object: Box::new(Expression::ident(var)),
                            field: format!("__del_{field}"),
                            null_safe: false,
                        })),
                        args: vec![],
                        optional: false,
                    })));
                }
                return Ok(StmtKind::Expr(call_ident(
                    "__py_attr_delete",
                    vec![(*object).clone(), Expression::string(&field)],
                )));
            }
            // `del obj[key]` (non-slice) → `obj.pop(key)`. Python `del` and
            // `.pop()` remove identically (both raise on a missing key/index),
            // and `.pop()` already works for dicts AND lists — whereas
            // `StmtKind::Delete`'s dict branch (`dict::emit_method_delete`) is
            // broken on dict literals (they don't populate the `__keys` array
            // it relies on).
            Some(DelTarget::Item { object, index }) => {
                if py_os_environ_expr(__w, &object) {
                    return Ok(StmtKind::Expr(call_ident(
                        "__py_os_unsetenv",
                        vec![(*index).clone()],
                    )));
                }
                if let ExprKind::Ident(var) = &object.kind
                    && let ExprKind::Lit(Literal::Str(name)) = &index.kind
                    && let Some(state) = __w.py_email_messages.get_mut(var)
                {
                    py_email_del_header(state, name);
                    return Ok(StmtKind::Expr(Expression::null()));
                }
                // A string-keyed subscript on a plain instance is an ATTRIBUTE,
                // not a mapping entry — unless the class defines `__getitem__`
                // and means it as one.
                if let ExprKind::Ident(var) = &object.kind
                    && let ExprKind::Lit(Literal::Str(field)) = &index.kind
                    && instance_class(__w, var)
                        .as_deref()
                        .is_some_and(|class_name| !class_has_attr(__w, class_name, "__getitem__"))
                {
                    return Ok(StmtKind::Expr(call_ident(
                        "__py_attr_delete",
                        vec![Expression::ident(var), Expression::string(field)],
                    )));
                }
                let pop = Expression::new(ExprKind::Call {
                    callee: Box::new(Expression::new(ExprKind::Member {
                        object: object.clone(),
                        field: "pop".into(),
                        null_safe: false,
                    })),
                    args: vec![Argument::positional((*index).clone())],
                    optional: false,
                });
                return Ok(StmtKind::Expr(pop));
            }
            None => {}
        }
    }
    // `del x` on a bare name drops a reference and may finalise. The walker
    // states no more than that it is a Delete: the policy is
    // `Directives::name_drop`, declared once for the module, and the shared
    // compiler lowers it against `ProtocolSlot::Destructor`. Slice targets keep
    // the same path — `del a[1:3]` removes a RANGE, which the shared lowering
    // reads off the target's own shape.
    Ok(StmtKind::Delete(exprs))
}

/// The two removable `del` target shapes, read through python's desugaring.
enum DelTarget {
    Attr {
        object: Box<Expression>,
        field: String,
    },
    Item {
        object: Box<Expression>,
        index: Box<Expression>,
    },
}

/// Recognise a `del` target in either its structural or its desugared spelling.
/// A SLICE subscript is not a target here: it removes a range rather than one
/// entry, and the shared `StmtKind::Delete` lowering handles it.
fn del_target(target: &Expression) -> Option<DelTarget> {
    match &target.kind {
        ExprKind::Member { object, field, .. } => Some(DelTarget::Attr {
            object: object.clone(),
            field: field.clone(),
        }),
        ExprKind::Index { object, index, .. } => {
            if matches!(index.kind, ExprKind::Slice { .. } | ExprKind::Range { .. }) {
                return None;
            }
            Some(DelTarget::Item {
                object: object.clone(),
                index: index.clone(),
            })
        }
        ExprKind::Call { callee, args, .. } => {
            let ExprKind::Ident(name) = &callee.kind else {
                return None;
            };
            if args.len() != 2 || args.iter().any(|a| a.name.is_some() || a.spread) {
                return None;
            }
            let object = Box::new(args[0].value.clone());
            match name.as_str() {
                "__py_attr_read" => match &args[1].value.kind {
                    ExprKind::Lit(Literal::Str(field)) => Some(DelTarget::Attr {
                        object,
                        field: field.clone(),
                    }),
                    _ => None,
                },
                "__py_getitem" => Some(DelTarget::Item {
                    object,
                    index: Box::new(args[1].value.clone()),
                }),
                _ => None,
            }
        }
        _ => None,
    }
}

fn walk_assert(__w: &mut PyWalker, pair: Pair<Rule>) -> Result<StmtKind, String> {
    let mut exprs: Vec<Expression> = pair
        .into_inner()
        .filter(|p| is_expression_rule(p.as_rule()))
        .map(|__x| walk_expression(__w, __x))
        .collect::<Result<Vec<_>, _>>()?;
    let msg = if exprs.len() > 1 { exprs.pop() } else { None };
    let test = exprs.into_iter().next().unwrap_or(Expression::bool(false));
    let message = msg.unwrap_or_else(|| Expression::string(""));
    Ok(StmtKind::If {
        cond: Expression::new(ExprKind::Unary {
            op: UnaryOp::Not,
            expr: Box::new(test),
        }),
        then_body: vec![Statement::new(StmtKind::Throw {
            expr: Some(call_ident("__py_exc_AssertionError", vec![message])),
            cause: None,
        })],
        elifs: Vec::new(),
        else_body: None,
    })
}

fn walk_scope_decl(pair: Pair<Rule>, kind: ScopeDeclKind) -> Result<StmtKind, String> {
    let names = pair
        .into_inner()
        .filter(|p| p.as_rule() == Rule::identifier)
        .map(|p| p.as_str().to_string())
        .collect();
    Ok(StmtKind::ScopeDecl { kind, names })
}

// ── Expression or assignment ────────────────────────────────────────────────

fn py_http_morsel_reserved_attr(expr: &Expression) -> bool {
    matches!(
        &expr.kind,
        ExprKind::Lit(Literal::Str(name))
            if matches!(
                name.as_str(),
                "expires"
                    | "path"
                    | "comment"
                    | "domain"
                    | "max-age"
                    | "secure"
                    | "version"
                    | "httponly"
                    | "samesite"
            )
    )
}

fn py_nested_morsel_setitem_stmt(target: &Expression, value: Expression) -> Option<StmtKind> {
    let ExprKind::Index { object, index, .. } = &target.kind else {
        return None;
    };
    if !py_http_morsel_reserved_attr(index) {
        return None;
    }
    let ExprKind::Index {
        object: inner_object,
        index: inner_index,
        ..
    } = &object.kind
    else {
        return None;
    };
    let receiver = Expression::new(ExprKind::Call {
        callee: Box::new(Expression::new(ExprKind::Member {
            object: inner_object.clone(),
            field: "__getitem__".into(),
            null_safe: false,
        })),
        args: vec![Argument::positional(*inner_index.clone())],
        optional: false,
    });
    Some(StmtKind::Block(vec![
        Statement::new(StmtKind::Assign {
            targets: vec![Expression::ident("__py_morsel_target")],
            value: receiver,
            by_ref: false,
        }),
        Statement::new(StmtKind::Expr(call_ident(
            "__py_attr_raw_write",
            vec![
                Expression::ident("__py_morsel_target"),
                *index.clone(),
                value,
            ],
        ))),
    ]))
}

fn py_http_message_call_rewrite(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    let ExprKind::Ident(var) = &object.kind else {
        return None;
    };
    if instance_class(__w, var).as_deref() != Some("HTTPMessage") {
        return None;
    }
    match field.as_str() {
        "get" if args.len() <= 2 => {
            let name = args.first()?.value.clone();
            let default = args
                .get(1)
                .map(|a| a.value.clone())
                .unwrap_or_else(Expression::null);
            Some(call_ident(
                "__py_http_message_get",
                vec![Expression::ident(var), name, default],
            ))
        }
        "get_content_type" if args.is_empty() => Some(call_ident(
            "__py_http_message_get_content_type",
            vec![Expression::ident(var)],
        )),
        "items" if args.is_empty() => Some(call_ident(
            "__py_http_message_items",
            vec![Expression::ident(var)],
        )),
        _ => None,
    }
}

