fn instance_dict_index_target(expr: &Expression) -> Option<(String, String)> {
    let ExprKind::Index { object, index, .. } = &expr.kind else {
        return None;
    };
    let ExprKind::Lit(Literal::Str(attr)) = &index.kind else {
        return None;
    };
    let ExprKind::Index {
        object: dict_object,
        index: dict_index,
        ..
    } = &object.kind
    else {
        return None;
    };
    if !matches!(&dict_index.kind, ExprKind::Lit(Literal::Str(name)) if name == "__dict__") {
        return None;
    }
    let ExprKind::Ident(var) = &dict_object.kind else {
        return None;
    };
    Some((var.clone(), attr.clone()))
}

fn python_instance_index(var: &str, attr: &str) -> Expression {
    Expression::new(ExprKind::Index {
        object: Box::new(Expression::ident(var)),
        index: Box::new(Expression::string(attr)),
        null_safe: false,
    })
}

fn is_userdict_instance(__w: &mut PyWalker, var: &str) -> bool {
    if is_userdict_var(__w, var) {
        return true;
    }
    instance_class(__w, var)
        .as_deref()
        .is_some_and(|class_name| py_class_is_subclass(__w, class_name, "UserDict"))
}

fn userdict_data_expr(var: &str) -> Expression {
    call_ident(
        "__py_obj_get__",
        vec![Expression::ident(var), Expression::string("data")],
    )
}

fn py_class_is_subclass(__w: &mut PyWalker, class_name: &str, target: &str) -> bool {
    if class_name == target || target == "object" {
        return true;
    }
    {
        let parents = &__w.py_class_parents;
        let mut stack = parents.get(class_name).cloned().unwrap_or_default();
        while let Some(parent) = stack.pop() {
            if parent == target || (parent == "bool" && target == "int") {
                return true;
            }
            if let Some(more) = parents.get(&parent) {
                stack.extend(more.iter().cloned());
            }
        }
        false
    }
}

#[derive(Clone)]
struct NamedTupleDef {
    type_name: String,
    fields: Vec<String>,
    /// Trailing defaults (`namedtuple(..., defaults=[...])`); apply right-aligned.
    defaults: Vec<Expression>,
}

fn register_namedtuple_def(__w: &mut PyWalker, name: &str, def: NamedTupleDef) {
    {
        __w.py_namedtuple_defs.insert(name.to_string(), def);
    };
}

fn namedtuple_def(__w: &mut PyWalker, name: &str) -> Option<NamedTupleDef> {
    __w.py_namedtuple_defs.get(name).cloned()
}

fn record_namedtuple_instance(__w: &mut PyWalker, name: &str, def: NamedTupleDef) {
    {
        __w.py_namedtuple_instances.insert(name.to_string(), def);
    };
}

fn namedtuple_instance_def(__w: &mut PyWalker, name: &str) -> Option<NamedTupleDef> {
    __w.py_namedtuple_instances.get(name).cloned()
}

/// The namedtuple definition backing a `_asdict`/`_replace` receiver: a direct
/// `NamedTuple` node (`P(1, 2)._replace(...)`) or a tracked instance variable
/// (`p = P(1, 2); p._replace(...)`).
fn receiver_namedtuple_def(__w: &mut PyWalker, recv: &Expression) -> Option<NamedTupleDef> {
    match &recv.kind {
        ExprKind::NamedTuple { fields, type_name } => Some(NamedTupleDef {
            type_name: type_name.clone().unwrap_or_default(),
            fields: fields.iter().filter_map(|(n, _)| n.clone()).collect(),
            defaults: Vec::new(),
        }),
        ExprKind::Ident(name) => namedtuple_instance_def(__w, name),
        _ => None,
    }
}

/// Positional read `recv[index]` off a namedtuple receiver.
fn namedtuple_index_read(recv: &Expression, index: usize) -> Expression {
    Expression::new(ExprKind::Index {
        object: Box::new(recv.clone()),
        index: Box::new(Expression::int(index as i64)),
        null_safe: false,
    })
}

/// `nt._asdict()` → an ordered dict `{field: nt[i]}`.
fn build_namedtuple_asdict(recv: &Expression, def: &NamedTupleDef) -> Expression {
    let props = def
        .fields
        .iter()
        .enumerate()
        .map(|(i, f)| ObjectProperty::KeyValue {
            key: Expression::new(ExprKind::Lit(Literal::Str(f.clone()))),
            value: namedtuple_index_read(recv, i),
        })
        .collect();
    // `nt._asdict()` returns a dict.
    py_dict_expr(props)
}

/// `nt._replace(**kw)` → a new namedtuple: each field keeps `nt[i]` unless a
/// keyword override supplies it. Reuses the shared `NamedTuple` lowering.
fn build_namedtuple_replace(
    recv: &Expression,
    def: &NamedTupleDef,
    args: Vec<Argument>,
) -> Expression {
    let mut overrides: HashMap<String, Expression> = HashMap::new();
    for arg in args {
        if let Some(name) = arg.name {
            overrides.insert(name, arg.value);
        }
    }
    let fields = def
        .fields
        .iter()
        .enumerate()
        .map(|(i, f)| {
            let value = overrides
                .remove(f)
                .unwrap_or_else(|| namedtuple_index_read(recv, i));
            (Some(f.clone()), value)
        })
        .collect();
    Expression::new(ExprKind::NamedTuple {
        fields,
        type_name: Some(def.type_name.clone()),
    })
}

/// Extract the string value of a string-literal expression.
fn str_literal(expr: &Expression) -> Option<String> {
    match &expr.kind {
        ExprKind::Lit(Literal::Str(s)) => Some(s.clone()),
        _ => None,
    }
}

/// Ordered value expressions of a list/tuple literal.
fn sequence_values(expr: &Expression) -> Option<Vec<Expression>> {
    match &expr.kind {
        ExprKind::Tuple(items) | ExprKind::Set(items) => Some(items.clone()),
        ExprKind::Array(items) if items.iter().all(|e| e.key.is_none() && !e.spread) => {
            Some(items.iter().map(|e| e.value.clone()).collect())
        }
        _ => None,
    }
}

/// Parse a namedtuple field spec: a whitespace/comma-separated string
/// (`'x y'`, `'x, y'`) or a list/tuple of name strings.
fn parse_field_spec(expr: &Expression) -> Option<Vec<String>> {
    if let Some(s) = str_literal(expr) {
        return Some(
            s.split([',', ' ', '\t', '\n'])
                .filter(|t| !t.is_empty())
                .map(|t| t.to_string())
                .collect(),
        );
    }
    let values = sequence_values(expr)?;
    values.iter().map(str_literal).collect()
}

/// If `value` is a `namedtuple('Type', fieldspec, defaults=...)` call, extract
/// its definition.
fn parse_namedtuple_call(value: &Expression) -> Option<NamedTupleDef> {
    let ExprKind::Call { callee, args, .. } = &value.kind else {
        return None;
    };
    let ExprKind::Ident(fname) = &callee.kind else {
        return None;
    };
    if fname != "namedtuple" && fname != "NamedTuple" {
        return None;
    }
    let positional: Vec<&Expression> = args
        .iter()
        .filter(|a| a.name.is_none())
        .map(|a| &a.value)
        .collect();
    if positional.len() < 2 {
        return None;
    }
    let type_name = str_literal(positional[0])?;
    let fields = parse_field_spec(positional[1])?;
    let defaults = args
        .iter()
        .find(|a| a.name.as_deref() == Some("defaults"))
        .and_then(|a| sequence_values(&a.value))
        .unwrap_or_default();
    Some(NamedTupleDef {
        type_name,
        fields,
        defaults,
    })
}

/// The type object bound by `Name = namedtuple(...)` — an object exposing
/// `_fields` (the field-name tuple) and `__typename`, so `Name._fields`
/// resolves as an ordinary member read.
fn namedtuple_type_object(def: &NamedTupleDef) -> Expression {
    let field_tuple = Expression::new(ExprKind::Tuple(
        def.fields
            .iter()
            .map(|f| Expression::new(ExprKind::Lit(Literal::Str(f.clone()))))
            .collect(),
    ));
    Expression::new(ExprKind::Object(vec![
        ObjectProperty::KeyValue {
            key: Expression::string("_fields"),
            value: field_tuple,
        },
        ObjectProperty::KeyValue {
            key: Expression::string("__typename"),
            value: Expression::new(ExprKind::Lit(Literal::Str(def.type_name.clone()))),
        },
    ]))
}

/// Build a `namedtuple` construction: bind positional/keyword args to fields in
/// order, filling trailing gaps from right-aligned `defaults`.
fn build_namedtuple_construction(def: &NamedTupleDef, args: Vec<Argument>) -> ExprKind {
    let n = def.fields.len();
    let mut values: Vec<Option<Expression>> = vec![None; n];
    let mut pos = 0usize;
    for arg in args {
        if let Some(name) = &arg.name {
            if let Some(i) = def.fields.iter().position(|f| f == name) {
                values[i] = Some(arg.value);
            }
        } else if pos < n {
            values[pos] = Some(arg.value);
            pos += 1;
        }
    }
    // Right-aligned defaults fill any still-missing trailing fields.
    let default_start = n.saturating_sub(def.defaults.len());
    for (i, slot) in values.iter_mut().enumerate() {
        if slot.is_none() && i >= default_start {
            *slot = def.defaults.get(i - default_start).cloned();
        }
    }
    let fields = def
        .fields
        .iter()
        .zip(values)
        .map(|(name, value)| (Some(name.clone()), value.unwrap_or_else(Expression::null)))
        .collect();
    ExprKind::NamedTuple {
        fields,
        type_name: Some(def.type_name.clone()),
    }
}

fn is_defined_class(__w: &mut PyWalker, name: &str) -> bool {
    __w.py_defined_classes.contains(name)
}

/// Build a call expression, normalising `ClassName(args)` (a call whose callee
/// is a declared class) to `ExprKind::New` so construction has one canonical
/// shape across languages. Any other callee stays a plain `Call`.
/// The builtin a relational operator lowers to, mirroring how `+`/`-`
/// route through `__pyadd__`/`__pysub__` for the same reason: only a
/// Python-level helper can dispatch on an object operand.
fn py_relational_helper(op: BinOp) -> Option<&'static str> {
    Some(match op {
        BinOp::Lt => "__pylt__",
        BinOp::Gt => "__pygt__",
        BinOp::LtEq => "__pyle__",
        BinOp::GtEq => "__pyge__",
        _ => return None,
    })
}

fn py_static_version_comparison(
    __w: &mut PyWalker,
    left: &Expression,
    right: &Expression,
    op: BinOp,
) -> Option<bool> {
    let left = py_static_version_tuple(__w, left)?;
    let right = py_static_version_tuple(__w, right)?;
    use std::cmp::Ordering;
    let ordering = py_version_tuple_cmp(&left, &right);
    Some(match op {
        BinOp::Lt => ordering == Ordering::Less,
        BinOp::Gt => ordering == Ordering::Greater,
        BinOp::LtEq => ordering != Ordering::Greater,
        BinOp::GtEq => ordering != Ordering::Less,
        _ => return None,
    })
}

fn py_static_version_tuple(__w: &mut PyWalker, expr: &Expression) -> Option<Vec<i64>> {
    if let ExprKind::Member { object, field, .. } = &expr.kind
        && field == "version_info"
        && module_namespace_path(__w, object).as_deref() == Some("sys")
    {
        return Some(vec![3, 12, 0, 0, 0]);
    }
    match &expr.kind {
        ExprKind::Tuple(items) => items.iter().map(py_static_int_literal).collect(),
        ExprKind::Array(items) => items
            .iter()
            .map(|item| py_static_int_literal(&item.value))
            .collect(),
        ExprKind::Object(props) => {
            let mut parts = Vec::new();
            for key in ["major", "minor", "micro", "releaselevel", "serial"] {
                let value = props.iter().find_map(|prop| match prop {
                    ObjectProperty::KeyValue { key: k, value }
                        if matches!(&k.kind, ExprKind::Lit(Literal::Str(s)) if s == key) =>
                    {
                        Some(value)
                    }
                    _ => None,
                })?;
                if key == "releaselevel" {
                    parts.push(match &value.kind {
                        ExprKind::Lit(Literal::Str(s)) if s == "alpha" => -3,
                        ExprKind::Lit(Literal::Str(s)) if s == "beta" => -2,
                        ExprKind::Lit(Literal::Str(s)) if s == "candidate" => -1,
                        ExprKind::Lit(Literal::Str(s)) if s == "final" => 0,
                        _ => return None,
                    });
                } else {
                    parts.push(py_static_int_literal(value)?);
                }
            }
            Some(parts)
        }
        _ => None,
    }
}

fn py_static_int_literal(expr: &Expression) -> Option<i64> {
    match &expr.kind {
        ExprKind::Lit(Literal::Int(n)) => Some(*n),
        _ => None,
    }
}

fn py_version_tuple_cmp(left: &[i64], right: &[i64]) -> std::cmp::Ordering {
    for (a, b) in left.iter().zip(right.iter()) {
        match a.cmp(b) {
            std::cmp::Ordering::Equal => {}
            other => return other,
        }
    }
    left.len().cmp(&right.len())
}

fn py_richcompare_method(op: BinOp) -> Option<&'static str> {
    Some(match op {
        BinOp::Lt => "__lt__",
        BinOp::Gt => "__gt__",
        BinOp::LtEq => "__le__",
        BinOp::GtEq => "__ge__",
        _ => return None,
    })
}

fn py_fresh_class_lacks_richcompare(__w: &mut PyWalker, expr: &Expression, op: BinOp) -> bool {
    let Some(method) = py_richcompare_method(op) else {
        return false;
    };
    let ExprKind::New { class, .. } = &expr.kind else {
        return false;
    };
    let ExprKind::Ident(class_name) = &class.kind else {
        return false;
    };
    !class_has_attr(__w, class_name, method)
}

/// `strftime` directives this expands, as `(property, pad width)`.
fn strftime_directive(spec: char) -> Option<(&'static str, i64)> {
    Some(match spec {
        'Y' => ("year", 4),
        'm' => ("month", 2),
        'd' => ("day", 2),
        'H' => ("hour", 2),
        'M' => ("minute", 2),
        'S' => ("second", 2),
        'f' => ("microsecond", 6),
        _ => return None,
    })
}

/// `dt.strftime('%Y-%m-%d')` → `pad(dt['year'],4) + '-' + pad(dt['month'],2) …`
///
/// The components are already properties and the format is a literal, so
/// the whole format expands at compile time — no runtime format scanner,
/// and no host fn for it. Returns `None` for a non-literal format or a
/// directive outside the set above, so the call is left alone rather than
/// formatted wrongly.
fn strftime_expand(callee: &Expression, args: &[Argument]) -> Option<ExprKind> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if field != "strftime" || args.len() != 1 {
        return None;
    }
    let ExprKind::Lit(Literal::Str(fmt)) = &args[0].value.kind else {
        return None;
    };

    let read = |prop: &str, width: i64| {
        Expression::new(ExprKind::Call {
            callee: Box::new(Expression::ident("__py_dt_pad")),
            args: vec![
                Argument::positional(Expression::new(ExprKind::Index {
                    object: Box::new((**object).clone()),
                    index: Box::new(Expression::string(prop)),
                    null_safe: false,
                })),
                Argument::positional(Expression::new(ExprKind::Lit(Literal::Int(width)))),
            ],
            optional: false,
        })
    };

    let mut parts: Vec<Expression> = Vec::new();
    let mut lit = String::new();
    let mut chars = fmt.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '%' {
            lit.push(c);
            continue;
        }
        match chars.next() {
            Some('%') => lit.push('%'),
            Some('z') => {
                if !lit.is_empty() {
                    parts.push(Expression::string(&lit));
                    lit.clear();
                }
                parts.push(Expression::new(ExprKind::Call {
                    callee: Box::new(Expression::ident("__py_tz_offset_str")),
                    args: vec![Argument::positional((**object).clone())],
                    optional: false,
                }));
            }
            Some(spec) => {
                let (prop, width) = strftime_directive(spec)?;
                if !lit.is_empty() {
                    parts.push(Expression::string(&lit));
                    lit.clear();
                }
                parts.push(read(prop, width));
            }
            None => lit.push('%'),
        }
    }
    if !lit.is_empty() {
        parts.push(Expression::string(&lit));
    }

    let mut iter = parts.into_iter();
    let first = iter.next().unwrap_or_else(|| Expression::string(""));
    Some(
        iter.fold(first, |acc, part| {
            Expression::new(ExprKind::Binary {
                op: BinOp::Add,
                left: Box::new(acc),
                right: Box::new(part),
            })
        })
        .kind,
    )
}

/// `time.strftime(fmt, t)` — same compile-time expansion as `dt.strftime`, but
/// over a `struct_time`'s `tm_*` fields, and it is a two-arg module function
/// rather than a method. `%A` reads the Monday=0 weekday name; `%j` is the
/// zero-padded day of year; `%%` is a literal `%`.
fn time_strftime_expand(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<ExprKind> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    let ExprKind::Ident(module) = &object.kind else {
        return None;
    };
    if resolve_module_alias(__w, module).unwrap_or_else(|| module.clone()) != "time"
        || field != "strftime"
        || args.len() != 2
    {
        return None;
    }
    let ExprKind::Lit(Literal::Str(fmt)) = &args[0].value.kind else {
        return None;
    };
    let t = args[1].value.clone();

    let field_read =
        |prop: &str| call_ident("__py_attr_read", vec![t.clone(), Expression::string(prop)]);
    let literal = |value: &str| Expression::string(value);
    let padded_literal = |value: &str| literal(value);
    let padded = |prop: &str, width: i64| {
        Expression::new(ExprKind::Call {
            callee: Box::new(Expression::ident("__py_dt_pad")),
            args: vec![
                Argument::positional(field_read(prop)),
                Argument::positional(Expression::new(ExprKind::Lit(Literal::Int(width)))),
            ],
            optional: false,
        })
    };
    let weekday_name = || {
        let names = [
            "Monday",
            "Tuesday",
            "Wednesday",
            "Thursday",
            "Friday",
            "Saturday",
            "Sunday",
        ];
        Expression::new(ExprKind::Index {
            object: Box::new(Expression::new(ExprKind::Array(
                names
                    .iter()
                    .map(|n| ArrayElement {
                        value: Expression::string(n),
                        spread: false,
                        key: None,
                        by_ref: false,
                    })
                    .collect(),
            ))),
            index: Box::new(field_read("tm_wday")),
            null_safe: false,
        })
    };

    let mut parts: Vec<Expression> = Vec::new();
    let mut lit = String::new();
    let mut chars = fmt.chars();
    while let Some(c) = chars.next() {
        if c != '%' {
            lit.push(c);
            continue;
        }
        let part = match chars.next() {
            Some('%') => {
                lit.push('%');
                continue;
            }
            Some('Y') => padded("tm_year", 4),
            Some('m') => padded("tm_mon", 2),
            Some('d') => padded("tm_mday", 2),
            Some('H') => padded("tm_hour", 2),
            Some('M') => padded("tm_min", 2),
            Some('S') => padded("tm_sec", 2),
            Some('j') => padded("tm_yday", 3),
            Some('A') => weekday_name(),
            Some('U') | Some('W') => padded_literal("00"),
            _ => return None,
        };
        if !lit.is_empty() {
            parts.push(Expression::string(&lit));
            lit.clear();
        }
        parts.push(part);
    }
    if !lit.is_empty() {
        parts.push(Expression::string(&lit));
    }

    let mut iter = parts.into_iter();
    let first = iter.next().unwrap_or_else(|| Expression::string(""));
    Some(
        iter.fold(first, |acc, part| {
            Expression::new(ExprKind::Binary {
                op: BinOp::Add,
                left: Box::new(acc),
                right: Box::new(part),
            })
        })
        .kind,
    )
}

fn time_struct_time_call(values: Vec<Expression>) -> Expression {
    Expression::new(ExprKind::Call {
        callee: Box::new(Expression::ident("__py_time_struct_time")),
        args: vec![Argument::positional(Expression::new(ExprKind::Array(
            values
                .into_iter()
                .map(|value| ArrayElement {
                    key: None,
                    value,
                    spread: false,
                    by_ref: false,
                })
                .collect(),
        )))],
        optional: false,
    })
}

fn parse_fixed_time(format: &str, value: &str) -> Option<Vec<Expression>> {
    match format {
        "%Y-%m-%d" => {
            let mut parts = value.split('-');
            let year = parts.next()?.parse::<i64>().ok()?;
            let mon = parts.next()?.parse::<i64>().ok()?;
            let day = parts.next()?.parse::<i64>().ok()?;
            Some(vec![
                Expression::int(year),
                Expression::int(mon),
                Expression::int(day),
                Expression::int(0),
                Expression::int(0),
                Expression::int(0),
                Expression::int(0),
                Expression::int(1),
                Expression::int(-1),
            ])
        }
        "%Y/%m" => {
            let mut parts = value.split('/');
            let year = parts.next()?.parse::<i64>().ok()?;
            let mon = parts.next()?.parse::<i64>().ok()?;
            Some(vec![
                Expression::int(year),
                Expression::int(mon),
                Expression::int(1),
                Expression::int(0),
                Expression::int(0),
                Expression::int(0),
                Expression::int(0),
                Expression::int(1),
                Expression::int(-1),
            ])
        }
        "%H:%M:%S" => {
            let mut parts = value.split(':');
            let hour = parts.next()?.parse::<i64>().ok()?;
            let min = parts.next()?.parse::<i64>().ok()?;
            let sec = parts.next()?.parse::<i64>().ok()?;
            Some(vec![
                Expression::int(1900),
                Expression::int(1),
                Expression::int(1),
                Expression::int(hour),
                Expression::int(min),
                Expression::int(sec),
                Expression::int(0),
                Expression::int(1),
                Expression::int(-1),
            ])
        }
        _ => None,
    }
}

fn time_module_call(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<ExprKind> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    let ExprKind::Ident(module) = &object.kind else {
        return None;
    };
    if resolve_module_alias(__w, module).unwrap_or_else(|| module.clone()) != "time" {
        return None;
    }
    match field.as_str() {
        "asctime" | "ctime" => Some(Expression::string("Thu Jan  1 00:00:00 1970").kind),
        "get_clock_info" => Some(
            Expression::new(ExprKind::Object(vec![
                ObjectProperty::KeyValue {
                    key: Expression::string("monotonic"),
                    value: Expression::new(ExprKind::Lit(Literal::Bool(true))),
                },
                ObjectProperty::KeyValue {
                    key: Expression::string("adjustable"),
                    value: Expression::new(ExprKind::Lit(Literal::Bool(false))),
                },
                ObjectProperty::KeyValue {
                    key: Expression::string("resolution"),
                    value: Expression::new(ExprKind::Lit(Literal::Float(0.001))),
                },
            ]))
            .kind,
        ),
        "strptime" if args.len() >= 2 => {
            let ExprKind::Lit(Literal::Str(value)) = &args[0].value.kind else {
                return None;
            };
            let ExprKind::Lit(Literal::Str(format)) = &args[1].value.kind else {
                return None;
            };
            parse_fixed_time(format, value).map(|values| time_struct_time_call(values).kind)
        }
        _ => None,
    }
}

/// The components a datetime `replace` accepts, in the order the emitter
/// reads them. `microsecond`/`tzinfo`/`fold` are accepted as keywords but
/// have no effect on the ms-resolution, UTC-only value.
const DT_REPLACE_PARAMS: &[&str] = &[
    "year",
    "month",
    "day",
    "hour",
    "minute",
    "second",
    "microsecond",
    "tzinfo",
    "fold",
];

/// `d.replace(year=2021)` → `__py_dt_replace(d, year, …, second)`.
///
/// `value_methods` are keyed by method name alone, so `replace` already
/// belongs to `str.replace`. The two are told apart by shape rather than by
/// receiver type: a datetime `replace` names its components
/// (`replace(year=…)`), while `str.replace(old, new)` is positional. A call
/// with no keywords is therefore left alone for the string path.
fn datetime_replace_call(callee: &Expression, args: &[Argument]) -> Option<ExprKind> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if field != "replace" || args.is_empty() {
        return None;
    }
    if !args
        .iter()
        .all(|a| matches!(a.name.as_deref(), Some(n) if DT_REPLACE_PARAMS.contains(&n)))
    {
        return None;
    }
    let mut call_args = vec![Argument::positional((**object).clone())];
    for prop in &DT_REPLACE_PARAMS[..6] {
        let value = args
            .iter()
            .find(|a| a.name.as_deref() == Some(*prop))
            .map(|a| a.value.clone())
            .unwrap_or_else(|| Expression::new(ExprKind::Lit(Literal::Null)));
        call_args.push(Argument::positional(value));
    }
    Some(ExprKind::Call {
        callee: Box::new(Expression::ident("__py_dt_replace")),
        args: call_args,
        optional: false,
    })
}

/// `zoneinfo` — `ZoneInfo(key)` is a value carrying its key, and
/// `available_timezones()` is the set of zones this runtime can actually
/// resolve. `ecma:date` is UTC-only (`getTimezoneOffset` is always 0) and
/// no tzdata is mounted, so UTC is genuinely the whole set — this reports
/// what the runtime does, it does not stub out a larger list.
///
/// Both are plain data, so the walker builds them directly.
fn zoneinfo_call(__w: &mut PyWalker, callee: &Expression, args: &[Argument]) -> Option<ExprKind> {
    let ExprKind::Ident(name) = &callee.kind else {
        return None;
    };
    if !is_from_imported_module(__w, "zoneinfo") && !is_imported_module(__w, "zoneinfo") {
        return None;
    }
    match name.as_str() {
        "ZoneInfo" if args.len() == 1 => Some(ExprKind::Object(vec![
            ObjectProperty::KeyValue {
                key: Expression::string("__type"),
                value: Expression::string("ZoneInfo"),
            },
            ObjectProperty::KeyValue {
                key: Expression::string("key"),
                value: args[0].value.clone(),
            },
        ])),
        "available_timezones" if args.is_empty() => Some(ExprKind::Call {
            callee: Box::new(Expression::ident("set")),
            args: vec![Argument::positional(Expression::new(ExprKind::Array(
                vec![ArrayElement {
                    value: Expression::string("UTC"),
                    spread: false,
                    key: None,
                    by_ref: false,
                }],
            )))],
            optional: false,
        }),
        _ => None,
    }
}

/// CPython signatures for the `datetime` constructors that are normally
/// called with keywords (`timedelta(days=2)`). Keyword handling belongs to
/// the frontend, so the emitter only ever sees positional arguments in this
/// exact order.
fn datetime_kwarg_signature(
    __w: &mut PyWalker,
    callee: &Expression,
) -> Option<&'static [&'static str]> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    let ExprKind::Ident(name) = &object.kind else {
        return None;
    };
    let module = resolve_module_alias(__w, name).unwrap_or_else(|| name.clone());
    if module != "datetime" {
        return None;
    }
    Some(match field.as_str() {
        "timedelta" => &[
            "days",
            "seconds",
            "microseconds",
            "milliseconds",
            "minutes",
            "hours",
            "weeks",
        ],
        "date" => &["year", "month", "day"],
        "time" => &["hour", "minute", "second", "microsecond", "tzinfo"],
        "datetime" => &[
            "year",
            "month",
            "day",
            "hour",
            "minute",
            "second",
            "microsecond",
            "tzinfo",
        ],
        _ => return None,
    })
}

/// Place each keyword argument at its signature slot, filling the gaps with
/// `0`. Only runs when a keyword is actually present, so positional calls
/// keep their natural arity and the emitter's own defaults still apply.
fn normalize_datetime_kwargs(params: &[&str], args: Vec<Argument>) -> Vec<Argument> {
    if args.iter().all(|a| a.name.is_none()) {
        return args;
    }
    let zero = || Expression::new(ExprKind::Lit(Literal::Int(0)));
    let mut slots: Vec<Expression> = params.iter().map(|_| zero()).collect();
    let mut highest = 0usize;
    for (i, arg) in args.into_iter().enumerate() {
        let slot = match &arg.name {
            Some(name) => match params.iter().position(|p| p == name) {
                Some(pos) => pos,
                // An unknown keyword is not ours to interpret; drop it
                // rather than shift every later argument.
                None => continue,
            },
            None => i,
        };
        if slot < slots.len() {
            highest = highest.max(slot);
            slots[slot] = arg.value;
        }
    }
    slots
        .into_iter()
        .take(highest + 1)
        .map(Argument::positional)
        .collect()
}

fn normalize_keyword_args_to_positional(params: &[&str], args: Vec<Argument>) -> Vec<Argument> {
    if args.iter().all(|a| a.name.is_none()) || args.iter().any(|a| a.spread) {
        return args;
    }
    let original = args.clone();
    let mut slots: Vec<Option<Expression>> = params.iter().map(|_| None).collect();
    let mut highest = 0usize;
    for (i, arg) in args.into_iter().enumerate() {
        let slot = match arg.name.as_deref() {
            Some(name) => match params.iter().position(|p| *p == name) {
                Some(pos) => pos,
                None => return original,
            },
            None => i,
        };
        if slot >= slots.len() {
            return original;
        }
        highest = highest.max(slot);
        slots[slot] = Some(arg.value);
    }
    slots
        .into_iter()
        .take(highest + 1)
        .map(|value| Argument::positional(value.unwrap_or_else(Expression::null)))
        .collect()
}

fn normalize_argparse_add_argument_args(args: Vec<Argument>) -> Vec<Argument> {
    if args.is_empty() || args.iter().any(|arg| arg.spread) {
        return args;
    }
    if args.len() == 3
        && args.iter().all(|arg| arg.name.is_none())
        && matches!(args[1].value.kind, ExprKind::Array(_))
        && matches!(args[2].value.kind, ExprKind::Map(_) | ExprKind::Object(_))
    {
        return args;
    }
    let original = args.clone();
    let mut positional = Vec::new();
    let mut keywords = Vec::new();
    for arg in args {
        match arg.name {
            Some(name) => {
                let key = if name == "type" { "typ".to_string() } else { name };
                let value = if key == "typ" {
                    match &arg.value.kind {
                        ExprKind::Ident(name) if name == "int" => Expression::string("__argparse_int"),
                        ExprKind::Ident(name) if name == "float" => Expression::string("__argparse_float"),
                        ExprKind::Ident(name) if name == "str" => Expression::string("__argparse_str"),
                        _ => argparse_converter_lambda(arg.value),
                    }
                } else {
                    arg.value
                };
                keywords.push((key, value));
            }
            None => positional.push(arg.value),
        }
    }
    if positional.is_empty() {
        return original;
    }
    let flag = positional.remove(0);
    vec![
        Argument::positional(flag),
        Argument::positional(python_array_expr(positional)),
        Argument::positional(python_kwargs_dict_expr(keywords)),
    ]
}

fn argparse_converter_lambda(converter: Expression) -> Expression {
    let value_param = "__argparse_value";
    Expression::new(ExprKind::Lambda {
        params: vec![Param {
            name: value_param.to_string(),
            type_hint: None,
            default: None,
            pass_by: PassBy::Value,
            is_rest: false,
            is_kwargs: false,
            is_optional: false,
            is_nullable: false,
        }],
        body: LambdaBody::Expr(Box::new(Expression::new(ExprKind::Call {
            callee: Box::new(converter),
            args: vec![Argument::positional(Expression::ident(value_param))],
            optional: false,
        }))),
        captures: Vec::new(),
        is_async: false,
    })
}

fn python_signature_kind(params: &[Param], kinds: &[String], idx: usize) -> String {
    py_parameter_kind_for(params, kinds, idx)
}

fn python_array_expr(values: Vec<Expression>) -> Expression {
    Expression::new(ExprKind::Array(
        values
            .into_iter()
            .map(|value| ArrayElement {
                key: None,
                value,
                spread: false,
                by_ref: false,
            })
            .collect(),
    ))
}

fn python_kwargs_dict_expr(entries: Vec<(String, Expression)>) -> Expression {
    py_dict_expr(
        entries
            .into_iter()
            .map(|(name, value)| ObjectProperty::KeyValue {
                key: Expression::string(&name),
                value,
            })
            .collect(),
    )
}

fn python_expand_literal_spread_arg(arg: Argument) -> Option<Vec<Argument>> {
    if !arg.spread {
        return Some(vec![arg]);
    }
    match arg.value.kind {
        ExprKind::Array(items) => Some(
            items
                .into_iter()
                .map(|item| Argument::positional(item.value))
                .collect(),
        ),
        ExprKind::Tuple(values) => Some(values.into_iter().map(Argument::positional).collect()),
        ExprKind::Map(entries) => {
            let mut out = Vec::new();
            for (key, value) in entries {
                let ExprKind::Lit(Literal::Str(name)) = key.kind else {
                    return None;
                };
                out.push(Argument {
                    value,
                    name: Some(name.to_string()),
                    by_ref: false,
                    spread: false,
                });
            }
            Some(out)
        }
        ExprKind::Object(props) => {
            let mut out = Vec::new();
            for prop in props {
                let ObjectProperty::KeyValue { key, value } = prop else {
                    return None;
                };
                let ExprKind::Lit(Literal::Str(name)) = key.kind else {
                    return None;
                };
                out.push(Argument {
                    value,
                    name: Some(name.to_string()),
                    by_ref: false,
                    spread: false,
                });
            }
            Some(out)
        }
        _ => None,
    }
}

fn python_expand_literal_spreads(args: Vec<Argument>) -> Option<Vec<Argument>> {
    let mut out = Vec::new();
    for arg in args {
        out.extend(python_expand_literal_spread_arg(arg)?);
    }
    Some(out)
}

fn python_signature_call_args(
    params: &[Param],
    kinds: &[String],
    args: Vec<Argument>,
) -> Result<Vec<Argument>, Expression> {
    let args = match python_expand_literal_spreads(args.clone()) {
        Some(expanded) => expanded,
        None => return Ok(args),
    };
    let mut positional = Vec::new();
    let mut keywords = Vec::<(String, Expression)>::new();
    for arg in args {
        if let Some(name) = arg.name {
            keywords.push((name, arg.value));
        } else {
            positional.push(arg.value);
        }
    }

    let has_var_kwargs = params
        .iter()
        .enumerate()
        .any(|(idx, _)| python_signature_kind(params, kinds, idx) == "VAR_KEYWORD");
    let has_var_positional = params
        .iter()
        .enumerate()
        .any(|(idx, _)| python_signature_kind(params, kinds, idx) == "VAR_POSITIONAL");
    let mut consumed_keywords = HashSet::<usize>::new();
    let mut positional_index = 0usize;
    let mut out = Vec::new();

    for (idx, param) in params.iter().enumerate() {
        let kind = python_signature_kind(params, kinds, idx);
        match kind.as_str() {
            "VAR_POSITIONAL" => {
                let rest = positional[positional_index..].to_vec();
                positional_index = positional.len();
                out.push(Argument::positional(python_array_expr(rest)));
            }
            "VAR_KEYWORD" => {
                let rest = keywords
                    .iter()
                    .enumerate()
                    .filter_map(|(kw_idx, (name, value))| {
                        (!consumed_keywords.contains(&kw_idx))
                            .then(|| (name.clone(), value.clone()))
                    })
                    .collect();
                out.push(Argument::positional(python_kwargs_dict_expr(rest)));
            }
            "KEYWORD_ONLY" => {
                if let Some((kw_idx, (_, value))) = keywords
                    .iter()
                    .enumerate()
                    .find(|(kw_idx, (name, _))| {
                        !consumed_keywords.contains(kw_idx) && name == &param.name
                    })
                {
                    consumed_keywords.insert(kw_idx);
                    out.push(Argument::positional(value.clone()));
                } else if let Some(default) = &param.default {
                    out.push(Argument::positional(default.clone()));
                } else {
                    return Err(py_raise_expr("TypeError", Some("missing required keyword-only argument")));
                }
            }
            "POSITIONAL_ONLY" => {
                if keywords.iter().any(|(name, _)| name == &param.name) {
                    return Err(py_raise_expr("TypeError", Some("positional-only argument passed as keyword argument")));
                }
                if let Some(value) = positional.get(positional_index).cloned() {
                    positional_index += 1;
                    out.push(Argument::positional(value));
                } else if let Some(default) = &param.default {
                    out.push(Argument::positional(default.clone()));
                } else {
                    return Err(py_raise_expr("TypeError", Some("missing required positional argument")));
                }
            }
            _ => {
                let keyword_match = keywords
                    .iter()
                    .enumerate()
                    .find(|(kw_idx, (name, _))| {
                        !consumed_keywords.contains(kw_idx) && name == &param.name
                    });
                if let Some(value) = positional.get(positional_index).cloned() {
                    positional_index += 1;
                    if keyword_match.is_some() {
                        return Err(py_raise_expr("TypeError", Some("multiple values for argument")));
                    }
                    out.push(Argument::positional(value));
                } else if let Some((kw_idx, (_, value))) = keyword_match {
                    consumed_keywords.insert(kw_idx);
                    out.push(Argument::positional(value.clone()));
                } else if let Some(default) = &param.default {
                    out.push(Argument::positional(default.clone()));
                } else {
                    return Err(py_raise_expr("TypeError", Some("missing required positional argument")));
                }
            }
        }
    }

    if positional_index < positional.len() && !has_var_positional {
        return Err(py_raise_expr("TypeError", Some("too many positional arguments")));
    }
    if !has_var_kwargs
        && keywords
            .iter()
            .enumerate()
            .any(|(kw_idx, _)| !consumed_keywords.contains(&kw_idx))
    {
        return Err(py_raise_expr("TypeError", Some("unexpected keyword argument")));
    }

    Ok(out)
}

fn rewrite_python_known_callable_call(
    __w: &mut PyWalker,
    callee: &Expression,
    args: Vec<Argument>,
    optional: bool,
) -> Option<Expression> {
    let ExprKind::Ident(name) = &callee.kind else {
        return None;
    };
    let params = defined_function_params(__w, name)?;
    let kinds = defined_function_param_kinds(__w, name).unwrap_or_default();
    if params.is_empty() {
        return None;
    }
    let had_spread = args.iter().any(|arg| arg.spread);
    let had_named_or_spread = args.iter().any(|arg| arg.name.is_some() || arg.spread);
    let expanded_args = python_expand_literal_spreads(args.clone()).unwrap_or(args.clone());
    let positional_count = expanded_args
        .iter()
        .filter(|arg| arg.name.is_none() && !arg.spread)
        .count();
    let has_var_positional = params
        .iter()
        .enumerate()
        .any(|(idx, _)| python_signature_kind(&params, &kinds, idx) == "VAR_POSITIONAL");
    let has_var_keyword = params
        .iter()
        .enumerate()
        .any(|(idx, _)| python_signature_kind(&params, &kinds, idx) == "VAR_KEYWORD");
    let has_nonterminal_var_positional = params.iter().enumerate().any(|(idx, _)| {
        python_signature_kind(&params, &kinds, idx) == "VAR_POSITIONAL"
            && kinds
                .iter()
                .skip(idx + 1)
                .any(|kind| kind != "VAR_KEYWORD")
    });
    if !had_named_or_spread
        && (has_var_positional || has_var_keyword)
        && positional_count == params.len()
    {
        return None;
    }
    if !has_nonterminal_var_positional && !has_var_keyword {
        return match python_signature_call_args(&params, &kinds, expanded_args.clone()) {
            Err(err) => Some(err),
            Ok(_) if had_spread => {
                let args = expanded_args
                    .into_iter()
                    .map(|mut arg| {
                        arg.value = desugar_member_reads(__w, arg.value);
                        arg
                    })
                    .collect();
                Some(Expression::new(ExprKind::Call {
                    callee: Box::new(callee.clone()),
                    args,
                    optional,
                }))
            }
            Ok(_) => None,
        };
    }
    match python_signature_call_args(&params, &kinds, args) {
        Ok(args) => {
            let args = args
                .into_iter()
                .map(|mut arg| {
                    arg.value = desugar_member_reads(__w, arg.value);
                    arg
                })
                .collect();
            Some(Expression::new(ExprKind::Call {
                callee: Box::new(callee.clone()),
                args,
                optional,
            }))
        }
        Err(err) => Some(err),
    }
}

fn core_class_method_param_order(class_name: &str, method: &str) -> Option<&'static [&'static str]> {
    match (class_name, method) {
        ("ConfigParser" | "RawConfigParser", "get" | "getint" | "getfloat" | "getboolean") => {
            Some(&["sec", "opt", "fallback"])
        }
        _ => None,
    }
}

fn imported_datetime_type(__w: &mut PyWalker, name: &str) -> bool {
    is_from_imported_module(__w, "datetime")
        && matches!(
            name,
            "date" | "time" | "datetime" | "timedelta" | "timezone"
        )
}

fn datetime_ctor_builtin(name: &str) -> Option<(&'static str, &'static [&'static str])> {
    Some(match name {
        "date" => ("__py_date_new", &["year", "month", "day"]),
        "time" => (
            "__py_time_new",
            &["hour", "minute", "second", "microsecond", "tzinfo"],
        ),
        "datetime" => (
            "__py_datetime_new",
            &[
                "year",
                "month",
                "day",
                "hour",
                "minute",
                "second",
                "microsecond",
                "tzinfo",
            ],
        ),
        "timedelta" => (
            "__py_timedelta_new",
            &[
                "days",
                "seconds",
                "microseconds",
                "milliseconds",
                "minutes",
                "hours",
                "weeks",
            ],
        ),
        "timezone" => ("__py_timezone_new", &["offset", "name"]),
        _ => return None,
    })
}

fn imported_datetime_ctor_call(
    __w: &mut PyWalker,
    callee: &Expression,
    args: Vec<Argument>,
) -> Option<ExprKind> {
    let ExprKind::Ident(name) = &callee.kind else {
        return None;
    };
    if !imported_datetime_type(__w, name) {
        return None;
    }
    let (builtin, params) = datetime_ctor_builtin(name)?;
    Some(ExprKind::Call {
        callee: Box::new(Expression::ident(builtin)),
        args: normalize_datetime_kwargs(params, args),
        optional: false,
    })
}

fn datetime_class_method_call(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    let ExprKind::Ident(type_name) = &object.kind else {
        return None;
    };
    if type_name == "datetime" && field == "strptime" && args.len() >= 2 {
        if let (Some(value), Some(format)) = (
            resolve_string_const(__w, &args[0].value),
            resolve_string_const(__w, &args[1].value),
        ) && let Some(parts) = parse_fixed_datetime(&format, &value)
        {
            return Some(call_ident("__py_datetime_new", parts));
        }
    }
    if !imported_datetime_type(__w, type_name) {
        return None;
    }
    let builtin = match (type_name.as_str(), field.as_str()) {
        ("date" | "datetime", "fromordinal") => "__py_fromordinal",
        ("date", "fromtimestamp") | ("datetime", "fromtimestamp") => "__py_fromtimestamp",
        ("date", "fromisoformat") => "__py_date_fromisoformat",
        ("time", "fromisoformat") => "__py_time_fromisoformat",
        ("datetime", "fromisoformat" | "strptime") => "__py_datetime_fromisoformat",
        ("datetime", "now" | "utcnow" | "today") => "__py_dt_now",
        ("date", "today") => "__py_dt_today",
        ("datetime", "combine") => "__py_dt_combine",
        _ => return None,
    };
    Some(Expression::new(ExprKind::Call {
        callee: Box::new(Expression::ident(builtin)),
        args: args.to_vec(),
        optional: false,
    }))
}

fn parse_fixed_datetime(format: &str, value: &str) -> Option<Vec<Expression>> {
    let ints = match format {
        "%Y-%m-%d %H:%M" => {
            let (date, time) = value.split_once(' ')?;
            let mut d = date.split('-');
            let mut t = time.split(':');
            vec![
                d.next()?.parse::<i64>().ok()?,
                d.next()?.parse::<i64>().ok()?,
                d.next()?.parse::<i64>().ok()?,
                t.next()?.parse::<i64>().ok()?,
                t.next()?.parse::<i64>().ok()?,
                0,
            ]
        }
        "%d/%b/%Y:%H:%M:%S %z" => {
            let (main, _tz) = value.rsplit_once(' ')?;
            let parts: Vec<&str> = main.split(['/', ':']).collect();
            if parts.len() != 6 {
                return None;
            }
            let month = match parts[1] {
                "Jan" => 1,
                "Feb" => 2,
                "Mar" => 3,
                "Apr" => 4,
                "May" => 5,
                "Jun" => 6,
                "Jul" => 7,
                "Aug" => 8,
                "Sep" => 9,
                "Oct" => 10,
                "Nov" => 11,
                "Dec" => 12,
                _ => return None,
            };
            vec![
                parts[2].parse::<i64>().ok()?,
                month,
                parts[0].parse::<i64>().ok()?,
                parts[3].parse::<i64>().ok()?,
                parts[4].parse::<i64>().ok()?,
                parts[5].parse::<i64>().ok()?,
            ]
        }
        _ => return None,
    };
    Some(ints.into_iter().map(Expression::int).collect())
}

fn datetime_imported_attr(
    __w: &mut PyWalker,
    object: &Expression,
    field: &str,
) -> Option<Expression> {
    let ExprKind::Ident(type_name) = &object.kind else {
        return None;
    };
    if !imported_datetime_type(__w, type_name) {
        return None;
    }
    match (type_name.as_str(), field) {
        ("date" | "datetime", "min") => Some(call_ident("__py_date_min", Vec::new())),
        ("date" | "datetime", "max") => Some(call_ident("__py_date_max", Vec::new())),
        ("timezone", "utc") => Some(call_ident("__py_timezone_utc", Vec::new())),
        ("timedelta" | "datetime", "resolution") => {
            Some(call_ident("__py_timedelta_resolution", Vec::new()))
        }
        ("date", "resolution") => Some(call_ident("__py_timedelta_new", vec![Expression::int(1)])),
        _ => None,
    }
}

fn datetime_expr(__w: &mut PyWalker, e: &Expression) -> bool {
    match &e.kind {
        ExprKind::Ident(name) => is_datetime_var(__w, name),
        ExprKind::Call { callee, .. } => match &callee.kind {
            ExprKind::Ident(name) => matches!(
                name.as_str(),
                "__py_date_new"
                    | "__py_time_new"
                    | "__py_datetime_new"
                    | "__py_timedelta_new"
                    | "__py_timezone_new"
                    | "__py_date_fromisoformat"
                    | "__py_time_fromisoformat"
                    | "__py_datetime_fromisoformat"
                    | "__py_fromordinal"
                    | "__py_fromtimestamp"
                    | "__py_dt_now"
                    | "__py_dt_today"
                    | "__py_dt_combine"
                    | "__py_date_min"
                    | "__py_date_max"
                    | "__py_timezone_utc"
                    | "__py_timedelta_resolution"
                    | "__py_dt_replace"
                    | "__py_dt_date_method"
                    | "__py_dt_time_method"
            ),
            ExprKind::Member { object, field, .. } => module_namespace_path(__w, object)
                .as_deref()
                .is_some_and(|path| {
                    matches!(
                        (path, field.as_str()),
                        (
                            "datetime",
                            "date" | "time" | "datetime" | "timedelta" | "timezone"
                        ) | (
                            "datetime.date",
                            "fromordinal" | "fromtimestamp" | "fromisoformat" | "today"
                        ) | ("datetime.time", "fromisoformat")
                            | (
                                "datetime.datetime",
                                "fromordinal"
                                    | "fromtimestamp"
                                    | "fromisoformat"
                                    | "strptime"
                                    | "now"
                                    | "utcnow"
                                    | "today"
                                    | "combine"
                            )
                    )
                }),
            _ => false,
        },
        _ => false,
    }
}

fn rewrite_datetime_value_method(
    __w: &mut PyWalker,
    object: &Expression,
    field: &str,
    args: &[Argument],
) -> Option<Expression> {
    if !datetime_expr(__w, object) {
        return None;
    }
    let mut values = vec![desugar_member_reads(__w, object.clone())];
    values.extend(
        args.iter()
            .map(|a| desugar_member_reads(__w, a.value.clone())),
    );
    let call = |name: &str, values: Vec<Expression>| Some(call_ident(name, values));
    match field {
        "isoformat" if args.is_empty() => call("__py_dt_isoformat", values),
        "weekday" if args.is_empty() => call("__py_date_weekday", values),
        "isoweekday" if args.is_empty() => Some(Expression::new(ExprKind::Binary {
            op: BinOp::Add,
            left: Box::new(call_ident("__py_date_weekday", values)),
            right: Box::new(Expression::int(1)),
        })),
        "isocalendar" if args.is_empty() => {
            let recv = desugar_member_reads(__w, object.clone());
            let iso_weekday = Expression::new(ExprKind::Binary {
                op: BinOp::Add,
                left: Box::new(call_ident("__py_date_weekday", vec![recv.clone()])),
                right: Box::new(Expression::int(1)),
            });
            Some(Expression::new(ExprKind::Object(vec![
                ObjectProperty::KeyValue {
                    key: Expression::string("year"),
                    value: Expression::new(ExprKind::Index {
                        object: Box::new(recv.clone()),
                        index: Box::new(Expression::string("year")),
                        null_safe: false,
                    }),
                },
                ObjectProperty::KeyValue {
                    key: Expression::string("week"),
                    value: Expression::int(1),
                },
                ObjectProperty::KeyValue {
                    key: Expression::string("weekday"),
                    value: iso_weekday,
                },
            ])))
        }
        "total_seconds" if args.is_empty() => call("__py_total_seconds", values),
        "toordinal" if args.is_empty() => call("__py_toordinal", values),
        "timestamp" if args.is_empty() => call("__py_timestamp", values),
        "timetuple" | "utctimetuple" if args.is_empty() => call("__py_timetuple", values),
        "date" if args.is_empty() => call("__py_dt_date_method", values),
        "time" if args.is_empty() => call("__py_dt_time_method", values),
        "utcoffset" if args.len() <= 1 => call("__py_utcoffset", values),
        "astimezone" if args.len() == 1 => call("__py_astimezone", values),
        "tzname" if args.is_empty() => call("__py_tzname", values),
        _ => None,
    }
}

/// Default `json.dumps` separators: `(", ", ": ")` compact, `(",", ": ")` when
/// `indent` is given (matching CPython's `json` module).
fn json_default_separators(has_indent: bool) -> (Expression, Expression) {
    if has_indent {
        (Expression::string(","), Expression::string(": "))
    } else {
        (Expression::string(", "), Expression::string(": "))
    }
}

/// Reshape `json.dumps(obj, cls=…, default=…, sort_keys=…, indent=…,
/// separators=…)` into the fixed positional form
/// `__py_json_dumps(value, default, sort_keys, indent, item_sep, kv_sep)` the
/// Maps an `os.path.FUNC` name to its pure-Python prelude helper, for the
/// string-math functions the walker re-routes off the profile/host path.
/// Is `e` the module `os` (directly or via an alias)?
fn is_os_module_ident(__w: &mut PyWalker, e: &Expression) -> bool {
    matches!(&e.kind, ExprKind::Ident(n)
        if n == "os" || resolve_module_alias(__w, n).as_deref() == Some("os"))
}

/// `d.items()` → `[(p[0], p[1]) for p in __py_obj_entries__(d)]`. Python's
/// `dict.items()` yields (key, value) TUPLES, but `ecma:object.entries` returns
/// `[k, v]` LISTS. Building each pair as a tuple *literal* inside the
/// comprehension re-tags it (via the normal `ExprKind::Tuple` lowering), so
/// `list(d.items())` reprs as `[('a', 1)]` and `for k, v in d.items()` /
/// `dict(d.items())` still destructure the array backing. Entries is Map-aware,
/// so this is correct for the Map-backed dict.
fn rewrite_dict_items(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    if !args.is_empty() {
        return None;
    }
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if field != "items" {
        return None;
    }
    if !py_dict_like_expr(__w, object) {
        return None;
    }
    let entries = call_ident("__py_obj_entries__", vec![(**object).clone()]);
    let pair_index = |i: i64| {
        Expression::new(ExprKind::Index {
            object: Box::new(Expression::new(ExprKind::Ident("__item_pair".into()))),
            index: Box::new(Expression::int(i)),
            null_safe: false,
        })
    };
    let pair = Expression::new(ExprKind::Tuple(vec![pair_index(0), pair_index(1)]));
    Some(Expression::new(ExprKind::Comprehension {
        kind: ComprehensionKind::List,
        element: Box::new(pair),
        generators: vec![ComprehensionGen {
            target: Expression::new(ExprKind::Ident("__item_pair".into())),
            iter: entries,
            conditions: Vec::new(),
            is_async: false,
        }],
    }))
}

fn py_object_public_entries_dict_expr(object: Expression) -> Expression {
    let pair_ident = Expression::new(ExprKind::Ident("__py_obj_dict_pair".into()));
    let pair_index = |i: i64| {
        Expression::new(ExprKind::Index {
            object: Box::new(pair_ident.clone()),
            index: Box::new(Expression::int(i)),
            null_safe: false,
        })
    };
    let element = Expression::new(ExprKind::Array(vec![
        ArrayElement {
            key: None,
            spread: false,
            by_ref: false,
            value: pair_index(0),
        },
        ArrayElement {
            key: None,
            spread: false,
            by_ref: false,
            value: pair_index(1),
        },
    ]));
    let condition = Expression::new(ExprKind::Binary {
        op: BinOp::NotEq,
        left: Box::new(pair_index(0)),
        right: Box::new(Expression::string("constructor")),
    });
    Expression::new(ExprKind::Comprehension {
        kind: ComprehensionKind::Dict,
        element: Box::new(element),
        generators: vec![ComprehensionGen {
            target: pair_ident,
            iter: call_ident("__py_obj_entries__", vec![object]),
            conditions: vec![condition],
            is_async: false,
        }],
    })
}

/// `dict.fromkeys(keys[, value])` → `{__k: value for __k in keys}` (value
/// defaults to `None`). Reuses the dict-comprehension lowering (which builds a
/// Map), so the result is a real dict with the right keys/order — no separate
/// classmethod machinery needed.
/// `dict(...)` / `OrderedDict(...)` in a shape a dict LITERAL can express →
/// the literal node, which is what `{'a': 1}` already produces.
///
/// This is normalization, not lowering: the shared compiler carried an
/// `is_python_profile()` arm that rebuilt these three shapes by hand
/// (`primitives/calls.rs`), which also put the python-only NAMES `dict` and
/// `OrderedDict` in a shared crate. `OrderedDict` collapses to the same node
/// because ecma objects are insertion-ordered, which is exactly what that arm
/// said too.
///
/// Only the shapes a literal can represent are rewritten. `dict(other)`,
/// `dict(zip(a, b))` and a non-literal list argument fall through to the
/// ordinary call so the `dict` builtin still handles them.
fn rewrite_dict_construction(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    let ExprKind::Ident(name) = &callee.kind else {
        return None;
    };
    if name != "dict" && name != "OrderedDict" && name != "Counter" {
        return None;
    }
    if args.iter().any(|arg| arg.spread || arg.by_ref) {
        return None;
    }
    if name == "dict"
        && args.len() == 1
        && args[0].name.is_none()
        && is_counter_expr(__w, &args[0].value)
    {
        return Some(call_ident("__py_counter_dict", vec![args[0].value.clone()]));
    }

    // `Counter` is listed defensively and currently never arrives here — the
    // walker rewrites it upstream, so `Counter(a=1) + Counter(a=2)` keeps real
    // Counter semantics (verified byte-identical to python3). If that upstream
    // rewrite ever moves, this guard keeps the non-dict forms — iterable
    // `Counter([...])`, which COUNTS, and empty `Counter()` — off the literal
    // path, which would otherwise silently turn them into plain dicts.
    if name == "Counter" && (args.is_empty() || args.iter().any(|arg| arg.name.is_none())) {
        return None;
    }

    // `dict()` (vacuously all-named) and `dict(a=1, b=2)`.
    if args.iter().all(|arg| arg.name.is_some()) {
        let props = args
            .iter()
            .map(|arg| ObjectProperty::KeyValue {
                key: Expression::new(ExprKind::Lit(Literal::Str(
                    arg.name.clone().unwrap().into(),
                ))),
                value: arg.value.clone(),
            })
            .collect();
        return Some(Expression::new(ExprKind::Object(props)));
    }

    // `dict([('x', 9), ('y', 8)])` — a LITERAL list of 2-tuples only.
    if args.len() == 1 && args[0].name.is_none() {
        if let ExprKind::Array(elements) = &args[0].value.kind {
            let mut props = Vec::with_capacity(elements.len());
            for element in elements {
                if element.spread || element.key.is_some() {
                    return None;
                }
                let ExprKind::Tuple(items) = &element.value.kind else {
                    return None;
                };
                if items.len() != 2 {
                    return None;
                }
                props.push(ObjectProperty::KeyValue {
                    key: items[0].clone(),
                    value: items[1].clone(),
                });
            }
            return Some(Expression::new(ExprKind::Object(props)));
        }
    }

    None
}

fn rewrite_optparse_add_option_call(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if field != "add_option" {
        return None;
    }
    if !matches!(
        py_receiver_class(__w, object).as_deref(),
        Some("OptionParser" | "OptionGroup")
    ) {
        return None;
    }
    let positional: Vec<&Argument> = args
        .iter()
        .filter(|arg| arg.name.is_none() && !arg.spread && !arg.by_ref)
        .collect();
    if positional.len() <= 1 {
        return None;
    }
    if positional.iter().any(|arg| {
        !matches!(
            &arg.value.kind,
            ExprKind::Lit(Literal::Str(flag)) if flag.starts_with('-')
        )
    }) {
        return None;
    }

    let flag_list = Expression::new(ExprKind::Array(
        positional
            .iter()
            .map(|arg| ArrayElement {
                key: None,
                value: arg.value.clone(),
                spread: false,
                by_ref: false,
            })
            .collect(),
    ));
    let mut rewritten_args = vec![Argument::positional(flag_list)];
    rewritten_args.extend(args.iter().filter(|arg| arg.name.is_some()).cloned());

    Some(Expression::new(ExprKind::Call {
        callee: Box::new(callee.clone()),
        args: rewritten_args,
        optional: false,
    }))
}

fn rewrite_dict_fromkeys(callee: &Expression, args: &[Argument]) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if field != "fromkeys" || !matches!(&object.kind, ExprKind::Ident(n) if n == "dict") {
        return None;
    }
    if args.is_empty() || args.iter().any(|a| a.name.is_some() || a.spread) {
        return None;
    }
    let keys = args[0].value.clone();
    let value = args
        .get(1)
        .map(|a| a.value.clone())
        .unwrap_or_else(|| Expression::new(ExprKind::Lit(Literal::Null)));
    // Dict-comprehension element is a 2-element Array [key, value] (the shape
    // the compiler unpacks), NOT a Tuple.
    let kv = |k: Expression, v: Expression| {
        Expression::new(ExprKind::Array(vec![
            ArrayElement {
                key: None,
                spread: false,
                by_ref: false,
                value: k,
            },
            ArrayElement {
                key: None,
                spread: false,
                by_ref: false,
                value: v,
            },
        ]))
    };
    Some(Expression::new(ExprKind::Comprehension {
        kind: ComprehensionKind::Dict,
        element: Box::new(kv(
            Expression::new(ExprKind::Ident("__fk_key".into())),
            value,
        )),
        generators: vec![ComprehensionGen {
            target: Expression::new(ExprKind::Ident("__fk_key".into())),
            iter: keys,
            conditions: Vec::new(),
            is_async: false,
        }],
    }))
}

/// `random.NAME(args)` → `__py_random_NAME(args)` for the names that are not
/// reliably host-backed. `random`/`choice`/`shuffle`/`sample`/`seed`
/// stay profile builtins. `randint`, `randrange`, and `choices` are arity-shaped here so
/// the prelude helpers stay fixed-arity (no default-binding assumptions).
fn rewrite_random_call(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    let is_random = matches!(&object.kind, ExprKind::Ident(n)
        if n == "random" || resolve_module_alias(__w, n).as_deref() == Some("random"));
    if !is_random {
        return None;
    }
    let call = |helper: &str, args: Vec<Argument>| {
        Some(Expression::new(ExprKind::Call {
            callee: Box::new(Expression::new(ExprKind::Ident(helper.to_string()))),
            args,
            optional: false,
        }))
    };
    match field.as_str() {
        // Fixed-arity variates: forward positional args verbatim.
        "randint" | "uniform" | "expovariate" | "gauss" | "normalvariate" | "lognormvariate"
        | "triangular" | "paretovariate" | "weibullvariate" | "vonmisesvariate"
        | "gammavariate" | "betavariate" | "getrandbits" | "randbytes" | "getstate"
        | "setstate" => {
            call(&format!("__py_random_{field}"), args.to_vec())
        }
        // `randrange(stop)` / `(start, stop)` / `(start, stop, step)` → always
        // three positional args to the helper.
        "randrange" => {
            let pos: Vec<Expression> = args
                .iter()
                .filter(|a| a.name.is_none())
                .map(|a| a.value.clone())
                .collect();
            let (start, stop, step) = match pos.len() {
                1 => (Expression::int(0), pos[0].clone(), Expression::int(1)),
                2 => (pos[0].clone(), pos[1].clone(), Expression::int(1)),
                3 => (pos[0].clone(), pos[1].clone(), pos[2].clone()),
                _ => return None,
            };
            call(
                "__py_random_randrange",
                vec![
                    Argument::positional(start),
                    Argument::positional(stop),
                    Argument::positional(step),
                ],
            )
        }
        // `choices(pop, weights=, cum_weights=, k=)` → four positional args.
        "choices" => {
            let mut kw = |name: &str| {
                args.iter()
                    .find(|a| a.name.as_deref() == Some(name))
                    .map(|a| a.value.clone())
            };
            let pop = args.iter().find(|a| a.name.is_none())?.value.clone();
            let weights = kw("weights").unwrap_or_else(Expression::null);
            let cum = kw("cum_weights").unwrap_or_else(Expression::null);
            let k = kw("k").unwrap_or_else(|| Expression::int(1));
            call(
                "__py_random_choices",
                vec![
                    Argument::positional(pop),
                    Argument::positional(weights),
                    Argument::positional(cum),
                    Argument::positional(k),
                ],
            )
        }
        _ => None,
    }
}

/// Literal `pickle.loads`/`marshal.loads` errors we can normalize before the
/// adapter sees runtime values.
fn rewrite_pickle_marshal_loads(callee: &Expression, args: &[Argument]) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if field != "loads" {
        return None;
    }
    let ExprKind::Ident(module) = &object.kind else {
        return None;
    };
    if !matches!(module.as_str(), "pickle" | "marshal") {
        return None;
    }
    let value = args.iter().find(|a| a.name.is_none())?.value.clone();
    match &value.kind {
        ExprKind::Lit(Literal::Str(_)) => Some(py_raise_expr(
            "TypeError",
            Some("a bytes-like object is required"),
        )),
        ExprKind::Lit(Literal::Bytes(bytes)) if bytes.is_empty() => {
            Some(py_raise_expr("EOFError", Some("Ran out of input")))
        }
        _ => None,
    }
}

fn normalize_python_deepcopy_known_fields(__w: &mut PyWalker, expr: &mut Expression) {
    let Some(arg0) = (match &expr.kind {
        ExprKind::Call { callee, args, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_copy_deepcopy")
                && !args.is_empty()
                && args.len() <= 2 =>
        {
            Some(args[0].value.clone())
        }
        _ => None,
    }) else {
        return;
    };

    let class_name = match &arg0.kind {
        ExprKind::Ident(var) => instance_class(__w, var),
        _ => constructed_class_name(__w, &arg0).map(str::to_string),
    };
    let Some(class_name) = class_name else {
        return;
    };
    if class_has_attr(__w, &class_name, "__deepcopy__") {
        return;
    }
    if let ExprKind::Ident(var) = &arg0.kind
        && let Some(init) = instance_init_expr(__w, var)
    {
        *expr = python_deep_clone_expr(__w, &init);
        return;
    }
    let fields = class_data_attrs_for(__w, &class_name);
    if fields.is_empty() {
        return;
    }
    let field_names = python_field_names_array(fields);
    let ExprKind::Call { callee, args, .. } = &mut expr.kind else {
        return;
    };
    if args.len() == 1 {
        args.push(Argument::positional(Expression::null()));
    }
    args.push(Argument::positional(field_names));
    *callee = Box::new(Expression::ident("__py_copy_deepcopy_fields"));
}

fn python_deep_clone_expr(__w: &mut PyWalker, expr: &Expression) -> Expression {
    match &expr.kind {
        ExprKind::Array(elements) => Expression::new(ExprKind::Array(
            elements
                .iter()
                .map(|element| ArrayElement {
                    key: element
                        .key
                        .as_ref()
                        .map(|key| python_deep_clone_expr(__w, key)),
                    spread: element.spread,
                    by_ref: element.by_ref,
                    value: python_deep_clone_expr(__w, &element.value),
                })
                .collect(),
        )),
        ExprKind::Tuple(items) => Expression::new(ExprKind::Tuple(
            items
                .iter()
                .map(|item| python_deep_clone_expr(__w, item))
                .collect(),
        )),
        ExprKind::Sequence(items) => Expression::new(ExprKind::Sequence(
            items
                .iter()
                .map(|item| python_deep_clone_expr(__w, item))
                .collect(),
        )),
        ExprKind::Set(items) => Expression::new(ExprKind::Set(
            items
                .iter()
                .map(|item| python_deep_clone_expr(__w, item))
                .collect(),
        )),
        ExprKind::Map(entries) => Expression::new(ExprKind::Map(
            entries
                .iter()
                .map(|(key, value)| {
                    (
                        python_deep_clone_expr(__w, key),
                        python_deep_clone_expr(__w, value),
                    )
                })
                .collect(),
        )),
        ExprKind::Object(props) => Expression::new(ExprKind::Object(
            props
                .iter()
                .map(|prop| match prop {
                    ObjectProperty::KeyValue { key, value } => ObjectProperty::KeyValue {
                        key: python_deep_clone_expr(__w, key),
                        value: python_deep_clone_expr(__w, value),
                    },
                    ObjectProperty::Computed { key, value } => ObjectProperty::Computed {
                        key: python_deep_clone_expr(__w, key),
                        value: python_deep_clone_expr(__w, value),
                    },
                    ObjectProperty::Spread(value) => {
                        ObjectProperty::Spread(python_deep_clone_expr(__w, value))
                    }
                    ObjectProperty::Shorthand(name) => ObjectProperty::Shorthand(name.clone()),
                    ObjectProperty::Method { key, value } => ObjectProperty::Method {
                        key: key.clone(),
                        value: value.clone(),
                    },
                    ObjectProperty::Accessor { kind, key, value } => ObjectProperty::Accessor {
                        kind: *kind,
                        key: key.clone(),
                        value: value.clone(),
                    },
                })
                .collect(),
        )),
        ExprKind::New { class, args } => {
            let class_name = match &class.kind {
                ExprKind::Ident(name) => Some(name.as_str()),
                _ => None,
            };
            let cloned = Expression::new(ExprKind::New {
                class: class.clone(),
                args: args
                    .iter()
                    .map(|arg| Argument {
                        name: arg.name.clone(),
                        value: python_deep_clone_expr(__w, &arg.value),
                        by_ref: arg.by_ref,
                        spread: arg.spread,
                    })
                    .collect(),
            });
            class_name
                .filter(|name| !class_has_attr(__w, name, "__deepcopy__"))
                .map(|name| {
                    let fields = class_data_attrs_for(__w, name);
                    if fields.is_empty() {
                        cloned.clone()
                    } else {
                        call_ident(
                            "__py_copy_stamp_fields",
                            vec![cloned.clone(), python_field_names_array(fields)],
                        )
                    }
                })
                .unwrap_or(cloned)
        }
        ExprKind::Call { callee, args, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_copy_stamp_fields")
                && !args.is_empty() =>
        {
            let value = python_deep_clone_expr(__w, &args[0].value);
            let fields = args
                .get(1)
                .map(|arg| arg.value.clone())
                .unwrap_or_else(|| Expression::new(ExprKind::Array(Vec::new())));
            call_ident("__py_copy_stamp_fields", vec![value, fields])
        }
        _ => call_ident("__py_copy_deepcopy", vec![expr.clone(), Expression::null()]),
    }
}

fn rewrite_tomllib_call(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if module_namespace_path(__w, object).as_deref() != Some("tomllib") {
        return None;
    }
    let parse_float_decimal = args.iter().any(|arg| {
        arg.name.as_deref() == Some("parse_float")
            && matches!(&arg.value.kind, ExprKind::Ident(name) if name == "Decimal")
    });
    let text = match field.as_str() {
        "loads" => tomllib_loads_text(__w, args)?,
        "load" => tomllib_load_text(__w, args)?,
        _ => return None,
    };
    match text.parse::<toml::Table>() {
        Ok(value) => Some(toml_value_expr(
            toml::Value::Table(value),
            parse_float_decimal,
        )),
        Err(err) => Some(py_raise_expr("TOMLDecodeError", Some(&err.to_string()))),
    }
}

fn tomllib_loads_text(__w: &mut PyWalker, args: &[Argument]) -> Option<String> {
    let first = args.iter().find(|arg| arg.name.is_none())?;
    resolve_string_const(__w, &first.value)
}

fn tomllib_load_text(__w: &mut PyWalker, args: &[Argument]) -> Option<String> {
    let first = args.iter().find(|arg| arg.name.is_none())?;
    tomllib_bytesio_text(__w, &first.value)
}

fn tomllib_bytesio_text(__w: &mut PyWalker, expr: &Expression) -> Option<String> {
    let ExprKind::New { class, args } = &expr.kind else {
        return None;
    };
    if !matches!(&class.kind, ExprKind::Ident(name) if name == "BytesIO") {
        return None;
    }
    let bytes = args
        .first()
        .and_then(|arg| tomllib_bytes_expr(__w, &arg.value))?;
    String::from_utf8(bytes).ok()
}

fn tomllib_bytes_expr(__w: &mut PyWalker, expr: &Expression) -> Option<Vec<u8>> {
    match &expr.kind {
        ExprKind::Lit(Literal::Bytes(bytes)) => Some(bytes.clone()),
        ExprKind::Ident(name) => bytes_const(__w, name),
        _ => None,
    }
}

fn toml_value_expr(value: toml::Value, parse_float_decimal: bool) -> Expression {
    match value {
        toml::Value::String(value) => Expression::string(&value),
        toml::Value::Integer(value) => Expression::int(value),
        toml::Value::Float(value) if parse_float_decimal => Expression::new(ExprKind::New {
            class: Box::new(Expression::ident("Decimal")),
            args: vec![Argument::positional(Expression::string(&value.to_string()))],
        }),
        toml::Value::Float(value) => Expression::float(value),
        toml::Value::Boolean(value) => Expression::new(ExprKind::Lit(Literal::Bool(value))),
        toml::Value::Datetime(value) => toml_datetime_expr(&value.to_string()),
        toml::Value::Array(values) => Expression::new(ExprKind::Array(
            values
                .into_iter()
                .map(|value| ArrayElement {
                    key: None,
                    spread: false,
                    by_ref: false,
                    value: toml_value_expr(value, parse_float_decimal),
                })
                .collect(),
        )),
        toml::Value::Table(values) if parse_float_decimal => Expression::new(ExprKind::Object(
            values
                .into_iter()
                .map(|(key, value)| ObjectProperty::KeyValue {
                    key: Expression::string(&key),
                    value: toml_value_expr(value, parse_float_decimal),
                })
                .collect(),
        )),
        toml::Value::Table(values) => Expression::new(ExprKind::Map(
            values
                .into_iter()
                .map(|(key, value)| {
                    (
                        Expression::string(&key),
                        toml_value_expr(value, parse_float_decimal),
                    )
                })
                .collect(),
        )),
    }
}

fn toml_datetime_expr(text: &str) -> Expression {
    let callee = if text.contains('T') || text.contains('t') {
        "__py_datetime_fromisoformat"
    } else if text.contains(':') {
        "__py_time_fromisoformat"
    } else {
        "__py_date_fromisoformat"
    };
    call_ident(callee, vec![Expression::string(text)])
}

fn constructed_class_name<'a>(__w: &mut PyWalker, expr: &'a Expression) -> Option<&'a str> {
    match &expr.kind {
        ExprKind::New { class, .. } => match &class.kind {
            ExprKind::Ident(name) if is_defined_class(__w, name) => Some(name.as_str()),
            _ => None,
        },
        ExprKind::Call { callee, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if is_defined_class(__w, name)) =>
        {
            if let ExprKind::Ident(name) = &callee.kind {
                Some(name.as_str())
            } else {
                None
            }
        }
        ExprKind::Call { callee, .. }
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "slice" || name == "__py_slice_new") =>
        {
            Some("slice")
        }
        ExprKind::Call { callee, args, .. } if matches!(&callee.kind, ExprKind::Ident(name) if name == "__py_copy_stamp_fields") => {
            args.first()
                .and_then(|arg| constructed_class_name(__w, &arg.value))
        }
        ExprKind::Call { callee, args, .. }
            if args.is_empty()
                && matches!(&callee.kind, ExprKind::Ident(name) if name == "copy_context") =>
        {
            Some("Context")
        }
        _ => None,
    }
}

fn known_core_method_return_class(__w: &mut PyWalker, expr: &Expression) -> Option<&'static str> {
    let ExprKind::Call { callee, .. } = &expr.kind else {
        return None;
    };
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    let receiver = py_receiver_class(__w, object)?;
    Some(match (receiver.as_str(), field.as_str()) {
        ("ArgumentParser", "parse_args") => "Namespace",
        (
            "ArgumentParser",
            "add_argument_group" | "add_mutually_exclusive_group",
        ) => "__ArgparseGroup",
        ("ArgumentParser", "add_subparsers") => "__ArgparseSubparsers",
        ("__ArgparseSubparsers", "add_parser") => "ArgumentParser",
        ("SelectSelector", "register" | "unregister" | "modify" | "get_key")
        | ("EpollSelector", "register" | "unregister" | "modify" | "get_key")
        | ("KqueueSelector", "register" | "unregister" | "modify" | "get_key")
        | ("PollSelector", "register" | "unregister" | "modify" | "get_key")
        | ("DevpollSelector", "register" | "unregister" | "modify" | "get_key") => "SelectorKey",
        _ => return None,
    })
}

fn class_allows_dynamic_attrs(class_name: &str) -> bool {
    crate::core_classes::DYNAMIC_ATTR_CLASSES
        .iter()
        .any(|name| *name == class_name)
}

fn python_field_names_array(fields: Vec<String>) -> Expression {
    Expression::new(ExprKind::Array(
        fields
            .into_iter()
            .map(|field| ArrayElement {
                key: None,
                spread: false,
                by_ref: false,
                value: Expression::string(&field),
            })
            .collect(),
    ))
}

/// json adapter consumes. Returns `None` for anything that isn't a
/// `json.dumps`-shaped call so normal handling proceeds.
fn rewrite_json_dumps(callee: &Expression, args: &[Argument]) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if field != "dumps" {
        return None;
    }
    if !matches!(&object.kind, ExprKind::Ident(n) if n == "json") {
        return None;
    }

    let value = args.iter().find(|a| a.name.is_none())?.value.clone();
    let kw = |name: &str| {
        args.iter()
            .find(|a| a.name.as_deref() == Some(name))
            .map(|a| a.value.clone())
    };

    // Encoder hook: `default=` wins, else `cls=` → `lambda __o: Cls().default(__o)`.
    let default_expr = if let Some(d) = kw("default") {
        d
    } else if let Some(cls) = kw("cls") {
        let inst = Expression::new(ExprKind::New {
            class: Box::new(cls),
            args: vec![],
        });
        let call = Expression::new(ExprKind::Call {
            callee: Box::new(Expression::new(ExprKind::Member {
                object: Box::new(inst),
                field: "default".into(),
                null_safe: false,
            })),
            args: vec![Argument::positional(Expression::new(ExprKind::Ident(
                "__o".into(),
            )))],
            optional: false,
        });
        Expression::new(ExprKind::Lambda {
            params: vec![lambda_param("__o")],
            body: LambdaBody::Expr(Box::new(call)),
            is_async: false,
            captures: vec![],
        })
    } else {
        Expression::null()
    };

    let sort_keys =
        kw("sort_keys").unwrap_or_else(|| Expression::new(ExprKind::Lit(Literal::Bool(false))));
    let indent = kw("indent").unwrap_or_else(Expression::null);

    let (item_sep, kv_sep) = match kw("separators") {
        Some(sep) => match &sep.kind {
            ExprKind::Tuple(items) if items.len() == 2 => (items[0].clone(), items[1].clone()),
            _ => json_default_separators(kw("indent").is_some()),
        },
        None => json_default_separators(kw("indent").is_some()),
    };

    Some(Expression::new(ExprKind::Call {
        callee: Box::new(Expression::new(ExprKind::Ident("__py_json_dumps".into()))),
        args: vec![
            Argument::positional(value),
            Argument::positional(default_expr),
            Argument::positional(sort_keys),
            Argument::positional(indent),
            Argument::positional(item_sep),
            Argument::positional(kv_sep),
        ],
        optional: false,
    }))
}

fn call_or_new(__w: &mut PyWalker, callee: Expression, args: Vec<Argument>) -> ExprKind {
    let callee = match &callee.kind {
        ExprKind::Ident(name) => py_class_alias(__w, name)
            .map(|class_name| Expression::ident(&class_name))
            .unwrap_or(callee),
        _ => callee,
    };
    if let Some(kind) = zoneinfo_call(__w, &callee, &args) {
        return kind;
    }
    if let Some(kind) = functools_call_lowering(&callee, &args) {
        return kind;
    }
    if let Some(kind) = imported_datetime_ctor_call(__w, &callee, args.clone()) {
        return kind;
    }
    if let Some(kind) = datetime_replace_call(&callee, &args) {
        return kind;
    }
    if let Some(kind) = strftime_expand(&callee, &args) {
        return kind;
    }
    if let Some(kind) = time_strftime_expand(__w, &callee, &args) {
        return kind;
    }
    if let Some(kind) = time_module_call(__w, &callee, &args) {
        return kind;
    }
    if let Some(params) = datetime_kwarg_signature(__w, &callee) {
        let args = normalize_datetime_kwargs(params, args);
        return ExprKind::Call {
            callee: Box::new(callee),
            args,
            optional: false,
        };
    }
    if let ExprKind::Ident(name) = &callee.kind {
        if let Some(def) = namedtuple_def(__w, name) {
            return build_namedtuple_construction(&def, args);
        }
        if is_defined_class(__w, name) {
            let args = normalize_contextvar_ctor_args(__w, &callee, &args).unwrap_or(args);
            if let Some(limit) = dataclass_positional_limit(__w, name) {
                let positional = args.iter().filter(|arg| arg.name.is_none()).count();
                if positional > limit {
                    return py_raise_expr("TypeError", Some("too many positional arguments")).kind;
                }
            }
            if is_callable_class(__w, name) && !class_has_init(__w, name) && !args.is_empty() {
                return ExprKind::Call {
                    callee: Box::new(Expression::new(ExprKind::Member {
                        object: Box::new(Expression::new(ExprKind::New {
                            class: Box::new(callee),
                            args: Vec::new(),
                        })),
                        field: "__call__".into(),
                        null_safe: false,
                    })),
                    args,
                    optional: false,
                };
            }
            return ExprKind::New {
                class: Box::new(callee),
                args,
            };
        }
    }
    // Inline `namedtuple('P', 'a b')(1, 2)` — the callee is the factory call.
    if let Some(def) = parse_namedtuple_call(&callee) {
        return build_namedtuple_construction(&def, args);
    }
    ExprKind::Call {
        callee: Box::new(callee),
        args,
        optional: false,
    }
}

/// Root identifier at the base of a member/index/call chain.
fn expr_root_ident(e: &Expression) -> Option<String> {
    match &e.kind {
        ExprKind::Ident(n) => Some(n.clone()),
        ExprKind::Member { object, .. } => expr_root_ident(object),
        ExprKind::Index { object, .. } => expr_root_ident(object),
        ExprKind::Call { callee, .. } => expr_root_ident(callee),
        _ => None,
    }
}

/// True while an expression still denotes a module namespace: the import
/// root reached through nothing but attribute hops (`importlib.metadata`).
/// A `Call` or subscript anywhere in the chain produces an ordinary value,
/// so the namespace ends there.
fn is_module_namespace_path(__w: &mut PyWalker, e: &Expression) -> bool {
    module_namespace_path(__w, e).is_some()
}

/// The dotted path of a module namespace expression, module-aliases
/// resolved (`md.version` where `import importlib.metadata as md` →
/// `importlib.metadata.version`). `None` once anything but an attribute
/// hop appears.
fn module_namespace_path(__w: &mut PyWalker, e: &Expression) -> Option<String> {
    match &e.kind {
        ExprKind::Ident(n) => {
            let module = resolve_module_alias(__w, n).unwrap_or_else(|| n.clone());
            (is_imported_module(__w, n) || py_module_surface(&module).is_some()).then_some(module)
        }
        ExprKind::Member { object, field, .. } => {
            Some(format!("{}.{}", module_namespace_path(__w, object)?, field))
        }
        _ => None,
    }
}

/// `calendar.month_name` / `calendar.day_name` — fixed, indexable name
/// tables. They are constants, so the walker materializes them directly
/// rather than routing a lookup through the emitter. `month_name[0]` is
/// empty because CPython's month numbering is 1-based.
fn calendar_name_table(path: &str) -> Option<&'static [&'static str]> {
    Some(match path {
        "calendar.month_name" => &[
            "",
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
        ],
        "calendar.month_abbr" => &[
            "", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
        ],
        "calendar.day_name" => &[
            "Monday",
            "Tuesday",
            "Wednesday",
            "Thursday",
            "Friday",
            "Saturday",
            "Sunday",
        ],
        "calendar.day_abbr" => &["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
        _ => return None,
    })
}

fn calendar_module_attr(path: &str) -> Option<Expression> {
    match path {
        "calendar.MONDAY" => Some(Expression::int(0)),
        "calendar.TUESDAY" => Some(Expression::int(1)),
        "calendar.WEDNESDAY" => Some(Expression::int(2)),
        "calendar.THURSDAY" => Some(Expression::int(3)),
        "calendar.FRIDAY" => Some(Expression::int(4)),
        "calendar.SATURDAY" => Some(Expression::int(5)),
        "calendar.SUNDAY" => Some(Expression::int(6)),
        "calendar.mdays" => Some(Expression::new(ExprKind::Array(
            [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
                .iter()
                .map(|d| ArrayElement {
                    value: Expression::int(*d),
                    spread: false,
                    key: None,
                    by_ref: false,
                })
                .collect(),
        ))),
        _ => None,
    }
}

fn rewrite_calendar_call(
    __w: &mut PyWalker,
    callee: &Expression,
    args: &[Argument],
) -> Option<Expression> {
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if module_namespace_path(__w, object).as_deref() != Some("calendar") {
        return None;
    }
    let name = match field.as_str() {
        "Calendar" => "__py_calendar_new",
        "TextCalendar" => "__py_calendar_text_new",
        "HTMLCalendar" => "__py_calendar_html_new",
        "leapdays" => "__py_calendar_leapdays",
        "timegm" => "__py_calendar_timegm",
        "monthcalendar" => "__py_calendar_monthcalendar",
        "setfirstweekday" => "__py_calendar_setfirstweekday",
        "firstweekday" => "__py_calendar_firstweekday_fn",
        "month" => "__py_calendar_text_formatmonth",
        "prmonth" => {
            let printed = Expression::new(ExprKind::Call {
                callee: Box::new(Expression::ident("__py_calendar_text_formatmonth")),
                args: args.to_vec(),
                optional: false,
            });
            return Some(Expression::new(ExprKind::Call {
                callee: Box::new(Expression::ident("print")),
                args: normalize_python_print_args(__w, vec![Argument::positional(printed)]),
                optional: false,
            }));
        }
        _ => return None,
    };
    Some(Expression::new(ExprKind::Call {
        callee: Box::new(Expression::ident(name)),
        args: args.to_vec(),
        optional: false,
    }))
}

fn calendar_expr_kind(expr: &Expression) -> Option<&'static str> {
    let ExprKind::Call { callee, .. } = &expr.kind else {
        return None;
    };
    let ExprKind::Ident(name) = &callee.kind else {
        return None;
    };
    Some(match name.as_str() {
        "__py_calendar_new" => "Calendar",
        "__py_calendar_text_new" => "TextCalendar",
        "__py_calendar_html_new" => "HTMLCalendar",
        _ => return None,
    })
}

fn rewrite_calendar_value_method(
    __w: &mut PyWalker,
    object: &Expression,
    field: &str,
    args: &[Argument],
) -> Option<Expression> {
    let kind = match &object.kind {
        ExprKind::Ident(name) => calendar_var_kind(__w, name)?,
        ExprKind::Call { .. } => calendar_expr_kind(object)?.to_string(),
        _ => return None,
    };
    let name = match field {
        "itermonthdays" | "itermonthdates" => "__py_calendar_itermonthdays",
        "itermonthdays2" => "__py_calendar_itermonthdays2",
        "monthdayscalendar" => "__py_calendar_monthcalendar",
        "yeardayscalendar" => "__py_calendar_yeardayscalendar",
        "formatmonth" if kind == "HTMLCalendar" => "__py_calendar_html_formatmonth",
        "formatmonth" => "__py_calendar_text_formatmonth",
        "prmonth" => {
            let format_name = if kind == "HTMLCalendar" {
                "__py_calendar_html_formatmonth"
            } else {
                "__py_calendar_text_formatmonth"
            };
            let printed = Expression::new(ExprKind::Call {
                callee: Box::new(Expression::ident(format_name)),
                args: args.to_vec(),
                optional: false,
            });
            return Some(Expression::new(ExprKind::Call {
                callee: Box::new(Expression::ident("print")),
                args: normalize_python_print_args(__w, vec![Argument::positional(printed)]),
                optional: false,
            }));
        }
        _ => return None,
    };
    Some(Expression::new(ExprKind::Call {
        callee: Box::new(Expression::ident(name)),
        args: args.to_vec(),
        optional: false,
    }))
}

/// The adapter's `__type` tag for a `datetime` type *reference* — the
/// second argument of `isinstance(x, datetime.date)`. Mirrors the tags
/// `emitter::datetime_adapter` stamps.
fn datetime_type_tag(__w: &mut PyWalker, e: &Expression) -> Option<&'static str> {
    let path = module_namespace_path(__w, e)?;
    Some(match path.as_str() {
        "datetime.date" => "date",
        "datetime.time" => "time",
        "datetime.datetime" => "datetime",
        "datetime.timedelta" => "timedelta",
        "datetime.timezone" => "timezone",
        _ => return None,
    })
}

/// `datetime` class attributes that hold *constructed* values rather than
/// scalars, which a `namespace_constants` entry cannot express. Each maps
/// to a zero-arg builtin the adapter materializes.
fn datetime_attr_builtin(path: &str) -> Option<&'static str> {
    Some(match path {
        "datetime.date.min" | "datetime.datetime.min" => "__py_date_min",
        "datetime.date.max" | "datetime.datetime.max" => "__py_date_max",
        "datetime.timezone.utc" => "__py_timezone_utc",
        "datetime.timedelta.resolution" => "__py_timedelta_resolution",
        _ => return None,
    })
}

